static void sgWriteFile(const std::wstring& path, const std::string& content) {
    std::ofstream f(path, std::ios::binary);
    if (f) f.write(content.data(), (std::streamsize)content.size());
}
// 原子写：同目录唯一临时文件 + 分片路径锁 + 全量 WriteFile/FlushFileBuffers 校验。
// 每个成功返回只提交本次调用自己的内容；任何短写/刷盘/替换失败均保留原文件。
bool sgWriteFileAtomicFlags(const std::wstring& path, const std::string& content, bool durable) {
    static std::mutex pathLocks[32];
    static std::atomic<unsigned long long> tempSeq{1};

    std::wstring lockKey = path;
    std::transform(lockKey.begin(), lockKey.end(), lockKey.begin(), ::towlower);
    std::lock_guard<std::mutex> pathLock(pathLocks[std::hash<std::wstring>{}(lockKey) % 32]);

    const auto seq = tempSeq.fetch_add(1);
    std::wstring tmp = path + L".ymcc." + std::to_wstring(GetCurrentProcessId()) +
        L"." + std::to_wstring(seq) + L".tmp";
    // C-B1（155 §3.2）：durable 走强制落盘三件套（WRITE_THROUGH + Flush +
    // MOVEFILE/REPLACEFILE WRITE_THROUGH）；transient 去掉强刷盘，但保留同目录
    // 唯一临时文件、路径锁、完整写入与 CloseHandle 错误检查、替换重试/失败保留
    // 旧文件、generation 和时间戳。去掉强刷盘 ≠ 去掉原子替换。
    const DWORD createFlags = durable ? (FILE_ATTRIBUTE_NORMAL | FILE_FLAG_WRITE_THROUGH)
                                      : FILE_ATTRIBUTE_NORMAL;
    HANDLE file = CreateFileW(tmp.c_str(), GENERIC_WRITE, 0, nullptr, CREATE_NEW, createFlags, nullptr);
    if (file == INVALID_HANDLE_VALUE) return false;

    bool writeOk = true;
    size_t offset = 0;
    while (offset < content.size()) {
        const size_t remaining = content.size() - offset;
        const DWORD chunk = static_cast<DWORD>((std::min)(remaining, static_cast<size_t>(1u << 20)));
        DWORD written = 0;
        if (!WriteFile(file, content.data() + offset, chunk, &written, nullptr) || written != chunk) {
            writeOk = false;
            break;
        }
        offset += written;
    }
    if (durable && writeOk && !FlushFileBuffers(file)) writeOk = false;
    if (!CloseHandle(file)) writeOk = false;
    if (!writeOk) {
        DeleteFileW(tmp.c_str());
        return false;
    }

    // 1) 首选 MoveFileEx（原子替换）。目标可能被 RTSS 钩子短暂占用 → 重试。
    const DWORD moveFlags = durable
        ? (MOVEFILE_REPLACE_EXISTING | MOVEFILE_WRITE_THROUGH)
        : MOVEFILE_REPLACE_EXISTING;
    for (int attempt = 0; attempt < 6; attempt++) {
        if (MoveFileExW(tmp.c_str(), path.c_str(), moveFlags))
            return true;
        if (attempt < 5) Sleep(50);
    }
    // 2) 退路 ReplaceFileW。仍失败时原文件保持完整，只删除本次调用自己的临时文件。
    const DWORD replaceFlags = durable ? REPLACEFILE_WRITE_THROUGH : 0;
    if (ReplaceFileW(path.c_str(), tmp.c_str(), nullptr, replaceFlags, nullptr, 0))
        return true;
    DeleteFileW(tmp.c_str());
    return false;
}

static bool sgWriteFileAtomic(const std::wstring& path, const std::string& content) {
    // 默认保持既有持久化语义（durable）。monitor 展示快照显式改走 transient。
    return sgWriteFileAtomicFlags(path, content, true);
}

static bool sgWriteFileAtomicTransient(const std::wstring& path, const std::string& content) {
    return sgWriteFileAtomicFlags(path, content, false);
}

static void signalUpdateHandshake() {
    if (g_updateHandshakePath.empty() || g_updateHandshakeToken.empty()) return;
    json marker = {
        {"phase", "started"},
        {"pid", GetCurrentProcessId()},
        {"token", g_updateHandshakeToken}
    };
    if (!sgWriteFileAtomic(g_updateHandshakePath, marker.dump())) {
        traceLog("UPDATE handshake marker write failed");
    }
}

static std::string sgReadFile(const std::wstring& path) {
    std::ifstream f(path, std::ios::binary);
    if (!f) return {};
    std::string content((std::istreambuf_iterator<char>(f)), std::istreambuf_iterator<char>());
    // PowerShell and common Windows editors write UTF-8 JSON with a BOM.
    // nlohmann::json does not accept that prefix, so normalize it at the one
    // shared file-read boundary used by sleep/settings markers.
    if (content.size() >= 3 &&
        static_cast<unsigned char>(content[0]) == 0xEF &&
        static_cast<unsigned char>(content[1]) == 0xBB &&
        static_cast<unsigned char>(content[2]) == 0xBF) {
        content.erase(0, 3);
    }
    return content;
}

static unsigned long long currentPowerGeneration();
static bool powerLifecycleMatches(PowerLifecycle phase, unsigned long long generation);

static bool beginHardwareWriteLease(const char* source) {
    if (!hardwareWriteAllowed()) {
        traceLog("power gate blocked source=%s generation=%llu", source ? source : "unknown",
                 currentPowerGeneration());
        return false;
    }
    g_hardwareWriteInFlight.fetch_add(1, std::memory_order_acq_rel);
    if (!hardwareWriteAllowed()) {
        g_hardwareWriteInFlight.fetch_sub(1, std::memory_order_acq_rel);
        traceLog("power gate blocked after lease source=%s generation=%llu",
                 source ? source : "unknown", currentPowerGeneration());
        return false;
    }
    return true;
}

static void endHardwareWriteLease() {
    g_hardwareWriteInFlight.fetch_sub(1, std::memory_order_acq_rel);
}

struct HardwareWriteLease {
    bool held = false;
    explicit HardwareWriteLease(const char* source) : held(beginHardwareWriteLease(source)) {
        if (!held) throw std::runtime_error("hardware writes are blocked during power transition");
    }
    ~HardwareWriteLease() { if (held) endHardwareWriteLease(); }
    HardwareWriteLease(const HardwareWriteLease&) = delete;
    HardwareWriteLease& operator=(const HardwareWriteLease&) = delete;
};

static bool isPowerRegistryPath(const std::string& rawPath) {
    auto path = ascii_lower(rawPath);
    std::replace(path.begin(), path.end(), '/', '\\');
    return path.find("\\control\\power\\") != std::string::npos ||
           path.find("\\powersettings\\") != std::string::npos;
}

static bool waitForHardwareWritesQuiesced(unsigned long long generation, DWORD timeoutMs) {
    const ULONGLONG deadline = GetTickCount64() + timeoutMs;
    while (g_hardwareWriteInFlight.load(std::memory_order_acquire) != 0) {
        if (!powerLifecycleMatches(PowerLifecycle::Suspending, generation)) return false;
        if (GetTickCount64() >= deadline) {
            traceLog("power gate quiesce timeout inflight=%u generation=%llu",
                     g_hardwareWriteInFlight.load(std::memory_order_acquire), generation);
            return false;
        }
        Sleep(20);
    }
    return true;
}

// 用户持久化配置唯一入口。运行快照、日志、名单和媒体仍使用各自的
// 独立文件；只有低频用户设置进入 yeman-settings.json。
static const std::wstring YM_SETTINGS_FILE = POWER_CONTROL_DIR + L"\\yeman-settings.json";
static const std::wstring YM_SETTINGS_BACKUP_FILE = YM_SETTINGS_FILE + L".bak";
static std::mutex g_settingsFileMtx;

static std::wstring normalizeWindowsPathForCompare(std::wstring path) {
    for (auto& ch : path) {
        if (ch == L'/') ch = L'\\';
    }
    wchar_t full[32768]{};
    const DWORD length = GetFullPathNameW(path.c_str(), static_cast<DWORD>(_countof(full)), full, nullptr);
    if (length > 0 && length < _countof(full)) path.assign(full, length);
    while (path.size() > 3 && !path.empty() && path.back() == L'\\') path.pop_back();
    for (auto& ch : path) ch = static_cast<wchar_t>(towlower(ch));
    return path;
}

static bool sameWindowsPath(const std::wstring& left, const std::wstring& right) {
    return normalizeWindowsPathForCompare(left) == normalizeWindowsPathForCompare(right);
}

// Unlike sgReadFile (best-effort runtime/log reads), durable settings reads
// must distinguish missing from sharing/access/I/O failures before recovery.
static std::string ymSettingsReadRaw(const std::wstring& path) {
    HANDLE file = CreateFileW(path.c_str(), GENERIC_READ,
        FILE_SHARE_READ | FILE_SHARE_WRITE | FILE_SHARE_DELETE, nullptr,
        OPEN_EXISTING, FILE_ATTRIBUTE_NORMAL, nullptr);
    if (file == INVALID_HANDLE_VALUE) {
        const DWORD error = GetLastError();
        if (error == ERROR_FILE_NOT_FOUND || error == ERROR_PATH_NOT_FOUND) return {};
        throw std::runtime_error("Unified settings read failed: " + std::to_string(error));
    }
    LARGE_INTEGER size{};
    if (!GetFileSizeEx(file, &size) || size.QuadPart < 0 || size.QuadPart > 4 * 1024 * 1024) {
        CloseHandle(file);
        throw std::runtime_error("Unified settings size/read failed");
    }
    std::string content(static_cast<size_t>(size.QuadPart), '\0');
    DWORD read = 0;
    const bool ok = content.empty() || (ReadFile(file, content.data(), static_cast<DWORD>(content.size()), &read, nullptr) && read == content.size());
    CloseHandle(file);
    if (!ok) throw std::runtime_error("Unified settings incomplete read");
    return content;
}

// Merge only actual changes relative to the submitted baseline. Arrays and
// scalars are atomic values; object siblings/unknown fields remain untouched.
static void ymSettingsApplyDelta(json& current, const json& baseline, const json& next) {
    if (baseline == next) return;
    if (!next.is_object() || (!baseline.is_object() && !baseline.is_null())) {
        current = next;
        return;
    }
    if (!current.is_object()) current = json::object();
    if (baseline.is_object()) {
        for (auto it = baseline.begin(); it != baseline.end(); ++it)
            if (!next.contains(it.key())) current.erase(it.key());
    }
    for (auto it = next.begin(); it != next.end(); ++it) {
        if (baseline.is_object() && baseline.contains(it.key())) {
            if (baseline[it.key()] != it.value()) ymSettingsApplyDelta(current[it.key()], baseline[it.key()], it.value());
        } else {
            ymSettingsApplyDelta(current[it.key()], nullptr, it.value());
        }
    }
}
static void ymSettingsFillMissing(json& current, const json& defaults) {
    if (!current.is_object() || !defaults.is_object()) return;
    for (auto it = defaults.begin(); it != defaults.end(); ++it) {
        if (!current.contains(it.key())) current[it.key()] = it.value();
        else if (current[it.key()].is_object() && it.value().is_object()) ymSettingsFillMissing(current[it.key()], it.value());
    }
}

static json ymSettingsReadUnlocked() {
    const auto raw = ymSettingsReadRaw(YM_SETTINGS_FILE);
    if (!raw.empty()) {
        try {
            auto j = json::parse(raw);
            if (j.is_object()) return j;
        } catch (...) {}
    }
    const auto backup = ymSettingsReadRaw(YM_SETTINGS_BACKUP_FILE);
    if (!backup.empty()) {
        try {
            auto j = json::parse(backup);
            if (j.is_object()) return j;
        } catch (...) {}
    }
    return json::object();
}
class SettingsFileGuard {
public:
    SettingsFileGuard() : local_(g_settingsFileMtx) {
        mutex_ = CreateMutexW(nullptr, FALSE, L"Local\\YeManCC-UnifiedSettings");
        if (!mutex_) throw std::runtime_error("Unified settings mutex creation failed");
        const DWORD wait = WaitForSingleObject(mutex_, INFINITE);
        if (wait != WAIT_OBJECT_0 && wait != WAIT_ABANDONED) {
            CloseHandle(mutex_);
            mutex_ = nullptr;
            throw std::runtime_error("Unified settings mutex wait failed");
        }
    }
    ~SettingsFileGuard() {
        if (mutex_) {
            ReleaseMutex(mutex_);
            CloseHandle(mutex_);
        }
    }
    SettingsFileGuard(const SettingsFileGuard&) = delete;
    SettingsFileGuard& operator=(const SettingsFileGuard&) = delete;
private:
    std::unique_lock<std::mutex> local_;
    HANDLE mutex_ = nullptr;
};
static bool ymSettingsWriteDocumentUnlocked(const std::string& content,
                                            long long* staleInputDroppedRev = nullptr,
                                            const json* baseline = nullptr,
                                            json* committed = nullptr, bool initialize = false,
                                             long long expectedInputRevision = -1,
                                             bool* inputRevisionConflict = nullptr) {
    if (inputRevisionConflict) *inputRevisionConflict = false;
    json parsed;
    try {
        parsed = json::parse(content);
    } catch (...) {
        return false;
    }
    if (!parsed.is_object()) return false;
    const auto raw = ymSettingsReadRaw(YM_SETTINGS_FILE);
    json old;
    bool oldValid = false;
    if (!raw.empty()) {
        try {
            old = json::parse(raw);
            oldValid = old.is_object();
        } catch (...) {}
    }
    // OEM save CAS: validate the caller revision under the same native lock
    // as delta merge and atomic commit. Same-next-revision races must reject.
    if (expectedInputRevision >= 0) {
        if (!oldValid) return false; // unreadable/corrupt is not a version proof
        long long diskRevision = 0;
        if (old.contains("input")) {
            if (!old["input"].is_object()) return false;
            const auto revision = old["input"].find("revision");
            if (revision != old["input"].end()) {
                if (!revision->is_number_integer()) return false;
                diskRevision = revision->get<long long>();
            }
        }
        if (diskRevision != expectedInputRevision) {
            if (inputRevisionConflict) *inputRevisionConflict = true;
            if (committed) *committed = old;
            return false; // no backup/write/refresh on rejected transaction
        }
    }
    if (!raw.empty() && !oldValid) {
        const auto corrupt = YM_SETTINGS_FILE + L".corrupt-native-" + std::to_wstring(GetTickCount64());
        if (!sgWriteFileAtomic(corrupt, raw)) return false;
    }
    if (baseline) {
        if (!baseline->is_object()) return false;
        json merged = oldValid ? old : ymSettingsReadUnlocked();
        if (!merged.is_object()) merged = json::object();
        if (initialize) {
            ymSettingsFillMissing(merged, parsed);
            if (parsed.contains("schemaVersion") && parsed["schemaVersion"].is_number_integer()) {
                const int written = merged.contains("schemaVersion") && merged["schemaVersion"].is_number_integer() ? merged["schemaVersion"].get<int>() : 0;
                merged["schemaVersion"] = (std::max)(written, parsed["schemaVersion"].get<int>());
            }
        }
        else ymSettingsApplyDelta(merged, *baseline, parsed);
        parsed = std::move(merged);
    }
    if (oldValid) {
        // 裁决20 §3（2026-09-18）：整文档覆盖入口（settings.write = 前端快照）的
        // 过期段保护，避免"过期设置写入意外覆盖 input / 回退已推进的版本"。
        // ① domainLogs：仅 native 写者（统一日志开关 IPC / 启动迁移）⇒ 一律保留
        //    磁盘值，前端整文档写入不得回退它（实测 14:10 曾把域开关回退为 false）。
        // ② input：入参 revision 小于磁盘现值 = 过期快照 ⇒ 保留磁盘 input 段（其余
        //    段照常写入）。合法的新请求（revision ≥ 现值，含前端 CAS 递增后的写入）
        //    不受影响。
        if (old.contains("domainLogs")) parsed["domainLogs"] = old["domainLogs"];
        // Native-owned deferred Steam write receipts must survive stale UI snapshots.
        if (old.contains("steamDeckMouse")) parsed["steamDeckMouse"] = old["steamDeckMouse"];
        const bool diskInput = old.contains("input") && old["input"].is_object();
        if (diskInput) {
            const long long diskRev = old["input"].value("revision", -1LL);
            const bool incomingInput = parsed.contains("input") && parsed["input"].is_object();
            const long long inRev = incomingInput ? parsed["input"].value("revision", -1LL) : -1LL;
            if (diskRev > inRev) {
                parsed["input"] = old["input"];
                if (staleInputDroppedRev) *staleInputDroppedRev = inRev;
            }
        }
    }
    const auto serialized = parsed.dump(2);
    if (serialized.size() > 4 * 1024 * 1024) return false;
    if (oldValid && !sgWriteFileAtomic(YM_SETTINGS_BACKUP_FILE, raw)) return false;
    if (!sgWriteFileAtomic(YM_SETTINGS_FILE, serialized)) return false;
    if (committed) *committed = parsed;
    return true;
}
static bool ymSettingsWriteDocument(const std::string& content,
                                    long long* staleInputDroppedRev = nullptr,
                                    const json* baseline = nullptr,
                                    json* committed = nullptr, bool initialize = false,
                                    long long expectedInputRevision = -1,
                                    bool* inputRevisionConflict = nullptr) {
    SettingsFileGuard guard;
    return ymSettingsWriteDocumentUnlocked(content, staleInputDroppedRev, baseline, committed, initialize,
                                           expectedInputRevision, inputRevisionConflict);
}
// Explicit-read metadata validation; no polling, parsing or disk reads when
// size/creation/last-write stamp is unchanged. Guard covers stamp + content.
static json ymSettingsReadSnapshot(const std::string& knownStamp) {
    SettingsFileGuard guard;
    WIN32_FILE_ATTRIBUTE_DATA attributes{};
    std::string stamp = "missing";
    if (GetFileAttributesExW(YM_SETTINGS_FILE.c_str(), GetFileExInfoStandard, &attributes)) {
        ULARGE_INTEGER modified{}, created{}, size{};
        modified.HighPart = attributes.ftLastWriteTime.dwHighDateTime;
        modified.LowPart = attributes.ftLastWriteTime.dwLowDateTime;
        created.HighPart = attributes.ftCreationTime.dwHighDateTime;
        created.LowPart = attributes.ftCreationTime.dwLowDateTime;
        size.HighPart = attributes.nFileSizeHigh; size.LowPart = attributes.nFileSizeLow;
        stamp = std::to_string(modified.QuadPart) + ":" + std::to_string(created.QuadPart) + ":" + std::to_string(size.QuadPart);
    } else {
        const DWORD error = GetLastError();
        if (error != ERROR_FILE_NOT_FOUND && error != ERROR_PATH_NOT_FOUND)
            throw std::runtime_error("Unified settings metadata read failed: " + std::to_string(error));
    }
    if (!knownStamp.empty() && knownStamp == stamp && stamp != "missing")
        return {{"stamp", stamp}, {"unchanged", true}};
    return {{"stamp", stamp}, {"unchanged", false}, {"content", ymSettingsReadRaw(YM_SETTINGS_FILE)}};
}
// This storage-only recovery endpoint is never called automatically.
// Archive BOTH exact original files before activating defaults; preserve every
// unknown/protected section that can be parsed. No hardware refresh is issued.
static json ymSettingsResetApplication(const json& defaults) {
    if (!defaults.is_object() || defaults.value("schemaVersion", 0) != 1)
        throw std::runtime_error("Invalid application recovery defaults");
    static const char* owned[] = {"ui", "background", "music", "performanceSchedule",
        "gameCustom", "tdp", "cpu", "sleep", "quickApps", "power", "tray", "autoclose"};
    for (const auto* key : owned)
        if (!defaults.contains(key) || !defaults[key].is_object())
            throw std::runtime_error("Incomplete application recovery defaults");
    SettingsFileGuard guard;
    const auto mainRaw = ymSettingsReadRaw(YM_SETTINGS_FILE);
    const auto backupRaw = ymSettingsReadRaw(YM_SETTINGS_BACKUP_FILE);
    auto objectFrom = [](const std::string& raw) -> json {
        try { auto value = json::parse(raw); if (value.is_object()) return value; } catch (...) {}
        return json();
    };
    json current = objectFrom(mainRaw);
    if (!current.is_object()) current = objectFrom(backupRaw);
    json next = current.is_object() ? current : json::object();
    for (const auto* key : owned) next[key] = defaults[key];
    next["schemaVersion"] = 1;
    if (!next.contains("baselineId") && defaults.contains("baselineId"))
        next["baselineId"] = defaults["baselineId"];
    // Reset should open an inspectable UI, not apply a new default CPU/TDP plan.
    next["tdp"]["autoApply"] = {{"boot", false}, {"wake", false}};
    next["tdp"]["float"] = {{"target", 120}, {"profile", "none"}, {"tdpStrategy", "none"}};
    next["cpu"]["autoEnable"] = {{"mode", "off"}};
    next["cpu"]["autostart"] = {{"ccd", {{"enabled", false}}}, {"uv", {{"enabled", false}}}};
    next["performanceSchedule"]["enabled"] = false;
    const auto content = next.dump(2);
    if (content.size() > 4 * 1024 * 1024) throw std::runtime_error("Recovered configuration is too large");
    static unsigned long long sequence = 0;
    const auto suffix = L".before-user-reset-" + std::to_wstring(GetCurrentProcessId()) +
        L"-" + std::to_wstring(GetTickCount64()) + L"-" + std::to_wstring(++sequence);
    json archives = json::array();
    auto archive = [&](const std::wstring& source, const std::string& raw) {
        if (raw.empty() && !fspath::exists(source)) return;
        const auto saved = source + suffix;
        if (!sgWriteFileAtomic(saved, raw)) throw std::runtime_error("Cannot back up settings; reset cancelled");
        archives.push_back(W2U(saved));
    };
    archive(YM_SETTINGS_FILE, mainRaw);
    archive(YM_SETTINGS_BACKUP_FILE, backupRaw);
    if (!sgWriteFileAtomic(YM_SETTINGS_FILE, content))
        throw std::runtime_error("Cannot activate recovered settings; old configuration retained");
    return {{"ok", true}, {"backups", archives}, {"protectedDataRecovered", current.is_object()}};
}

static json ymSettingsRead() {
    SettingsFileGuard guard;
    return ymSettingsReadUnlocked();
}
static json ymSettingsSection(const char* section);
static bool ymSettingsWriteSection(const char* section, const json& value) {
    SettingsFileGuard guard;
    const auto raw = ymSettingsReadRaw(YM_SETTINGS_FILE);
    auto all = ymSettingsReadUnlocked();
    if (!all.is_object()) all = json::object();
    all["schemaVersion"] = (std::max)(1, all.value("schemaVersion", 1));
    if (!all.contains("baselineId")) all["baselineId"] = "2026-08-09-user-default";
    all[section] = value;
    // Keep the last valid main file available for recovery before replacing it.
    if (!raw.empty()) {
        try {
            auto old = json::parse(raw);
            if (old.is_object()) { if (!sgWriteFileAtomic(YM_SETTINGS_BACKUP_FILE, raw)) return false; }
            else if (!sgWriteFileAtomic(YM_SETTINGS_FILE + L".corrupt-native-" + std::to_wstring(GetTickCount64()), raw)) return false;
        } catch (...) {
            if (!sgWriteFileAtomic(YM_SETTINGS_FILE + L".corrupt-native-" + std::to_wstring(GetTickCount64()), raw)) return false;
        }
    }
    return sgWriteFileAtomic(YM_SETTINGS_FILE, all.dump(2));
}
static bool ymSettingsExists() {
    return fspath::exists(YM_SETTINGS_FILE);
}
static json ymSettingsSection(const char* section) {
    const auto all = ymSettingsRead();
    auto it = all.find(section);
    return it != all.end() && it->is_object() ? *it : json::object();
}

static bool windowPlacementIsLeft() {
    try {
        const auto ui = ymSettingsSection("ui");
        return ui.is_object() && ui.contains("windowPlacement") && ui["windowPlacement"] == "left";
    } catch (...) {
        // Broken/unavailable settings must not prevent the shell from opening.
        return false;
    }
}
static bool ymSettingsPatchSection(const char* section, const json& patch) {
    SettingsFileGuard guard;
    const auto all = ymSettingsReadUnlocked();
    auto it = all.find(section);
    auto current = it != all.end() && it->is_object() ? *it : json::object();
    if (!current.is_object()) current = json::object();
    if (patch.is_object()) {
        for (auto it = patch.begin(); it != patch.end(); ++it) current[it.key()] = it.value();
    }
    auto next = all.is_object() ? all : json::object();
    next["schemaVersion"] = (std::max)(1, next.value("schemaVersion", 1));
    if (!next.contains("baselineId")) next["baselineId"] = "2026-08-09-user-default";
    next[section] = current;
    const auto raw = ymSettingsReadRaw(YM_SETTINGS_FILE);
    if (!raw.empty()) {
        try {
            auto old = json::parse(raw);
            if (old.is_object()) { if (!sgWriteFileAtomic(YM_SETTINGS_BACKUP_FILE, raw)) return false; }
            else if (!sgWriteFileAtomic(YM_SETTINGS_FILE + L".corrupt-native-" + std::to_wstring(GetTickCount64()), raw)) return false;
        } catch (...) {
            if (!sgWriteFileAtomic(YM_SETTINGS_FILE + L".corrupt-native-" + std::to_wstring(GetTickCount64()), raw)) return false;
        }
    }
    return sgWriteFileAtomic(YM_SETTINGS_FILE, next.dump(2));
}

