// ── 7.47（Controller 族，HC LegionController 对齐）──────────────────────
// HC SensorFamily.Controller 在手柄自带 IMU 时优先于 Windows 传感器
// （ControllerManager 目标有 MotionSensor → SensorsManager.PickNextSensor
// 置 Controller 族，SensorsManager.cs:208-221）。Legion Go 手柄 IMU 由
// 其 HID 报告固有偏移采集（LegionController.cs:64-79 索引常量 + 255-295
// 采集：accel ±4g、gyro ±2000dps，左/右 joycon 各有独立偏移，报告错位
// （byte1==0）时整体 -2）。这里在豁免 HID 读中解析同一报告的 IMU 字段，
// 供 Controller 族注入（HC SetGyroscope + ProcessMotion 语义）。
static std::mutex g_legionImuMx;
static bool g_legionImuValid = false;
static float g_legionImuGx = 0, g_legionImuGy = 0, g_legionImuGz = 0;
static float g_legionImuAx = 0, g_legionImuAy = 0, g_legionImuAz = 0;
static ULONGLONG g_legionImuTick = 0;
// HC LegionController 报告偏移常量（LegionController.cs:64-79）
static constexpr int kLegionLAccelIdx = 35;   // 左 joycon accel (X,Z,Y each i16)
static constexpr int kLegionLGyroIdx = 41;    // 左 joycon gyro (X,Z,Y each i16)
static constexpr int kLegionRAccelIdx = 48;   // 右 joycon accel
static constexpr int kLegionRGyroIdx = 54;    // 右 joycon gyro
static constexpr float kLegionAccelScale = 4.0f / 32767.0f;    // ±4g / i16
static constexpr float kLegionGyroScale = 2000.0f / 32767.0f;  // ±2000dps / i16
// HC SetGyroIndex 默认左 joycon（LegionController.cs:167-168, 286-291）
static constexpr int kLegionGyroSide = 0;
static bool legionImuParse(const BYTE* data, size_t len, bool misaligned,
                           float& gx, float& gy, float& gz,
                           float& ax, float& ay, float& az) {
    if (!data || len < 60) return false;
    const int off = misaligned ? -2 : 0;
    const int am = kLegionGyroSide == 0 ? kLegionLAccelIdx : kLegionRAccelIdx;
    const int gm = kLegionGyroSide == 0 ? kLegionLGyroIdx : kLegionRGyroIdx;
    const int a = am + off, g = gm + off;
    if (a < 0 || g < 0 || a + 5 >= static_cast<int>(len) || g + 5 >= static_cast<int>(len)) return false;
    const auto i16 = [&](int o) -> short { return (short)((unsigned short)(data[o] << 8 | data[o + 1])); };
    if (kLegionGyroSide == 0) {
        // 左 joycon（HC 262-269）：aX=-X,aZ=-Z,aY=-Y；gX=-X,gZ=-Z,gY=-Y
        ax = i16(a) * -kLegionAccelScale;
        az = i16(a + 2) * -kLegionAccelScale;
        ay = i16(a + 4) * -kLegionAccelScale;
        gx = i16(g) * -kLegionGyroScale;
        gz = i16(g + 2) * -kLegionGyroScale;
        gy = i16(g + 4) * -kLegionGyroScale;
    } else {
        // 右 joycon（HC 273-281）：aX=+Z2,aZ=-X1,aY=-Y；gX=-Z2,gZ=+X1,gY=-Y
        ax = i16(a + 2) * -kLegionAccelScale;
        az = i16(a) * kLegionAccelScale;
        ay = i16(a + 4) * -kLegionAccelScale;
        gx = i16(g + 2) * -kLegionGyroScale;
        gz = i16(g) * kLegionGyroScale;
        gy = i16(g + 4) * -kLegionGyroScale;
    }
    return true;
}
