// 背键全机型适配 + 专用键全机型采集（2026-09-16 全机型普查，源码锚点见各
// profile 注释）：键盘/鼠标 chord 表驱动采集。每机型一个 profile——规则 =
// 键集合掩码 + 键位 bit + 背键位（bit0/1）。键集合按「精确集合相等」语义
// （HC InputsManager.cs:443-506：缓冲键数量相等且逐项命中）；同组互斥（组内
// 靠前的规则先命中，处理组合键包含关系，如 AOKZOE Home ⊂ Home+Turbo）。
// profile 由 oemBackMappingRefreshGate 按 family/deviceClass 选择（hook 位于
// g_machineIdentity 定义之前，故经 g_oemBackProfileId 传递）。
static std::atomic<int> g_oemBackProfileId{0};

// 键态跟踪掩码（规范化键位——修饰键不分侧：ctrl/alt/shift/win 统一到
// kVkCtrl/kVkAlt/kVkShift/kVkWin；LL hook 可能报 0x11/0xA2/0xA3 等形态）。
// 仅 hook 回调线程访问（键盘/鼠标 hook 同一安装线程投递）。
enum OemVkBit : uint32_t {
    kVkCtrl = 1u << 0,  kVkAlt = 1u << 1,  kVkShift = 1u << 2,  kVkWin = 1u << 3,
    kVkF3 = 1u << 4,    kVkF10 = 1u << 5,  kVkF11 = 1u << 6,   kVkF12 = 1u << 7,
    kVkF13 = 1u << 8,   kVkF14 = 1u << 9,  kVkF15 = 1u << 10,  kVkF16 = 1u << 11,
    kVkF17 = 1u << 12,  kVkF18 = 1u << 13, kVkF21 = 1u << 14,  kVkF22 = 1u << 15,
    kVkF23 = 1u << 16,  kVkF24 = 1u << 17, kVkL = 1u << 18,    kVkR = 1u << 19,
    kVkO = 1u << 20,    kVkG = 1u << 21,   kVkT = 1u << 22,    kVkD = 1u << 23,
    kVkEsc = 1u << 24,  kVkDel = 1u << 25, kVkSnap = 1u << 26,
    kVkTab = 1u << 27,  // MSI BIOS 10F 的 QS 键盘回退编码（ClawA1M.cs:281-282）
};
static uint32_t g_oemKbDown = 0;
// ── ROG 键盘 Raw Input 独占通路（裁决 §4.3 单一来源 / §4.4 释放清理）──────
// ROG profile 下背键由本通路提供：该 profile 不安装键盘 LL hook，两路状态
// 物理分离（清理本路不得触碰 g_oemKbDown 仍持有的输入）。写者：UI 线程
// （WM_INPUT / WM_INPUT_DEVICE_CHANGE）与 profile 门（oemRawPathReset）。
static std::atomic<uint32_t> g_oemKbDownRaw{0};
static std::atomic<bool> g_oemRawPathActive{false};
// 受理键位表：键位来源由当前 profile 规则导出（§4.1 ③，不做用户白名单）
static bool g_oemRawVkAllowed[256] = {};
// 来源接纳结论缓存：按 hDevice 命中最后结论（背键只来自一个设备；设备增删时失效）
static HANDLE g_oemRawAdmitDev = nullptr;
static bool g_oemRawAdmitOk = false;
// 鼠标键跟踪：Ayn Loki Guide 与 AYANEO KUN 旧 EC Guide 为鼠标和弦
// LButton+XButton2（AynLoki.cs:60-64 / AYANEOKUN.cs:26-30）——HC 用
// WH_MOUSE_LL 匹配（App.xaml.cs:401），此处同构。
static bool g_oemMouseLeft = false, g_oemMouseX2 = false;

// OEM 键位（与 nativeKeyboardShortcutMaskBit 表一致；bit20+ 高位空间）
static constexpr uint64_t kOemBitM1 = 1ull << 20, kOemBitM2 = 1ull << 21;
static constexpr uint64_t kOemBitCc = 1ull << 22, kOemBitAc = 1ull << 23, kOemBitLib = 1ull << 24;
static constexpr uint64_t kOemBitClaw = 1ull << 25, kOemBitQs = 1ull << 26;
static constexpr uint64_t kOemBitCkBig = 1ull << 27, kOemBitCkSmall = 1ull << 28;
static constexpr uint64_t kOemBitCkTl = 1ull << 29, kOemBitCkTr = 1ull << 30, kOemBitAyat = 1ull << 31;
static constexpr uint64_t kOemBitR4 = 1ull << 32, kOemBitL4 = 1ull << 33, kOemBitGamepad = 1ull << 34;
static constexpr uint64_t kOemBitKeyboard = 1ull << 35, kOemBitHome = 1ull << 36;
static constexpr uint64_t kOemBitLegionR = 1ull << 37, kOemBitLegionL = 1ull << 38;
static constexpr uint64_t kOemBitSpecial = 1ull << 39, kOemBitTurbo = 1ull << 40;
static constexpr uint64_t kOemBitSpecial2 = 1ull << 41;
static constexpr uint64_t kOemBitHomeLp = 1ull << 42, kOemBitHomeKb = 1ull << 43, kOemBitHomeTb = 1ull << 44;
static constexpr uint64_t kOemBitGuide = 1ull << 45, kOemBitLcc = 1ull << 46;
static constexpr uint64_t kOemBitZotac = 1ull << 47, kOemBitDots = 1ull << 48;
static constexpr uint64_t kOemBitScreen = 1ull << 49;
static constexpr uint64_t kOemBitWinKey = 1ull << 50, kOemBitEscKey = 1ull << 51;
static constexpr uint64_t kOemBitOrange = 1ull << 52, kOemBitFunction = 1ull << 53;
static constexpr uint64_t kOemBitOrangeKb = 1ull << 54, kOemBitOrangeTb = 1ull << 55;
static constexpr uint64_t kOemBitOrangeLp = 1ull << 56;
// Legion Go 其余 4 个背键（W7 步骤 4 确证：HC LegionController.cs:44-54 BackEnum 六位
// M3=0x04/M2=0x08/M1=0x10/Y3=0x20/Y2=0x40/Y1=0x80，:227-233 映射 R4/R5/L4/L5/B5/B11；
// YMCC 此前只解 M1/Y1 两位 ⇒ 其余 4 键被静默丢弃）
static constexpr uint64_t kOemBitLegionY2 = 1ull << 57, kOemBitLegionY3 = 1ull << 58;
static constexpr uint64_t kOemBitLegionM2 = 1ull << 59, kOemBitLegionM3 = 1ull << 60;
// R10: HC front OEM1/OEM2 are independent of all six rear switches.
static constexpr uint64_t kOemBitLegionFrontL = 1ull << 61, kOemBitLegionFrontR = 1ull << 62;

// ── GP-FAMILY-CAPABILITY-4 C4-D2：通用 OEM→rear mapper ─────────────────────
// 用户可配置的「OEM canonical 键 → 虚拟背键槽」映射。源掩码的每一位为 canonical
// OEM 位（nativeKeyboardShortcutMaskBit 的 bit20+ 段），命中即点亮对应 rear 位：
// bit0（左/L5）、bit1（右/R5）。默认全 0 = 未配置 = 零行为变化（既有
// g_oemBackState/oemBackMergedDisplayState 语义一字不动）。不改变固件通道，也不
// 默认把任何 Custom/Home/Guide 键转成背键——只有用户显式声明才映射。
static std::atomic<uint64_t> g_oemRearMapToL5{0};   // 命中 → bit0（左/L5）
static std::atomic<uint64_t> g_oemRearMapToR5{0};   // 命中 → bit1（右/R5）
// 定义在 nativeKeyboardShortcutMaskBit 之后（复用其 canonical 键表）。
static void oemRearMapRefresh(const json& outputTarget);

struct OemChordRule {
    uint32_t keys;       // 键集合（OemVkBit 掩码，全部按下即命中；mouseChord 时忽略）
    uint64_t bit;        // g_oemKeyMask 位（0 = 仅背键位）
    uint8_t backIndex;   // 1 = 背键 bit0（左/L5）、2 = bit1（右/R5）、0 = 无
    uint8_t group;       // 互斥组（0 = 独立；组内仅靠前首个命中生效）
    bool mouseChord;     // 鼠标和弦（LButton+XButton2）
};
struct OemChordProfile {
    const OemChordRule* rules;
    int count;
};

