// ── HidHide 并发串行化（HC parity：Misc\HidHide.cs 每个操作 lock(hidLock)）──
// HC 用 HidHideControlService 进程内 API，且全部 Hide/Unhide/Register/Cloak
// 操作均 lock(hidLock)（HidHide.cs:56/71/97/132/167/210/248）。YMCC 走 CLI，
// 若 28 处 hidHideRun 无锁并发（hide 线程 / watchdog / BUS / 自愈），CLI 子
// 进程互撞会触发 FilterDriverProxy 0x0005、wedged 并把正常 restore 吞掉 →
// 物理手柄保持隐藏，需拔插/卸载才能恢复（0910-21 用户实测）。此处加全局
// 互斥使所有 HidHide 调用串行，与 HC hidLock 语义一致。
static std::mutex g_hidHideMx;

// GP-926R13 §3.2：absoluteDeadlineTick!=0 时整个 CLI 等待（含收尾）以该绝对时刻为界；
// 客户端停止等待不等于驱动操作已取消——到点即终止子进程并在完成态收尾后再返回。
static bool hidHideRun(const std::wstring& arguments, std::string* output = nullptr,
                       DWORD* exitCodeOut = nullptr, ULONGLONG absoluteDeadlineTick = 0) {
    const std::wstring cli = hidHideCliPath();
    if (GetFileAttributesW(cli.c_str()) == INVALID_FILE_ATTRIBUTES) return false;
    SECURITY_ATTRIBUTES sa{ sizeof(sa), nullptr, TRUE };
    HANDLE readPipe = nullptr, writePipe = nullptr;
    if (!CreatePipe(&readPipe, &writePipe, &sa, 0)) return false;
    SetHandleInformation(readPipe, HANDLE_FLAG_INHERIT, 0);
    STARTUPINFOW si{}; si.cb = sizeof(si); si.dwFlags = STARTF_USESTDHANDLES | STARTF_USESHOWWINDOW;
    si.hStdOutput = writePipe; si.hStdError = writePipe; si.wShowWindow = SW_HIDE;
    PROCESS_INFORMATION pi{};
    std::wstring cmd = L"\"" + cli + L"\" " + arguments;
    std::vector<wchar_t> buf(cmd.begin(), cmd.end()); buf.push_back(0);
    const BOOL ok = CreateProcessW(nullptr, buf.data(), nullptr, nullptr, TRUE, CREATE_NO_WINDOW, nullptr, nullptr, &si, &pi);
    CloseHandle(writePipe);
    if (!ok) { CloseHandle(readPipe); return false; }
    std::string text;
    char chunk[4096];
    // HidHideCLI can wedge (e.g. stalled driver I/O): a synchronous ReadFile on
    // the pipe here would block the whole Host open forever, leaving the
    // session live but never writing input-host-open-result (observed r-f).
    // Poll with a 4 s deadline and terminate the wedged child instead.
    const ULONGLONG fallbackDeadline = GetTickCount64() + 4000;
    const ULONGLONG deadline = (absoluteDeadlineTick != 0 && absoluteDeadlineTick < fallbackDeadline)
        ? absoluteDeadlineTick : fallbackDeadline;
    for (;;) {
        DWORD avail = 0;
        if (PeekNamedPipe(readPipe, nullptr, 0, nullptr, &avail, nullptr) && avail > 0) {
            DWORD n = 0;
            const DWORD want = (DWORD)(avail < sizeof(chunk) ? avail : sizeof(chunk));
            if (ReadFile(readPipe, chunk, want, &n, nullptr) && n) text.append(chunk, chunk + n);
        }
        if (WaitForSingleObject(pi.hProcess, 0) == WAIT_OBJECT_0) break;
        if (GetTickCount64() >= deadline) {
            TerminateProcess(pi.hProcess, 1);
            WaitForSingleObject(pi.hProcess, absoluteDeadlineTick != 0 ? 250 : 1000);
            break;
        }
        Sleep(10);
    }
    DWORD exitCode = 1;
    GetExitCodeProcess(pi.hProcess, &exitCode);
    CloseHandle(readPipe); CloseHandle(pi.hThread); CloseHandle(pi.hProcess);
    if (output) *output = text;
    if (exitCodeOut) *exitCodeOut = exitCode;
    return exitCode == ERROR_SUCCESS;
}

// ── T0 (2026-09-10): HidHide 自愈 ──
// HC 只有 fail-fast 启动检查与 API→CLI fallback（Misc\HidHide.cs），没有自动
// 重装/重置/服务重启。用户将 HidHide 故障（服务停、驱动异常、配置损坏导致
// Configuration Client 崩溃、隐藏残留致手柄不可用）升级为 T0：YMCC 自愈。
//   L1  服务未 RUNNING         → sc start HidHide
//   L3  隐藏残留纠偏           → 由 RecoverPersistentTransaction + exact
//                                restore（已有路径）承担，不重复。
// 2026-09-10 收敛（0910-18 探针 + 用户裁决）：
//   原 L2（sc stop/start 重启驱动）与 L4（每 30s 静默重装）删除：
//   (1) L4 每 30s 拉起 Inno Setup，第一个实例超时后成为僵尸持有安装互斥锁，
//       后续实例必然弹 "Another instance of setup is already running"
//       （/VERYSILENT /SUPPRESSMSGBOXES 压制不了 Inno 的单实例检查）；
//   (2) L2 在虚拟手柄会话进行中执行 sc stop/start HidHide，等于每 30s 掐断
//       物理源读取通道；HC 从不做这两种运行时破坏性操作。
//   运行时保留 L1（服务未运行则拉起，无破坏性）与 L3；HidHide 驱动/配置
//   坏态（--dev-all 不可交互）只做持久诊断（hidhide.driver-degraded），由
//   部署/发布通道做干净重装或在 UI 提示用户。用户曾授权运行时自动卸载+
//   重装，因进程权限不足（非管理员，Inno 静默重装不可行）于 2026-09-10
//   撤销：本代码库不含任何自动卸载/重装逻辑，与 HC 完全一致。
static ULONGLONG g_hidHideLastHealTick = 0;

static bool hidHideRunSc(const std::wstring& arguments, std::string* output = nullptr) {
    SECURITY_ATTRIBUTES sa{ sizeof(sa), nullptr, TRUE };
    HANDLE readPipe = nullptr, writePipe = nullptr;
    if (!CreatePipe(&readPipe, &writePipe, &sa, 0)) return false;
    SetHandleInformation(readPipe, HANDLE_FLAG_INHERIT, 0);
    STARTUPINFOW si{}; si.cb = sizeof(si); si.dwFlags = STARTF_USESTDHANDLES | STARTF_USESHOWWINDOW;
    si.hStdOutput = writePipe; si.hStdError = writePipe; si.wShowWindow = SW_HIDE;
    PROCESS_INFORMATION pi{};
    std::wstring cmd = L"sc.exe " + arguments;
    std::vector<wchar_t> buf(cmd.begin(), cmd.end()); buf.push_back(0);
    const BOOL ok = CreateProcessW(nullptr, buf.data(), nullptr, nullptr, TRUE, CREATE_NO_WINDOW, nullptr, nullptr, &si, &pi);
    CloseHandle(writePipe);
    if (!ok) { CloseHandle(readPipe); return false; }
    std::string text; char chunk[512];
    DWORD n = 0;
    const ULONGLONG deadline = GetTickCount64() + 4000;
    for (;;) {
        DWORD avail = 0;
        if (PeekNamedPipe(readPipe, nullptr, 0, nullptr, &avail, nullptr) && avail > 0) {
            const DWORD want = avail < sizeof(chunk) ? avail : sizeof(chunk);
            if (ReadFile(readPipe, chunk, want, &n, nullptr) && n) text.append(chunk, chunk + n);
        }
        if (WaitForSingleObject(pi.hProcess, 0) == WAIT_OBJECT_0) break;
        if (GetTickCount64() >= deadline) {
            TerminateProcess(pi.hProcess, 1);
            WaitForSingleObject(pi.hProcess, 1000);
            break;
        }
        Sleep(10);
    }
    DWORD exitCode = 1;
    GetExitCodeProcess(pi.hProcess, &exitCode);
    CloseHandle(readPipe); CloseHandle(pi.hThread); CloseHandle(pi.hProcess);
    if (output) *output = text;
    return exitCode == ERROR_SUCCESS;
}

