    ipc_on("app.aiFanMockAcceptRequest", [](const json& a) -> json {
        if (!g_aiFanMockSession.enabled || !a.is_object() || a.size() < 6 || a.size() > 7) return false;
        for (const auto& item : a.items()) {
            if (item.key() != "schemaVersion" && item.key() != "sessionId" && item.key() != "parentPid" &&
                item.key() != "requestId" && item.key() != "sequence" && item.key() != "action" && item.key() != "preset") return false;
        }
        if (a.value("schemaVersion", 0) != 1 || a.value("sessionId", std::string{}) != W2U(g_aiFanMockSession.id) ||
            a.value("parentPid", 0ULL) != GetCurrentProcessId()) return false;
        if (!a.contains("sequence") || !a["sequence"].is_number_integer()) return false;
        const auto signedSequence = a["sequence"].get<long long>();
        if (signedSequence <= 0 || signedSequence > 9007199254740991LL) return false;
        const auto requestId = a.value("requestId", std::string{});
        if (!ymcc::ai_fan::validSessionId(U2W(requestId))) return false;
        const auto action = a.value("action", std::string{});
        if (action != "probe" && action != "on" && action != "off" && action != "close" && action != "status") return false;
        if (a.contains("preset")) {
            const auto preset = a.value("preset", std::string{});
            if (action != "on" || (preset != "soft" && preset != "balanced" && preset != "aggressive")) return false;
        }
        std::lock_guard<std::mutex> lock(g_aiFanMockRequestMutex);
        const auto sequence = static_cast<unsigned long long>(signedSequence);
        if (sequence <= g_aiFanMockLastSequence || g_aiFanMockSeenRequests.count(requestId) || g_aiFanMockSeenRequests.size() >= 4096) return false;
        g_aiFanMockLastSequence = sequence;
        g_aiFanMockSeenRequests.insert(requestId);
        return true;
    });
