    ipc_on("screenTouchpads.get", [](const json& args) -> json {
        const int profile=args.contains("persona") && args["persona"].is_string()
            ? ymcc::screenpads::profileIndex(args["persona"].get<std::string>()) : ymcc::screenpads::activeProfile.load();
        if(profile<0) return {{"ok",false},{"reason","invalid-persona"}};
        const ymcc::screenpads::ProfileBank bank(ymSettingsSection("screenTouchpads"));
        return ymcc::screenpads::profileState(bank.slots[profile],profile);
    });
    ipc_on("screenTouchpads.set", [](const json& args) -> json {
        const int profile=args.contains("persona") && args["persona"].is_string()
            ? ymcc::screenpads::profileIndex(args["persona"].get<std::string>()) : ymcc::screenpads::activeProfile.load();
        if(profile<0) return {{"ok",false},{"reason","invalid-persona"}};
        const json patch=args.contains("config") ? args["config"] : args;
        ymcc::screenpads::ProfileBank bank(ymSettingsSection("screenTouchpads"));
        ymcc::screenpads::Config next;
        if(!ymcc::screenpads::parseConfig(patch,bank.slots[profile],next))
            return {{"ok",false},{"reason","invalid-settings"}};
        const bool selectingDeck=(patch.contains("leftMode") && next.left==ymcc::screenpads::Mode::Deck) ||
            (patch.contains("rightMode") && next.right==ymcc::screenpads::Mode::Deck);
        if(selectingDeck && (profile!=1 || !ymcc::screenpads::available.load()))
            return {{"ok",false},{"reason","steamdeck-not-enabled"}};
        const bool psMapping=next.enabled && (next.layout==ymcc::screenpads::Layout::Single?
            next.single==ymcc::screenpads::Mode::DualSense:
            next.left==ymcc::screenpads::Mode::DualSense || next.right==ymcc::screenpads::Mode::DualSense);
        if(psMapping && (profile!=2 || !ymcc::screenpads::psAvailable.load()) &&
            (patch.contains("singleMode") || patch.contains("leftMode") || patch.contains("rightMode") || patch.contains("layout")))
            return {{"ok",false},{"reason","ps-not-enabled"}};
        if((effectiveSpecialMask(next)!=0 && profile==0) || (effectiveRearMask(next)!=0 && profile!=1 && profile!=2))
            return {{"ok",false},{"reason","buttons-not-supported"}};
        bank.slots[profile]=next;
        if(!ymSettingsWriteSection("screenTouchpads",bank.json()))
            return {{"ok",false},{"reason","settings-write-failed"}};
        if(profile==ymcc::screenpads::activeProfile.load()) ymcc::screenpads::configure(next,profile);
        auto result=ymcc::screenpads::profileState(next,profile);
        ipc_emit("screenTouchpads.updated",result);return result;
    });
