static const BYTE kRogCmdShoulder[]      = {0x5A,0xD1,0x02,0x04,0x2C,0x01,0x05,0x00,0x00,0x00,0x00,0x00,0x00,0x00,0x00,0x00,0x00,0x00,0x00,0x00,0x00,0x00,0x00,0x00,0x00,0x00,0x00,0x01,0x06};
static const BYTE kRogCmdFaceAB[]        = {0x5A,0xD1,0x02,0x05,0x2C,0x01,0x01,0x00,0x00,0x00,0x00,0x00,0x00,0x00,0x00,0x00,0x05,0x00,0x00,0x16,0x00,0x00,0x00,0x00,0x00,0x00,0x00,0x01,0x02,0x00,0x00,0x00,0x00,0x00,0x00,0x00,0x00,0x00,0x04,0x00,0x00,0x00,0x02,0x82,0x31};
static const BYTE kRogCmdFaceXY[]        = {0x5A,0xD1,0x02,0x06,0x2C,0x01,0x03,0x00,0x00,0x00,0x00,0x00,0x00,0x00,0x00,0x00,0x04,0x00,0x00,0x00,0x00,0x02,0x82,0x4D,0x00,0x00,0x00,0x01,0x04,0x00,0x00,0x00,0x00,0x00,0x00,0x00,0x00,0x00,0x05,0x00,0x00,0x1E};
static const BYTE kRogCmdViewMenu[]      = {0x5A,0xD1,0x02,0x07,0x2C,0x01,0x11,0x00,0x00,0x00,0x00,0x00,0x00,0x00,0x00,0x00,0x00,0x00,0x00,0x00,0x00,0x00,0x00,0x00,0x00,0x00,0x00,0x01,0x12};
static const BYTE kRogCmdM1M2Default[]   = {0x5A,0xD1,0x02,0x08,0x2C,0x02,0x00,0x8E,0x00,0x00,0x00,0x00,0x00,0x00,0x00,0x00,0x02,0x00,0x8E,0x00,0x00,0x00,0x00,0x00,0x00,0x00,0x00,0x02,0x00,0x8F};
static const BYTE kRogCmdM1F18M2F17[]    = {0x5A,0xD1,0x02,0x08,0x2C,0x02,0x00,0x28,0x00,0x00,0x00,0x00,0x00,0x00,0x00,0x00,0x00,0x00,0x00,0x00,0x00,0x00,0x00,0x00,0x00,0x00,0x00,0x02,0x00,0x30};
static const BYTE kRogCmdTriggers[]      = {0x5A,0xD1,0x02,0x09,0x2C,0x01,0x0D,0x00,0x00,0x00,0x00,0x00,0x00,0x00,0x00,0x00,0x00,0x00,0x00,0x00,0x00,0x00,0x00,0x00,0x00,0x00,0x00,0x01,0x0E};
static const BYTE kRogCmdCommit1[]       = {0x5A,0xD1,0x0F,0x20};
static const BYTE kRogCmdCommit2[]       = {0x5A,0xD1,0x06,0x02,0x64,0x64};
static const BYTE kRogCmdCommit3[]       = {0x5A,0xD1,0x04,0x04,0x00,0x64,0x00,0x64};
static const BYTE kRogCmdCommit4[]       = {0x5A,0xD1,0x05,0x04,0x00,0x64,0x00,0x64};

// 全套 14 条顺序写入（HC fire-and-forget 语义 + 累计成败用于诊断；不因
// 单条失败中止——commit 必须照发）。返回成功条数（-1 = 前置不满足）。
static int rogWriteControllerRemapSeq(bool remap) {
    if (g_rog.control == INVALID_HANDLE_VALUE || g_rog.featureLen < 30) return -1;
    struct RogRemapCmd { const BYTE* data; size_t len; };
    const RogRemapCmd seq[14] = {
        {kRogCmdModeGame, sizeof(kRogCmdModeGame)},
        {kRogCmdDpadUpDown, sizeof(kRogCmdDpadUpDown)},
        {kRogCmdDpadLeftRight, sizeof(kRogCmdDpadLeftRight)},
        {kRogCmdJoySticks, sizeof(kRogCmdJoySticks)},
        {kRogCmdShoulder, sizeof(kRogCmdShoulder)},
        {kRogCmdFaceAB, sizeof(kRogCmdFaceAB)},
        {kRogCmdFaceXY, sizeof(kRogCmdFaceXY)},
        {kRogCmdViewMenu, sizeof(kRogCmdViewMenu)},
        {remap ? kRogCmdM1F18M2F17 : kRogCmdM1M2Default,
         remap ? sizeof(kRogCmdM1F18M2F17) : sizeof(kRogCmdM1M2Default)},
        {kRogCmdTriggers, sizeof(kRogCmdTriggers)},
        {kRogCmdCommit1, sizeof(kRogCmdCommit1)},
        {kRogCmdCommit2, sizeof(kRogCmdCommit2)},
        {kRogCmdCommit3, sizeof(kRogCmdCommit3)},
        {kRogCmdCommit4, sizeof(kRogCmdCommit4)},
    };
    int okCount = 0;
    for (const RogRemapCmd& c : seq) {
        std::vector<BYTE> report(g_rog.featureLen, 0);
        std::memcpy(report.data(), c.data, c.len);
        if (HidD_SetFeature(g_rog.control, report.data(), static_cast<ULONG>(report.size())) != FALSE)
            ++okCount;
    }
    return okCount;
}

// 重映射生命周期（A 方案）：电源守卫 + 目标态记忆/节流 + 会话重建 + 5 次重试，
// 全部对齐 rogEnsureXboxFaceEnabled 模板。仅在 ROG 系（hasControl 已绑定）生效。
//
// §15.1 收口①②（W7 第 20 批，裁决授权）：**调用边界所有权**。
// 裁决实读：该函数可被 UI 消息线程（WM_ROG_HIDE_ENSURE）与电源/IPC 线程
// （commitPowerResume → gamepadRecoverAfterResume）到达；旧 `bool` 守卫与普通共享
// 记账对象在无同步读写属下 C++ 数据竞争——POD 不保证不读错，**不能用"最多多写一轮"
// 界定**（该表述已撤回）。处置（不重写设备引擎，只在调用边界落实单一写入者）：
// §21 R1（裁决入口修复单）：同线程递归 vs 跨线程竞争必须分开。
// 旧实现是**全局** atomic guard —— 线程 A 在途时线程 B 在首行 CAS 就失败返回，
// 终态请求根本到不了下面的等待（裁决用两线程最小程序复现：terminalReachedWait=0）。
// 现改为：
//   ① 同线程递归 = `thread_local` RAII 标记（只挡"本线程内 绑定↔重映射 互递归"）；
//   ② 跨线程竞争 = `g_rogRemapBoundaryMx` 边界锁（非终态 try(0)，终态有界等待）。
// 于是"别的线程在跑"不再会挡掉终态请求。
static thread_local bool tls_rogRemapActive = false;
struct RogRemapGuardScope {
    bool acquired;
    RogRemapGuardScope() : acquired(!tls_rogRemapActive) {
        if (acquired) tls_rogRemapActive = true;
    }
    ~RogRemapGuardScope() { if (acquired) tls_rogRemapActive = false; }
    RogRemapGuardScope(const RogRemapGuardScope&) = delete;
    RogRemapGuardScope& operator=(const RogRemapGuardScope&) = delete;
};

static std::timed_mutex g_rogRemapBoundaryMx;
static bool rogRemapTryEnter() { return g_rogRemapBoundaryMx.try_lock(); }
// 终态路径（exit/destroy）：**进入锁之前**的有界等待（锁等待预算，见 kRogRemapTerminalWaitBudgetMs）。
// §21 R3 口径更正：这只是**申请锁的等待预算**——调度可令返回更晚；取得锁之后的同步 HID 写入、
// 重试与全部退出耗时**不受该预算保证**；超时或写入失败都会如实登记（见 rogRemapNoteExitUnresolved）。
static constexpr unsigned kRogRemapTerminalWaitBudgetMs = 800;
static bool rogRemapTryEnterWithin(unsigned ms) {
    return g_rogRemapBoundaryMx.try_lock_for(std::chrono::milliseconds(ms));
}
static void rogRemapLeaveBoundary() { g_rogRemapBoundaryMx.unlock(); }
struct RogRemapBoundaryScope {
    bool entered;
    explicit RogRemapBoundaryScope(unsigned waitMs = 0)
        : entered(waitMs ? rogRemapTryEnterWithin(waitMs) : rogRemapTryEnter()) {}
    ~RogRemapBoundaryScope() { if (entered) rogRemapLeaveBoundary(); }
    RogRemapBoundaryScope(const RogRemapBoundaryScope&) = delete;
    RogRemapBoundaryScope& operator=(const RogRemapBoundaryScope&) = delete;
};

// §21 R2：控制会话原语接缝。产品的 close/bind/feature 读写全部经这里，自测用它替换成
// 假设备（**同一入口、同一协调函数**，不另抄一套测试算法）；生产默认走真实实现。
struct RogSessionOps {
    void (*closeSession)(bool keepIdentity);
    bool (*ensureSession)();            // 重建控制会话；返回 hasControl
    void (*retryDelay)();
    int  (*writeRemapSeq)(bool remap);  // 返回成功条数（14 = 成功）
    bool (*writeFace)();
    std::string (*readBack)();
};
static RogSessionOps g_rogSessionOpsFake{};                     // 仅自测填充
static std::atomic<bool> g_rogSessionOpsFakeActive{false};      // 仅自测置位
static const RogSessionOps& rogSessionOps();                    // 实现在真实原语之后

// §21 R3：终态结果必须如实登记（超时/写失败 ⇒ M1M2Default 可能未写回）。
// 设备代次声明提前到此处（下面的代次块不再重复声明）。
static std::atomic<unsigned long long> g_rogRemapDevGen{1};
static std::atomic<unsigned long long> g_rogRemapExitUnresolved{0};
static void rogRemapNoteExitUnresolved(const char* stage) {
    g_rogRemapExitUnresolved.fetch_add(1, std::memory_order_acq_rel);
    if (g_rogSessionOpsFakeActive.load(std::memory_order_acquire)) return;
    appendNativeLifecycleLog("rog.controller-remap-exit-unresolved", {
        {"stage", stage ? stage : ""},
        {"count", g_rogRemapExitUnresolved.load(std::memory_order_acquire)},
        {"devGen", g_rogRemapDevGen.load(std::memory_order_acquire)}
    });
}
// 自测期静默（避免把合成事件写进产品日志）；生产恒为 false。
static std::atomic<bool> g_rogRemapLogQuiet{false};
static void rogRemapLog(const char* event, json detail) {
    if (g_rogRemapLogQuiet.load(std::memory_order_acquire)) return;
    appendNativeLifecycleLog(event, std::move(detail));
}
static bool rogRemapTerminalReason(const char* why) {
    return why && (std::strcmp(why, "exit") == 0 || std::strcmp(why, "destroy") == 0);
}

// ── §14.2（W7 第 19 批，裁决授权定点修复）：重映射节流 = 尝试记账 × 成功应用 ──
// 裁决实读的旧缺陷：只有一份「成功应用」记账（remapTargetKnown/remapTarget），
// 而节流入口要求 known && 同目标 ⇒
//   ① 初始 known=false 时连续同目标失败永远绕过节流，每次调用都进整轮 5 次重试
//      （含 Sleep(80)，最坏 ~400ms 卡 UI 线程）；
//   ② 已有成功目标 A 后尝试 B 失败：B 的失败退避借用不到 A 的键（target 不等），
//      下一次 B 调用同样再进整轮重试。
// 现分离两份记账，并以代次锚定：
//   applied（成功应用态）：最近一次成功写入、且此后无失败尝试的目标 —— 5s 内同目标
//                          可直接复用（返回 true，不写 14 条 feature）。
//   attempt（尝试记账）  ：最近一次尝试（无论成败）的目标/时刻/结果 —— 同目标失败
//                          5s 内退避（**返回 false**，不得报伪成功）。
// 失败作废 applied：半写状态无法证明设备仍处原目标态，禁止再复用。
// 失效锚：设备代次（DBT_DEVNODES_CHANGED / 身份丢失后重获）× 电源代次（休眠唤醒）；
//         目标变化由 remap 键天然区分；重入由 RogRemapGuardScope 挡在记账之前
//         （重入调用直接 false，不读不写记账）。
// 调用方契约（实读两处调用点 `hid-bound` 与 xbox-face 均忽略返回值）：
//         true = 目标态当前已应用（本次写入成功，或 5s 内的成功复用）；
//         false = 未应用（写入失败，或被失败退避抑制）——抑制失败时不得返回 true。
struct RogRemapThrottle {
    bool appliedKnown = false;
    bool appliedTarget = false;
    ULONGLONG appliedTick = 0;
    bool attemptKnown = false;
    bool attemptTarget = false;
    bool attemptOk = false;
    ULONGLONG attemptTick = 0;
    unsigned long long anchorDevGen = 0;
    unsigned long long anchorPowerGen = 0;
    // §15.1 收口③ / §21 R3：提交时的**绑定签名**（单原子打包值，见 rogRemapPackSig）。
    // 裁决更正：bool 身份 + 产品 PID 不是完整设备身份，且双原子字段不构成一致快照；
    // 这里改成"单原子打包 = 控制接口实例代次(epoch) | 身份位 | 产品号 | 控制路径哈希"，
    // 只服务本缓存必需的两个判据：噪声不失效、真实换代失效。
    bool boundKnown = false;
    unsigned long long boundSig = 0;
};
static constexpr ULONGLONG kRogRemapThrottleMs = 5000;
// 记账不随 RogInputSession 关闭清零（代次负责失效），故置于会话结构之外；
// **只在持有 g_rogRemapBoundaryMx 的区间内读写**（调用边界所有权，§15.1 ①③）。
static RogRemapThrottle g_rogRemapThrottle;

// 设备代次：只在**相关身份变化**时推进——① 身份丢失后重新匹配到设备（断连→重连）；
// ② 设备树变化后复核确认"我们绑定的身份/产品号"确实变了。通用设备树通知本身**不**推进
// （鼠标/虚拟端枚举也会触发它，会把刚建立的失败退避反复打掉，§15.1 ③）。
// 设备代次（声明见上方 §21 R3 块）。
// DBT_DEVNODES_CHANGED 只置"待复核"；由边界内复核决定是否放弃退避。
static std::atomic<bool> g_rogRemapDevTreeDirty{false};
// 当前绑定签名镜像：**单原子打包**（跨线程只读；避免双原子撕裂快照，也避免读 std::wstring）。
// 打包 = epoch(32) | 身份位(1) | productId(16) | 控制路径哈希(15)
static std::atomic<unsigned long long> g_rogRemapBoundSig{0};
static unsigned long long g_rogRemapLastPathHash = 0;
static unsigned long long rogRemapPackSig(unsigned epoch, bool identity, unsigned short pid,
                                          unsigned long long pathHash15) {
    return (static_cast<unsigned long long>(epoch) << 32) |
           (identity ? (1ull << 31) : 0ull) |
           (static_cast<unsigned long long>(pid) << 15) |
           (pathHash15 & 0x7FFFull);
}
static unsigned long long rogRemapPathHash15(const std::wstring& path) {
    unsigned long long h = 1469598103934665603ull;           // FNV-1a
    for (wchar_t c : path) { h ^= static_cast<unsigned long long>(c); h *= 1099511628211ull; }
    return h & 0x7FFFull;
}

enum class RogRemapPlan { Write, ReuseApplied, DeferFailed };
enum class RogRemapDirty { None, Noise, Relevant };

static const char* rogRemapPlanName(RogRemapPlan plan) {
    switch (plan) {
        case RogRemapPlan::ReuseApplied: return "reuse-applied";
        case RogRemapPlan::DeferFailed:  return "defer-failed";
        default:                         return "write";
    }
}

// 代次推进：只在"相关身份/有效代次变化"时调用（原子写 + 一条事件；不读记账，
// 避免绑定线程触碰受边界锁保护的记账对象）。
static void rogRemapNoteDeviceGeneration(const char* why) {
    const unsigned long long gen = g_rogRemapDevGen.fetch_add(1, std::memory_order_acq_rel) + 1;
    appendNativeLifecycleLog("rog.remap-cache-invalidated", {
        {"why", why ? why : ""}, {"devGen", gen}
    });
}

// 通用设备树通知：只置脏（待复核），不推进代次、不碰记账。
static void rogRemapNoteDeviceTreeChange() {
    g_rogRemapDevTreeDirty.store(true, std::memory_order_release);
}

// 纯判定（不推进代次、不写日志，便于隔离自测）：本次脏事件是否与"我们的绑定"相关。
// Relevant ⇒ 调用方推进代次（据此放弃退避）；Noise ⇒ 保留退避，只刷新签名快照。
// 签名取自**单个**原子量 ⇒ 不会出现"身份与产品号来自不同时刻"的撕裂快照。
static RogRemapDirty rogRemapResolveDirty(RogRemapThrottle& t) {
    if (!g_rogRemapDevTreeDirty.exchange(false, std::memory_order_acq_rel))
        return RogRemapDirty::None;
    const unsigned long long sig = g_rogRemapBoundSig.load(std::memory_order_acquire);
    if (!t.boundKnown) {          // 尚无签名 ⇒ 无缓存可保护：只记快照，不放弃退避
        t.boundKnown = true;
        t.boundSig = sig;
        return RogRemapDirty::Noise;
    }
    return (sig != t.boundSig) ? RogRemapDirty::Relevant : RogRemapDirty::Noise;
}

static bool rogRemapAnchorStale(const RogRemapThrottle& t, unsigned long long devGen,
                                unsigned long long powerGen) {
    if (!t.appliedKnown && !t.attemptKnown) return false;
    return t.anchorDevGen != devGen || t.anchorPowerGen != powerGen;
}

static RogRemapPlan rogRemapPlan(const RogRemapThrottle& t, bool remap, ULONGLONG now,
                                 unsigned long long devGen, unsigned long long powerGen) {
    if (rogRemapAnchorStale(t, devGen, powerGen)) return RogRemapPlan::Write;
    if (t.appliedKnown && t.appliedTarget == remap &&
        now - t.appliedTick < kRogRemapThrottleMs) {
        return RogRemapPlan::ReuseApplied;
    }
    if (t.attemptKnown && t.attemptTarget == remap && !t.attemptOk &&
        now - t.attemptTick < kRogRemapThrottleMs) {
        return RogRemapPlan::DeferFailed;
    }
    return RogRemapPlan::Write;
}

static void rogRemapRecordResult(RogRemapThrottle& t, bool remap, bool ok, ULONGLONG now,
                                 unsigned long long devGen, unsigned long long powerGen) {
    t.anchorDevGen = devGen;
    t.anchorPowerGen = powerGen;
    // §15.1 ①④ 版本化提交：结果按**启动时代次**（devGen/powerGen 入参）入账——
    // 尝试期间发生的代次变化不会被旧结果"满足"，下一次调用必然重写（见受控交错测试）。
    // 同时记录提交时的**打包**绑定签名（单原子读，供设备树脏事件复核相关性）。
    t.boundKnown = true;
    t.boundSig = g_rogRemapBoundSig.load(std::memory_order_acquire);
    t.attemptKnown = true;
    t.attemptTarget = remap;
    t.attemptOk = ok;
    t.attemptTick = now;
    if (!ok) {
        t.appliedKnown = false;   // 半写状态：不得再宣称已应用
        return;
    }
    t.appliedKnown = true;
    t.appliedTarget = remap;
    t.appliedTick = now;
}

// ── §14.2 + §15.1 隔离自测：假时钟 + 假写入结果（纯逻辑，不碰 HID/固件、不写产品日志）
// ① 顺序六场景：初始连续失败 / 同目标成功复用 / A→B 失败 / 退避边界 / 重连代次 / 唤醒静默；
// ② §15.1 受控交错：两请求竞争（真实边界锁 + 真实两线程握手）、设备树噪声 vs 相关身份变化、
//    尝试期间代次变化（版本化提交）、真实线程下边界锁互斥计数、终态路径有界等待（第 20 批补丁 A）。
// 断言：每次调用的 plan（产品**仅在 plan==Write 时**才进入 14 条 feature 写入循环与失败重试/
// Sleep(80)/会话重建 ⇒ plan 序列即实际写入回合与枚举次数）、跨调用计数、返回语义
// （true 仅当目标态已应用；退避抑制必须 false）、脏事件复核判定。
// 与 --oem-identity-selftest 同口径：本地可跑，不需要 ROG 或任何设备。
// §21 入口测试脚手架（仅自测使用；生产路径不触碰）。
static bool rogEnsureControllerRemap(bool remap, const char* reason);   // 入口前置声明（自测要经它）
struct RogEntryTestFake {
    std::atomic<int> writeSeqCalls{0};
    std::atomic<int> closeCalls{0};
    std::atomic<int> ensureCalls{0};
    std::atomic<int> writeFaceCalls{0};
    std::atomic<int> retryDelayCalls{0};
    std::atomic<int> lastRemapTarget{-1};
    std::atomic<int> writeSeqFailCount{0};   // 0 = 返回 14（成功）
    std::atomic<int> holdMs{0};              // 写入前占用时长（模拟在途）
};
static RogEntryTestFake* g_entryTestFake = nullptr;
static std::atomic<int> g_entryTestNestedResult{-1};
// §22 自测观察点（生产不读取）：恢复 bind 是否被执行/被延期/被丢弃。
static std::atomic<int> g_entryTestBindCalls{0};
static std::atomic<int> g_entryTestRecoverBindDeferred{0};
static std::atomic<int> g_entryTestRecoverBindDropped{0};
static void (*g_entryTestEnsureHook)() = nullptr;
// 模拟"绑定成功处补写重映射"（bind 收尾 → remap 入口），用于验证同线程递归抑制。
static void rogEntryTestEnsureHook() {
    g_entryTestNestedResult.store(rogEnsureControllerRemap(true, "hid-bound") ? 1 : 0);
}

static bool rogRemapThrottleSelfTest() {
    struct Step {
        const char* label;
        ULONGLONG dtMs;      // 相对上一个步骤的假时钟推进量
        int genBump;         // 0=无；1=设备代次 +1（身份重获/相关变化）；2=电源代次 +1（唤醒）
        int dirty;           // 0=无；1=设备树噪声（签名不变）；2=设备树相关（签名变化）
        bool skip;           // true=电源静默早退：产品在 plan 之前 return，不记账
        bool remap;          // 本次调用的目标
        bool writeOk;        // 若进入写入循环，本次假写入结果
        RogRemapPlan want;   // 期望 plan（skip 步骤不参与）
        bool wantReturn;     // 期望返回给调用方的值
        RogRemapDirty wantDirty;   // dirty!=0 时生效
    };
    struct Scenario {
        const char* name;
        std::vector<Step> steps;
        int wantWrites, wantReuses, wantDefers;
    };
    const RogRemapDirty DN = RogRemapDirty::None;
    std::vector<Scenario> scenarios;
    // ① 初始连续失败（applied/attempt 从未为真）+ 退避到期。
    //    旧实现：known=false 使节流永不生效 ⇒ 第 2、3 次调用各再进一整轮 5 次重试。
    scenarios.push_back({"initial-consecutive-failures", {
        {"fail-1",                0,    0, 0, false, true,  false, RogRemapPlan::Write,       false, DN},
        {"fail-2-within-5s",      1000, 0, 0, false, true,  false, RogRemapPlan::DeferFailed, false, DN},
        {"fail-3-within-5s",      2000, 0, 0, false, true,  false, RogRemapPlan::DeferFailed, false, DN},
        {"backoff-expired",       2000, 0, 0, false, true,  true,  RogRemapPlan::Write,       true,  DN},
    }, 2, 0, 2});
    // ② 同目标成功复用（5s 内不重写）+ 超窗刷新。
    scenarios.push_back({"same-target-success-reuse", {
        {"apply-ok",              0,    0, 0, false, true,  true,  RogRemapPlan::Write,       true,  DN},
        {"reuse-1",               1000, 0, 0, false, true,  false, RogRemapPlan::ReuseApplied, true,  DN},
        {"reuse-2",               3000, 0, 0, false, true,  false, RogRemapPlan::ReuseApplied, true,  DN},
        {"refresh-after-window",  2000, 0, 0, false, true,  true,  RogRemapPlan::Write,       true,  DN},
    }, 2, 2, 0});
    // ③ 目标 A→B 失败：B 不得复用 A 的成功键；B 的失败退避生效；A 因 B 失败被作废须重写。
    scenarios.push_back({"target-a-then-b-failure", {
        {"apply-A",               0,    0, 0, false, true,  true,  RogRemapPlan::Write,       true,  DN},
        {"try-B-fails",           100,  0, 0, false, false, false, RogRemapPlan::Write,       false, DN},
        {"B-repeat-within-5s",    1000, 0, 0, false, false, false, RogRemapPlan::DeferFailed, false, DN},
        {"A-again-after-B-fail",  1000, 0, 0, false, true,  true,  RogRemapPlan::Write,       true,  DN},
    }, 3, 0, 1});
    // ④ 退避边界：<5000ms 抑制、=5000ms 放行（与旧实现的窗口口径一致）。
    scenarios.push_back({"backoff-boundary", {
        {"fail",                  0,    0, 0, false, true,  false, RogRemapPlan::Write,       false, DN},
        {"at-4999ms",             4999, 0, 0, false, true,  false, RogRemapPlan::DeferFailed, false, DN},
        {"at-5000ms",             1,    0, 0, false, true,  true,  RogRemapPlan::Write,       true,  DN},
    }, 2, 0, 1});
    // ⑤ 设备代次变化（断连重连/相关身份变化）：退避窗口内的同目标调用必须重新尝试。
    scenarios.push_back({"device-generation-change", {
        {"fail",                  0,    0, 0, false, true,  false, RogRemapPlan::Write,       false, DN},
        {"reconnect-devgen-bump", 1000, 1, 0, false, true,  true,  RogRemapPlan::Write,       true,  DN},
    }, 2, 0, 0});
    // ⑥ 电源静默（跳过不记账）→ 唤醒后电源代次变化 ⇒ 必须重写，不得沿用休眠前的复用。
    scenarios.push_back({"power-quiet-then-resume", {
        {"apply-ok",              0,    0, 0, false, true,  true,  RogRemapPlan::Write,       true,  DN},
        {"power-quiet-skip",      100,  0, 0, true,  true,  false, RogRemapPlan::Write,       false, DN},
        {"reuse-still-valid",     1000, 0, 0, false, true,  false, RogRemapPlan::ReuseApplied, true,  DN},
        {"resume-powergen-bump",  100,  2, 0, false, true,  true,  RogRemapPlan::Write,       true,  DN},
    }, 2, 1, 0});
    // ⑦ 设备树噪声（鼠标/虚拟端等无关设备增删）：置脏但不推进代次 ⇒ 保留失败退避（§15.1 ③）。
    scenarios.push_back({"devnode-noise-keeps-backoff", {
        {"fail",                  0,    0, 0, false, true,  false, RogRemapPlan::Write,       false, DN},
        {"noise-dirty-1",         1000, 0, 1, false, true,  false, RogRemapPlan::DeferFailed, false, RogRemapDirty::Noise},
        {"noise-dirty-2",         1000, 0, 1, false, true,  false, RogRemapPlan::DeferFailed, false, RogRemapDirty::Noise},
    }, 1, 0, 2});
    // ⑧ 相关身份变化（绑定签名真的变了）⇒ 放弃退避、允许重写（替换设备/重枚举到别的实例）。
    scenarios.push_back({"bound-identity-change-drops-backoff", {
        {"fail",                  0,    0, 0, false, true,  false, RogRemapPlan::Write, false, DN},
        {"relevant-dirty",        1000, 0, 2, false, true,  true,  RogRemapPlan::Write, true,  RogRemapDirty::Relevant},
    }, 2, 0, 0});
    // ⑨ 真实重绑（身份丢失后重获，代次推进）⇒ 退避窗口内也必须能重写。
    scenarios.push_back({"rebind-drops-backoff", {
        {"fail",                  0,    0, 0, false, true,  false, RogRemapPlan::Write, false, DN},
        {"identity-reacquired",   1000, 1, 0, false, true,  true,  RogRemapPlan::Write, true,  DN},
    }, 2, 0, 0});

    bool pass = true;
    std::string report = "rog-remap-throttle-selftest (pure logic, no hardware):\n";
    for (const Scenario& sc : scenarios) {
        RogRemapThrottle st;
        unsigned long long devGen = 1;
        unsigned long long powerGen = 1;
        ULONGLONG clock = 100000;
        int writes = 0, reuses = 0, defers = 0;
        bool ok = true;
        std::string detail;
        // 场景内"当前绑定签名"镜像（写真实原子量；打包值，供脏事件复核与提交时记录）。
        bool mirrorIdent = true;
        unsigned short mirrorPid = 0x1ABE;
        const unsigned mirrorEpoch = 1;
        const unsigned long long mirrorPath = 0x1234;
        for (const Step& s : sc.steps) {
            clock += s.dtMs;
            if (s.genBump == 1) ++devGen;
            if (s.genBump == 2) ++powerGen;
            if (s.skip) continue;   // 电源静默：产品在 plan 之前早退，不读不写记账
            if (s.dirty != 0) {
                if (s.dirty == 2) {          // 相关：绑定签名真的变了
                    if (mirrorIdent) { mirrorIdent = false; mirrorPid = 0; }
                    else { mirrorIdent = true; mirrorPid = static_cast<unsigned short>(mirrorPid + 1); }
                }
                g_rogRemapBoundSig.store(rogRemapPackSig(mirrorEpoch, mirrorIdent, mirrorPid, mirrorPath),
                                         std::memory_order_release);
                g_rogRemapDevTreeDirty.store(true, std::memory_order_release);
                const RogRemapDirty d = rogRemapResolveDirty(st);
                if (d != s.wantDirty) {
                    ok = false;
                    detail += std::string(" [") + s.label + " dirty got=" +
                              (d == RogRemapDirty::Relevant ? "relevant" :
                               (d == RogRemapDirty::Noise ? "noise" : "none")) + "]";
                }
                if (d == RogRemapDirty::Relevant) ++devGen;   // 产品在相关时推进代次
            }
            g_rogRemapBoundSig.store(rogRemapPackSig(mirrorEpoch, mirrorIdent, mirrorPid, mirrorPath),
                                     std::memory_order_release);
            const RogRemapPlan plan = rogRemapPlan(st, s.remap, clock, devGen, powerGen);
            bool got = false;
            switch (plan) {
                case RogRemapPlan::ReuseApplied:
                    ++reuses;
                    got = true;
                    break;
                case RogRemapPlan::DeferFailed:
                    ++defers;
                    got = false;      // 失败被抑制 ⇒ 不得报伪成功
                    break;
                case RogRemapPlan::Write: {
                    ++writes;         // = 产品进入 14 条 feature 写入循环（含失败重试）
                    got = s.writeOk;  // 假写入结果
                    rogRemapRecordResult(st, s.remap, got, clock, devGen, powerGen);
                    break;
                }
            }
            if (plan != s.want || got != s.wantReturn) {
                ok = false;
                detail += std::string(" [") + s.label + " got=" + rogRemapPlanName(plan) + "/" +
                          (got ? "true" : "false") + " want=" + rogRemapPlanName(s.want) + "/" +
                          (s.wantReturn ? "true" : "false") + "]";
            }
        }
        if (writes != sc.wantWrites || reuses != sc.wantReuses || defers != sc.wantDefers) {
            ok = false;
            detail += " [counts got=w" + std::to_string(writes) + "/r" + std::to_string(reuses) +
                      "/d" + std::to_string(defers) + " want=w" + std::to_string(sc.wantWrites) +
                      "/r" + std::to_string(sc.wantReuses) + "/d" + std::to_string(sc.wantDefers) + "]";
        }
        if (!ok) pass = false;
        report += std::string("  ") + (ok ? "PASS " : "FAIL ") + sc.name +
                  " writeRuns=" + std::to_string(writes) +
                  " reuse=" + std::to_string(reuses) +
                  " deferred=" + std::to_string(defers) + detail + "\n";
    }

    // ⑩ 受控交错：两请求竞争（**真实**边界锁 + 真实两线程握手）。
    //    A 持锁期间 B 必须进不来（且 B 不读不写记账）；A 提交后 C 才允许复用。
    {
        bool ok = true;
        std::string detail;
        RogRemapThrottle st;
        std::atomic<int> stage{0};
        std::atomic<bool> bEntered{false};
        std::atomic<bool> aEntered{false};
        std::thread a([&]() {
            const bool got = rogRemapTryEnter();
            aEntered.store(got, std::memory_order_release);
            if (got) {
                if (rogRemapPlan(st, true, 100000, 1, 1) != RogRemapPlan::Write)
                    aEntered.store(false, std::memory_order_release);
                rogRemapRecordResult(st, true, true, 100010, 1, 1);
            }
            stage.store(1, std::memory_order_release);
            while (stage.load(std::memory_order_acquire) != 2) std::this_thread::yield();
            if (got) rogRemapLeaveBoundary();
        });
        while (stage.load(std::memory_order_acquire) != 1) std::this_thread::yield();
        if (rogRemapTryEnter()) {          // B：应与 A 互斥
            bEntered.store(true, std::memory_order_release);
            rogRemapLeaveBoundary();
        }
        stage.store(2, std::memory_order_release);
        a.join();
        if (!aEntered.load()) { ok = false; detail += " [A 未取到边界锁]"; }
        if (bEntered.load()) { ok = false; detail += " [B 与 A 并发进入]"; }
        const RogRemapPlan after = rogRemapPlan(st, true, 101000, 1, 1);
        if (after != RogRemapPlan::ReuseApplied) { ok = false; detail += " [A 提交后未复用]"; }
        if (!ok) pass = false;
        report += std::string("  ") + (ok ? "PASS " : "FAIL ") + "contended-two-requests" + detail + "\n";
    }

    // ⑪ 受控交错：尝试期间代次变化（版本化提交）——旧结果不得满足新代次。
    {
        bool ok = true;
        std::string detail;
        RogRemapThrottle st;
        unsigned long long gen = 1, power = 1;
        if (rogRemapPlan(st, true, 100000, gen, power) != RogRemapPlan::Write) {
            ok = false; detail += " [首个尝试未进入写入]";
        }
        ++gen;                                                     // 尝试进行中：相关身份变化
        rogRemapRecordResult(st, true, true, 100050, 1, power);     // 结果按**启动时代次 1**入账
        if (rogRemapPlan(st, true, 100100, gen, power) != RogRemapPlan::Write) {
            ok = false; detail += " [新代次被旧结果满足]";
        }
        if (rogRemapPlan(st, true, 100100, 1, power) != RogRemapPlan::ReuseApplied) {
            ok = false; detail += " [同代次未复用]";
        }
        if (!ok) pass = false;
        report += std::string("  ") + (ok ? "PASS " : "FAIL ") + "stale-attempt-midflight-gen" + detail + "\n";
    }

    // ⑫ 边界锁互斥计数（真实两线程 × 4000 次尝试）：任一时刻在临界区内的线程数必须 ≤1。
    {
        bool ok = true;
        std::string detail;
        std::atomic<int> inFlight{0};
        std::atomic<bool> overlap{false};
        auto worker = [&]() {
            for (int i = 0; i < 4000; ++i) {
                if (!rogRemapTryEnter()) continue;
                if (inFlight.fetch_add(1, std::memory_order_acq_rel) != 0)
                    overlap.store(true, std::memory_order_release);
                inFlight.fetch_sub(1, std::memory_order_acq_rel);
                rogRemapLeaveBoundary();
            }
        };
        std::thread t1(worker), t2(worker);
        t1.join();
        t2.join();
        if (overlap.load()) { ok = false; detail += " [出现并发进入]"; }
        if (inFlight.load() != 0) { ok = false; detail += " [计数未归零]"; }
        if (!ok) pass = false;
        report += std::string("  ") + (ok ? "PASS " : "FAIL ") + "boundary-mutual-exclusion" + detail + "\n";
    }

    // ⑬ 终态路径有界等待（第 20 批补丁 A）：持锁者在位时**非终态**调用必失败；
    //    **终态**调用应在持锁者释放后、界内取得（保证 exit/destroy 的 M1M2Default 写回不被跳过）。
    {
        bool ok = true;
        std::string detail;
        ULONGLONG waited = 0;
        std::atomic<int> stage{0};
        std::thread holder([&]() {
            if (rogRemapTryEnter()) {
                stage.store(1, std::memory_order_release);
                std::this_thread::sleep_for(std::chrono::milliseconds(150));
                rogRemapLeaveBoundary();
            } else {
                stage.store(-1, std::memory_order_release);
            }
        });
        while (stage.load(std::memory_order_acquire) == 0) std::this_thread::yield();
        if (stage.load(std::memory_order_acquire) != 1) {
            ok = false;
            detail += " [持锁线程未取得边界锁]";
        }
        if (rogRemapTryEnter()) {                 // 非终态：必须进不来
            ok = false;
            detail += " [非终态调用竟进入]";
            rogRemapLeaveBoundary();
        }
        const ULONGLONG t0 = GetTickCount64();
        const bool got = rogRemapTryEnterWithin(kRogRemapTerminalWaitBudgetMs);
        waited = GetTickCount64() - t0;
        if (got) rogRemapLeaveBoundary();
        if (!got) {
            ok = false;
            detail += " [终态等待未取得]";
        } else if (waited > kRogRemapTerminalWaitBudgetMs) {
            ok = false;
            detail += " [等待超界]";
        }
        holder.join();
        if (!ok) pass = false;
        report += std::string("  ") + (ok ? "PASS " : "FAIL ") + "terminal-path-bounded-wait"
                  + " waitedMs=" + std::to_string(waited) + detail + "\n";
    }

    // ⑭ §21 R1/R2/R3：**生产入口**测试（同一入口 + 假设备写入，不另抄一套算法）。
    // 覆盖：终态在竞争下仍能等到锁并真的执行 remap(false)；非终态竞争被跳；
    //       在途写期间外部 xbox-face 不得 close/rebind 会话；同线程 bind 回调仍被抑制；
    //       退出意图下晚到的启用请求不得重新应用 remap(true)；等待预算耗尽与写失败被如实登记。
    // 线程握手一律带测试侧截止时间，失败即 FAIL，不挂死。
    {
        RogEntryTestFake fake;
        g_entryTestFake = &fake;
        g_entryTestEnsureHook = nullptr;
        g_rogSessionOpsFake = RogSessionOps{
            +[](bool k) { g_entryTestFake->closeCalls.fetch_add(1); (void)k; },
            +[]() -> bool {
                g_entryTestFake->ensureCalls.fetch_add(1);
                if (g_entryTestEnsureHook) g_entryTestEnsureHook();
                return true;
            },
            +[]() { g_entryTestFake->retryDelayCalls.fetch_add(1); },
            +[](bool remap) -> int {
                g_entryTestFake->writeSeqCalls.fetch_add(1);
                g_entryTestFake->lastRemapTarget.store(remap ? 1 : 0);
                const int hold = g_entryTestFake->holdMs.load();
                if (hold > 0) std::this_thread::sleep_for(std::chrono::milliseconds(hold));
                const int fail = g_entryTestFake->writeSeqFailCount.load();
                return fail > 0 ? fail : 14;
            },
            +[]() -> bool { g_entryTestFake->writeFaceCalls.fetch_add(1); return true; },
            +[]() -> std::string { return std::string("FAKE"); }
        };
        g_rogSessionOpsFakeActive.store(true, std::memory_order_release);
        g_rogRemapLogQuiet.store(true, std::memory_order_release);

        g_rog.identityMatched = true;
        g_rog.hasControl = true;
        g_powerLifecycle.store(PowerLifecycle::Ready, std::memory_order_release);
        g_inputReady.store(true, std::memory_order_release);
        g_exitRequested.store(false, std::memory_order_release);

        auto resetState = [&](int holdMs, int failCount) {
            fake.writeSeqCalls.store(0); fake.closeCalls.store(0); fake.ensureCalls.store(0);
            fake.writeFaceCalls.store(0); fake.retryDelayCalls.store(0);
            fake.lastRemapTarget.store(-1); fake.writeSeqFailCount.store(failCount);
            fake.holdMs.store(holdMs);
            g_rogRemapThrottle = RogRemapThrottle{};
            g_rogRemapDevGen.fetch_add(1, std::memory_order_acq_rel);
            g_rogRemapBoundSig.store(rogRemapPackSig(9, true, 0x1ABE, 0x77),
                                     std::memory_order_release);
        };
        auto waitUntil = [](const std::atomic<int>& v, int want, int ms) {
            const ULONGLONG deadline = GetTickCount64() + static_cast<ULONGLONG>(ms);
            while (v.load() != want && GetTickCount64() < deadline) std::this_thread::yield();
            return v.load() == want;
        };

        // T1：在途 remap 期间，终态 exit **真的执行** remap(false)（裁决反例的回归测试）
        {
            bool ok = true; std::string detail;
            resetState(200, 0);
            bool aResult = false;
            std::thread a([&]() { aResult = rogEnsureControllerRemap(true, "window-hidden"); });
            if (!waitUntil(fake.writeSeqCalls, 1, 3000)) { ok = false; detail += " [A 未开始写入(超时)]"; }
            const ULONGLONG t0 = GetTickCount64();
            const bool bResult = rogEnsureControllerRemap(false, "exit");
            const ULONGLONG waited = GetTickCount64() - t0;
            a.join();
            if (!bResult) { ok = false; detail += " [终态未执行]"; }
            if (fake.writeSeqCalls.load() != 2) { ok = false; detail += " [写入次数!=2]"; }
            if (fake.lastRemapTarget.load() != 0) { ok = false; detail += " [终态未以 remap(false) 执行]"; }
            if (waited > kRogRemapTerminalWaitBudgetMs + 200) { ok = false; detail += " [等待超预算]"; }
            if (!aResult) { ok = false; detail += " [A 未成功]"; }
            if (!ok) pass = false;
            report += std::string("  ") + (ok ? "PASS " : "FAIL ") + "entry-exit-during-remap"
                      + " waitedMs=" + std::to_string(waited) + detail + "\n";
        }
        // T2：非终态竞争请求被跳过（不写、不读记账）
        {
            bool ok = true; std::string detail;
            resetState(200, 0);
            std::thread a([&]() { (void)rogEnsureControllerRemap(true, "window-hidden"); });
            if (!waitUntil(fake.writeSeqCalls, 1, 3000)) { ok = false; detail += " [A 未开始写入(超时)]"; }
            g_rogRemapDevGen.fetch_add(1, std::memory_order_acq_rel);   // 让节流判 Write
            const bool bResult = rogEnsureControllerRemap(true, "window-hidden");
            a.join();
            if (bResult) { ok = false; detail += " [非终态竞争未被跳过]"; }
            if (fake.writeSeqCalls.load() != 1) { ok = false; detail += " [非终态也写了]"; }
            if (!ok) pass = false;
            report += std::string("  ") + (ok ? "PASS " : "FAIL ") + "entry-nonterminal-contention" + detail + "\n";
        }
        // T3：在途写期间，外部 xbox-face 不得 close/rebind 同一控制会话（§21 R2）
        {
            bool ok = true; std::string detail;
            resetState(250, 0);
            std::thread a([&]() { (void)rogEnsureControllerRemap(true, "window-hidden"); });
            if (!waitUntil(fake.writeSeqCalls, 1, 3000)) { ok = false; detail += " [A 未开始写入(超时)]"; }
            const bool bResult = rogEnsureXboxFaceEnabled("window-hidden");
            a.join();
            if (bResult) { ok = false; detail += " [xbox-face 未被跳过]"; }
            if (fake.closeCalls.load() != 0 || fake.ensureCalls.load() != 0 ||
                fake.writeFaceCalls.load() != 0) {
                ok = false;
                detail += " [在途写期间会话被外部 close/rebind]";
            }
            if (!ok) pass = false;
            report += std::string("  ") + (ok ? "PASS " : "FAIL ") + "entry-session-not-closed-during-write" + detail + "\n";
        }
        // T4：同线程绑定回调重入仍被抑制（xbox-face → 核心；bind 收尾回调 → 入口）
        {
            bool ok = true; std::string detail;
            resetState(0, 0);
            g_entryTestNestedResult.store(-1);
            g_entryTestEnsureHook = &rogEntryTestEnsureHook;
            const bool outer = rogEnsureXboxFaceEnabled("window-hidden");
            g_entryTestEnsureHook = nullptr;
            if (!outer) { ok = false; detail += " [外层 xbox-face 失败]"; }
            if (g_entryTestNestedResult.load() != 0) { ok = false; detail += " [同线程重入未被抑制]"; }
            if (fake.writeSeqCalls.load() != 1) { ok = false; detail += " [写入次数!=1]"; }
            if (!ok) pass = false;
            report += std::string("  ") + (ok ? "PASS " : "FAIL ") + "entry-thread-recursion-suppressed" + detail + "\n";
        }
        // T5：退出意图下，晚到的启用请求不得重新应用 remap(true)；终态写回仍允许
        {
            bool ok = true; std::string detail;
            resetState(0, 0);
            g_exitRequested.store(true, std::memory_order_release);
            const bool lateEnable = rogEnsureControllerRemap(true, "hid-bound");
            const int seqAfterLate = fake.writeSeqCalls.load();
            const bool lateResume = rogEnsureXboxFaceEnabled("resume");
            const int seqAfterResume = fake.writeSeqCalls.load();
            const bool terminalWrite = rogEnsureControllerRemap(false, "exit");
            g_exitRequested.store(false, std::memory_order_release);
            if (lateEnable) { ok = false; detail += " [hid-bound 在退出后仍启用]"; }
            if (lateResume && seqAfterResume > seqAfterLate) { ok = false; detail += " [resume 在退出后仍应用 remap]"; }
            if (!terminalWrite) { ok = false; detail += " [终态写回被误挡]"; }
            if (!ok) pass = false;
            report += std::string("  ") + (ok ? "PASS " : "FAIL ") + "entry-exit-intent-blocks-late-enable" + detail + "\n";
        }
        // T6：终态等待预算耗尽 ⇒ 不执行写，且登记 exit-unresolved(wait-budget-exhausted)
        {
            bool ok = true; std::string detail;
            resetState(1200, 0);
            const unsigned long long before =
                g_rogRemapExitUnresolved.load(std::memory_order_acquire);
            std::thread a([&]() { (void)rogEnsureControllerRemap(true, "window-hidden"); });
            if (!waitUntil(fake.writeSeqCalls, 1, 3000)) { ok = false; detail += " [A 未开始写入(超时)]"; }
            const int writesBefore = fake.writeSeqCalls.load();
            const bool bResult = rogEnsureControllerRemap(false, "destroy");
            const int writesAfter = fake.writeSeqCalls.load();
            a.join();
            if (bResult) { ok = false; detail += " [预算耗尽却报成功]"; }
            if (writesAfter != writesBefore) { ok = false; detail += " [预算耗尽却执行了写]"; }
            if (g_rogRemapExitUnresolved.load(std::memory_order_acquire) != before + 1) {
                ok = false; detail += " [未登记 exit-unresolved]";
            }
            if (!ok) pass = false;
            report += std::string("  ") + (ok ? "PASS " : "FAIL ") + "entry-terminal-wait-budget-exhausted" + detail + "\n";
        }
        // T7：终态写失败 ⇒ 不报成功，且登记 exit-unresolved(write-failed)
        {
            bool ok = true; std::string detail;
            resetState(0, 3);
            const unsigned long long before =
                g_rogRemapExitUnresolved.load(std::memory_order_acquire);
            const bool r = rogEnsureControllerRemap(false, "exit");
            if (r) { ok = false; detail += " [写失败却报成功]"; }
            if (fake.writeSeqCalls.load() != 5) { ok = false; detail += " [重试轮数!=5]"; }
            if (g_rogRemapExitUnresolved.load(std::memory_order_acquire) != before + 1) {
                ok = false; detail += " [未登记 exit-unresolved]";
            }
            if (!ok) pass = false;
            report += std::string("  ") + (ok ? "PASS " : "FAIL ") + "entry-terminal-write-failure-recorded" + detail + "\n";
        }

// ⑮ §21 R2 扩展回归：Aura 关闭助手的**行为**测试。
        // 目的：把"集成误应用把助手体替换成 `{lock; 自调}` 自递归段"这类错误变成**可执行判据**。
        // 本机实测（MSVC std::mutex）：同一线程二次取锁**不卡住，而是抛 resource_deadlock_would_occur**；
        // 不接住就会 std::terminate 中止整个自测（无报告文件、退出码 0xC0000409），判据只剩"进程非零退出"。
        // 因此这里按生产调用约定在持锁下直调助手，并**接住异常判 FAIL**；真跨线程死锁才由看门狗兜底。
        // 句柄用不可能有效的值（0xDEAD…）：CloseHandle 只返回失败，不会触及真实句柄。
    {
        const HANDLE savedAura = g_rog.auraControl;
        const HANDLE savedCtl = g_rog.control;
        const HANDLE savedIn = g_rog.input;
        g_rog.control = reinterpret_cast<HANDLE>(static_cast<uintptr_t>(0x1111));
        g_rog.input = reinterpret_cast<HANDLE>(static_cast<uintptr_t>(0x2222));
        g_rog.auraControl = reinterpret_cast<HANDLE>(static_cast<uintptr_t>(0xDEAD0000DEAD0000ULL));
        std::atomic<int> outcome{0};                        // 0=未完成 1=正常 2=抛错 3=未置无效
        std::thread helper([&]() {
            try {
                std::lock_guard<std::mutex> auraLock(g_rogAuraMx);   // 生产调用约定：助手在持锁下调用
                rogCloseAuraHandleLocked();
                outcome.store((g_rog.auraControl == INVALID_HANDLE_VALUE) ? 1 : 3,
                              std::memory_order_release);
            } catch (const std::exception&) {
                outcome.store(2, std::memory_order_release);
            } catch (...) {
                outcome.store(2, std::memory_order_release);
            }
        });
        const ULONGLONG deadline = GetTickCount64() + 3000;
        while (outcome.load(std::memory_order_acquire) == 0 && GetTickCount64() < deadline)
            std::this_thread::sleep_for(std::chrono::milliseconds(10));
        const int res = outcome.load(std::memory_order_acquire);
        if (res != 0) helper.join(); else helper.detach();   // 超时：置 FAIL 并让进程随后退出
        const bool ok = (res == 1);
        g_rog.auraControl = savedAura;
        g_rog.control = savedCtl;
        g_rog.input = savedIn;
        if (!ok) pass = false;
        std::string detail;
        if (res == 2) detail = " [助手自递归/二次取锁：抛错]";
        else if (res == 3) detail = " [助手未把句柄置为无效]";
        else if (res == 0) detail = " [3s 内未返回 ⇒ 真死锁]";
        report += std::string("  ") + (ok ? "PASS " : "FAIL ") + "aura-close-helper-no-recursion" + detail + "\n";
    }

// ⑯ §21 R2 扩展回归：会话关闭**不得自死锁**（锁序：边界 → Aura 互斥，且不重复取）。
        // 用假句柄调 rogCloseSession(true/false)；同一线程二次取 g_rogAuraMx 在 MSVC 下会**抛错**
        // （resource_deadlock_would_occur），只有真正的跨线程锁序成环才会卡住——两种都必须判 FAIL：
        // 抛错接住判 FAIL，卡住由看门狗（3s 截止）判 FAIL，均不挂死整个自测。
        {
            g_rog.control = reinterpret_cast<HANDLE>(static_cast<uintptr_t>(0x1A1A));
            g_rog.input = reinterpret_cast<HANDLE>(static_cast<uintptr_t>(0x2B2B));
            g_rog.auraControl = reinterpret_cast<HANDLE>(static_cast<uintptr_t>(0x3C3C));
            std::atomic<int> outcome{0};                        // 0=未完成 1=正常 2=抛错
            std::thread closer([&]() {
                try {
                    rogCloseSession(true);
                    rogCloseSession(false);
                    outcome.store(1, std::memory_order_release);
                } catch (const std::exception&) {
                    outcome.store(2, std::memory_order_release);
                } catch (...) {
                    outcome.store(2, std::memory_order_release);
                }
            });
            const ULONGLONG deadline = GetTickCount64() + 3000;
            while (outcome.load(std::memory_order_acquire) == 0 && GetTickCount64() < deadline)
                std::this_thread::sleep_for(std::chrono::milliseconds(10));
            const int res = outcome.load(std::memory_order_acquire);
            if (res != 0) closer.join(); else closer.detach();   // 超时：置 FAIL 并让进程随后退出
            const bool ok = (res == 1);
            if (!ok) pass = false;
            report += std::string("  ") + (ok ? "PASS " : "FAIL ") + "session-close-no-self-deadlock"
                      + (ok ? "" : res == 2 ? " [会话关闭内二次取锁：抛错]"
                                            : " [3s 内未返回 ⇒ 锁序/自锁风险]")
                      + "\n";
        }

        // ⑰ §21 R2 扩展回归（**行为级**，补上"只有锁序论证"的缺口）：Aura(0x5D) 句柄归属。
        // 判据：一个线程正在"写灯"（持 g_rogAuraMx）时，另一线程调生产路径 rogCloseSession
        // **必须等待**该写者，而**不能**把正在使用的句柄关掉。若归属被去掉/写错（例如关闭
        // 不经 g_rogAuraMx），关闭会立刻返回 ⇒ 本项 FAIL（负对照 R4 已实证其区分力）。
        // 句柄全为伪造值：CloseHandle 只返回失败，不触及真实设备。
        {
            bool ok = true; std::string detail;
            const HANDLE savedAura = g_rog.auraControl;
            const HANDLE savedCtl = g_rog.control;
            const HANDLE savedIn = g_rog.input;
            const bool savedReadPending = g_rog.readPending;
            g_rog.control = reinterpret_cast<HANDLE>(static_cast<uintptr_t>(0x4D4D));
            g_rog.input = reinterpret_cast<HANDLE>(static_cast<uintptr_t>(0x5E5E));
            g_rog.auraControl = reinterpret_cast<HANDLE>(static_cast<uintptr_t>(0x6F6F));
            g_rog.readPending = false;
            const ULONGLONG holdMs = 300;
            std::atomic<bool> writerHolds{false};
            std::atomic<bool> closeDone{false};
            std::thread writer([&]() {
                std::lock_guard<std::mutex> auraLock(g_rogAuraMx);   // 模拟灯光写入持锁
                writerHolds.store(true, std::memory_order_release);
                std::this_thread::sleep_for(std::chrono::milliseconds(holdMs));
            });
            const ULONGLONG holdDeadline = GetTickCount64() + 2000;
            while (!writerHolds.load(std::memory_order_acquire) && GetTickCount64() < holdDeadline)
                std::this_thread::yield();
            if (!writerHolds.load(std::memory_order_acquire)) {
                ok = false; detail += " [写者未取得锁(超时)]";
            }
            const ULONGLONG t0 = GetTickCount64();
            std::thread closer([&]() {
                rogCloseSession(false);                          // 生产路径：内部取 g_rogAuraMx
                closeDone.store(true, std::memory_order_release);
            });
            const ULONGLONG deadline = GetTickCount64() + holdMs + 3000;
            while (!closeDone.load(std::memory_order_acquire) && GetTickCount64() < deadline)
                std::this_thread::sleep_for(std::chrono::milliseconds(5));
            const ULONGLONG elapsed = GetTickCount64() - t0;
            if (!closeDone.load(std::memory_order_acquire)) {
                ok = false; detail += " [关闭未返回 ⇒ 死锁]";
                writer.detach(); closer.detach();                // 让进程随后退出；不再触碰 g_rog
            } else {
                writer.join(); closer.join();
                if (elapsed < holdMs - 100) {
                    ok = false; detail += " [关闭未等待写者 ⇒ 句柄归属失效]";
                }
                if (g_rog.auraControl != INVALID_HANDLE_VALUE) {
                    ok = false; detail += " [关闭后 Aura 句柄未置无效]";
                }
                g_rog.auraControl = savedAura;
                g_rog.control = savedCtl;
                g_rog.input = savedIn;
                g_rog.readPending = savedReadPending;
            }
            if (!ok) pass = false;
            report += std::string("  ") + (ok ? "PASS " : "FAIL ") + "aura-close-waits-for-writer"
                      + " waitedMs=" + std::to_string(elapsed) + detail + "\n";
        }
        // ⑱ §22（联合裁决 §3）：恢复入口的会话归属——**在途写期间恢复不得已进入 bind**。
        // 驱动的是**真实恢复入口** `gamepadRecoverAfterResume`（内部走有界等待），
        // 判据落在"是否真的进了 rogBindInputHid"这一行为上：A 持边界在途写时采样必须为 0，
        // A 释放后必须 ≥1（恢复有效执行）。旧的无锁直调会立刻进入 bind ⇒ 采样非 0 ⇒ FAIL
        // （负对照 R6 已实证该判据能抓住无锁旧行为）。
        {
            bool ok = true; std::string detail;
            resetState(400, 0);
            g_rog.identityMatched = true;      // ⑯/⑰ 的 rogCloseSession 会清会话态 ⇒ 本项自备
            g_rog.hasControl = true;
            g_entryTestBindCalls.store(0, std::memory_order_release);
            g_entryTestRecoverBindDeferred.store(0, std::memory_order_release);
            g_entryTestRecoverBindDropped.store(0, std::memory_order_release);
            std::thread a([&]() { (void)rogEnsureControllerRemap(true, "window-hidden"); });
            if (!waitUntil(fake.writeSeqCalls, 1, 3000)) { ok = false; detail += " [A 未开始写入(超时)]"; }
            std::thread r([&]() { (void)gamepadRecoverAfterResume(); });
            std::this_thread::sleep_for(std::chrono::milliseconds(120));
            const int duringHold = g_entryTestBindCalls.load(std::memory_order_acquire);
            if (duringHold != 0) { ok = false; detail += " [在途写期间恢复已进入 bind]"; }
            a.join(); r.join();
            const int afterAll = g_entryTestBindCalls.load(std::memory_order_acquire);
            if (afterAll < 1) { ok = false; detail += " [锁释放后恢复未执行]"; }
            if (!ok) pass = false;
            report += std::string("  ") + (ok ? "PASS " : "FAIL ") + "recover-bind-waits-for-inflight-write"
                      + " duringHold=" + std::to_string(duringHold) + " after=" + std::to_string(afterAll)
                      + detail + "\n";
        }
        // ⑲ §22：exit 与**晚到恢复**交错 ⇒ 延期的恢复意图被**取消**（不执行、不记成功）。
        {
            bool ok = true; std::string detail;
            resetState(1200, 0);                       // A 持边界 > 恢复等待预算 ⇒ 恢复必有界等待失败
            g_rog.identityMatched = true;      // ⑯/⑰ 的 rogCloseSession 会清会话态 ⇒ 本项自备
            g_rog.hasControl = true;
            g_entryTestBindCalls.store(0, std::memory_order_release);
            g_entryTestRecoverBindDeferred.store(0, std::memory_order_release);
            g_entryTestRecoverBindDropped.store(0, std::memory_order_release);
            std::thread a([&]() { (void)rogEnsureControllerRemap(true, "window-hidden"); });
            if (!waitUntil(fake.writeSeqCalls, 1, 3000)) { ok = false; detail += " [A 未开始写入(超时)]"; }
            const bool deferred = !rogRecoverBindSerialized("resume");
            if (!deferred) { ok = false; detail += " [恢复未被延期]"; }
            if (g_entryTestRecoverBindDeferred.load() != 1) { ok = false; detail += " [未记录待办]"; }
            g_exitRequested.store(true, std::memory_order_release);
            a.join();
            (void)rogEnsureControllerRemap(false, "exit");      // 持边界消费 ⇒ 退出意图 ⇒ 丢弃
            g_exitRequested.store(false, std::memory_order_release);
            if (g_entryTestRecoverBindDropped.load() != 1) { ok = false; detail += " [未丢弃待办]"; }
            if (g_entryTestBindCalls.load() != 0) { ok = false; detail += " [退出后仍执行恢复 bind]"; }
            if (!ok) pass = false;
            report += std::string("  ") + (ok ? "PASS " : "FAIL ") + "recover-bind-cancelled-by-exit"
                      + detail + "\n";
        }
        // ⑳ §22：延期的恢复意图在**代次过期**后不得记成功（丢弃，不执行 bind）。
        {
            bool ok = true; std::string detail;
            resetState(1200, 0);
            g_rog.identityMatched = true;      // ⑯/⑰ 的 rogCloseSession 会清会话态 ⇒ 本项自备
            g_rog.hasControl = true;
            g_entryTestBindCalls.store(0, std::memory_order_release);
            g_entryTestRecoverBindDeferred.store(0, std::memory_order_release);
            g_entryTestRecoverBindDropped.store(0, std::memory_order_release);
            std::thread a([&]() { (void)rogEnsureControllerRemap(true, "window-hidden"); });
            if (!waitUntil(fake.writeSeqCalls, 1, 3000)) { ok = false; detail += " [A 未开始写入(超时)]"; }
            const bool deferred = !rogRecoverBindSerialized("resume");
            if (!deferred) { ok = false; detail += " [恢复未被延期]"; }
            a.join();
            g_rogRemapDevGen.fetch_add(1, std::memory_order_acq_rel);   // 真实换代
            (void)rogEnsureControllerRemap(false, "exit");              // 消费点
            if (g_entryTestRecoverBindDropped.load() != 1) { ok = false; detail += " [过期未丢弃]"; }
            if (g_entryTestBindCalls.load() != 0) { ok = false; detail += " [过期仍执行 bind]"; }
            if (!ok) pass = false;
            report += std::string("  ") + (ok ? "PASS " : "FAIL ") + "recover-bind-stale-generation-dropped"
                      + detail + "\n";
        }
        // ㉑ §22：延期的恢复意图必须被**下一次生命周期入口**有效消费（恢复不丢失）。
        {
            bool ok = true; std::string detail;
            resetState(1200, 0);
            g_rog.identityMatched = true;      // ⑯/⑰ 的 rogCloseSession 会清会话态 ⇒ 本项自备
            g_rog.hasControl = true;
            g_entryTestBindCalls.store(0, std::memory_order_release);
            g_entryTestRecoverBindDeferred.store(0, std::memory_order_release);
            g_entryTestRecoverBindDropped.store(0, std::memory_order_release);
            std::thread a([&]() { (void)rogEnsureControllerRemap(true, "window-hidden"); });
            if (!waitUntil(fake.writeSeqCalls, 1, 3000)) { ok = false; detail += " [A 未开始写入(超时)]"; }
            const bool deferred = !rogRecoverBindSerialized("resume");
            if (!deferred) { ok = false; detail += " [恢复未被延期]"; }
            a.join();
            const int before = g_entryTestBindCalls.load(std::memory_order_acquire);
            (void)rogEnsureControllerRemap(false, "exit");              // 同代次 ⇒ 应被消费并执行 bind
            const int after = g_entryTestBindCalls.load(std::memory_order_acquire);
            if (after != before + 1) { ok = false; detail += " [延期恢复未被消费]"; }
            if (g_entryTestRecoverBindDropped.load() != 0) { ok = false; detail += " [被误丢弃]"; }
            if (!ok) pass = false;
            report += std::string("  ") + (ok ? "PASS " : "FAIL ") + "recover-bind-consumed-next-entry"
                      + " before=" + std::to_string(before) + " after=" + std::to_string(after)
                      + detail + "\n";
        }
        g_rogSessionOpsFakeActive.store(false, std::memory_order_release);
        g_rogRemapLogQuiet.store(false, std::memory_order_release);
        g_entryTestFake = nullptr;
        g_exitRequested.store(false, std::memory_order_release);
    }

    report += pass ? "RESULT=PASS\n" : "RESULT=FAIL\n";
    try {
        std::ofstream f(yemancc_data_dir() + L"\\rog-remap-throttle-selftest.txt",
                        std::ios::binary | std::ios::trunc);
        f << report;
    } catch (...) { }
    return pass;
}

// 写后回读：HidD_SetFeature 返回真只证明 IOCTL 成功，不证明固件接受映射
// （HC 侧同样无回读；本项在机型库中登记为「真机写后读回」P1 未验项）。
// 回读只读、不改设备状态；失败或返回全零时日志里 rbLen=0。
static std::string rogReadBackFeatureReport() {
    if (g_rog.control == INVALID_HANDLE_VALUE || g_rog.featureLen < 5) return std::string();
    std::vector<BYTE> rb(g_rog.featureLen, 0);
    rb[0] = 0x5A;
    if (HidD_GetFeature(g_rog.control, rb.data(), static_cast<ULONG>(rb.size())) == FALSE) return std::string();
    static const char* kHex = "0123456789ABCDEF";
    size_t n = g_rog.featureLen < 16 ? g_rog.featureLen : 16;
    std::string out;
    out.reserve(n * 2);
    for (size_t i = 0; i < n; ++i) {
        out.push_back(kHex[(rb[i] >> 4) & 0x0F]);
        out.push_back(kHex[rb[i] & 0x0F]);
    }
    return out;
}

// ── §4.1 来源接纳：键盘 Raw Input 背键事件的设备身份核验 ──────────────────
// 裁决要求：判据不能是单一 VID 子串，须「路径 + 实例/父节点 + 机型」一致；且不复用
// 游戏手柄准入规则（不改 NotGamepad），只复用通用设备树查询能力。此处以 ContainerId
// 比对落实：本事件的键盘接口与本机已绑定的 ROG 设备接口同容器 ⇒ 同一物理设备
// （父节点树一致），再叠加已解析机型（family ∈ ROG 且身份已解析）确认。
static std::wstring rawInputDeviceInterfacePath(HANDLE hDevice) {
    std::wstring out;
    if (hDevice == nullptr) return out;
    UINT chars = 0;
    if (GetRawInputDeviceInfoW(hDevice, RIDI_DEVICENAME, nullptr, &chars) == static_cast<UINT>(-1) || chars == 0)
        return out;
    std::vector<wchar_t> buf(static_cast<size_t>(chars) + 1, L'\0');
    if (GetRawInputDeviceInfoW(hDevice, RIDI_DEVICENAME, buf.data(), &chars) == static_cast<UINT>(-1))
        return out;
    out.assign(buf.data());
    return out;
}

static bool deviceInterfaceContainerId(const wchar_t* ifacePath, GUID* out) {
    if (ifacePath == nullptr || out == nullptr || ifacePath[0] == L'\0') return false;
    DEVPROPTYPE type = 0;
    ULONG size = sizeof(GUID);
    const CONFIGRET cr = CM_Get_Device_Interface_PropertyW(
        ifacePath, &DEVPKEY_Device_ContainerId, &type,
        reinterpret_cast<PBYTE>(out), &size, 0);
    if (cr != CR_SUCCESS || type != DEVPROP_TYPE_GUID || size != sizeof(GUID)) return false;
    // 空容器 = "未分配容器"，不能当身份用：否则两个"无容器"设备会被误判为同一设备。
    // 本机实测确有接口返回 00000000-0000-0000-ffff-ffffffffffff（如 ASUS PID_19AF 集合），
    // 因此这里按"未解析"处理，保持 fail-closed。
    static const GUID kNullContainer = { 0x00000000, 0x0000, 0x0000,
        { 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff } };
    if (IsEqualGUID(*out, kNullContainer) != FALSE) return false;
    return true;
}

// 上溯到 USB 顶层设备实例（父节点树级身份）：容器缺失（空容器）时作为替代判据。
// 背景（真机实测）：ASUS 控制接口的容器可能是空容器 ⇒ 只用容器会误拒合法基准
// （本轮真机 `refReady:false` 即此成因），故按裁决 §4.1 补「实例/父节点」这一路。
static bool deviceInterfaceUsbInstance(const wchar_t* ifacePath, std::wstring& out) {
    out.clear();
    if (ifacePath == nullptr || ifacePath[0] == L'\0') return false;
    wchar_t instanceId[512] = {};
    DEVPROPTYPE type = 0;
    ULONG size = sizeof(instanceId);
    if (CM_Get_Device_Interface_PropertyW(ifacePath, &DEVPKEY_Device_InstanceId, &type,
            reinterpret_cast<PBYTE>(instanceId), &size, 0) != CR_SUCCESS) return false;
    if (type != DEVPROP_TYPE_STRING || instanceId[0] == L'\0') return false;
    DEVINST devInst = 0;
    if (CM_Locate_DevNodeW(&devInst, instanceId, CM_LOCATE_DEVNODE_NORMAL) != CR_SUCCESS) return false;
    for (int depth = 0; depth < 8; ++depth) {
        wchar_t devId[512] = {};
        if (CM_Get_Device_IDW(devInst, devId, 512, 0) != CR_SUCCESS) break;
        const std::wstring id(devId);
        // 只认「复合设备」级实例：USB 接口节点（ID 含 &MI_xx）**不是**同一物理设备的稳定
        // 基准——真机实测 MI_02/MI_03 各自有独立的 USB\...&MI_xx 节点，若停在第一层 USB\
        // 会得到不同实例串，使实例比对永不成立（这正是真机 admitted:false / via:"" 的成因）。
        if (id.compare(0, 4, L"USB\\") == 0 && id.find(L"&MI_") == std::wstring::npos) {
            out = id;
            return true;
        }
        DEVINST parent = 0;
        if (CM_Get_Parent(&parent, devInst, 0) != CR_SUCCESS) break;
        devInst = parent;
    }
    return false;
}

// 同一物理设备的树级判据（§4.1「路径 + 实例/父节点 + 机型」，机型由调用方另行确认）：
// ① 双方容器都存在且相等；② 否则比对上溯到的 USB 顶层实例；
// ③ 再否则比"与已核验 ROG 设备同 VID&PID"——该 PID 在 ROG 绑定时已按机型核验
//    （rogIsAllyPid + identityMatched），故不是裸 VID 判断。
// 三者都不可得 ⇒ 拒收（fail-closed）。viaOut 回填用了哪一路，便于日志取证。
static bool usbVidPidOf(const std::wstring& ifacePath, std::string& outLower) {
    outLower.clear();
    if (ifacePath.empty()) return false;
    const std::string p = ascii_lower(W2U(ifacePath));
    const size_t v = p.find("vid_");
    const std::string pidTag = "&pid_";
    const size_t q = p.find(pidTag);
    if (v == std::string::npos || q == std::string::npos || q < v) return false;
    const size_t end = q + pidTag.size() + 4;   // &pid_ + 4 位
    if (end > p.size()) return false;
    outLower = p.substr(v, end - v);
    return true;
}

// ── §10.2 来源关联判定（收紧版）────────────────────────────────────────────
// 裁决要点：同 VID/PID **只作候选筛选，不作实例归属的最终证据**；强身份冲突时
// **不得**回退到更弱信号；参考身份不可得时**显式未就绪**（走已验证的适配器后备），
// 绝不宽泛接纳键盘来源。最终证据只有设备树级两类：容器一致 / USB 复合（父）实例一致。
enum class OemIdentityVerdict {
    MatchContainer,     // 容器一致（设备树级）
    MatchUsbInstance,   // USB 复合（父）实例一致（设备树级）—— 真机实证通路
    NotReady,           // 参考（基准）身份不可得 ⇒ 显式未就绪
    SameModelOnly,      // 仅同 VID/PID（候选筛选通过，不足以判定同源）
    Conflict,           // 两侧身份均可解析且不一致（硬冲突）
    Reject              // 其他（含事件侧身份不可得）
};

struct OemIdentityInputs {
    bool eventContainerOk = false; GUID eventContainer{};
    bool refContainerOk = false;   GUID refContainer{};
    bool eventUsbOk = false;       std::wstring eventUsb;
    bool refUsbOk = false;         std::wstring refUsb;
    std::string eventVidPid;
    std::string refVidPid;
};

// 纯函数（不碰设备）：便于 --oem-identity-selftest 覆盖"同 VID/PID 不同实例 /
// 强冲突 / 身份不可得"等定点场景，无需真机即可回归。
static OemIdentityVerdict oemIdentityDecide(const OemIdentityInputs& in) {
    if (!in.refContainerOk && !in.refUsbOk) return OemIdentityVerdict::NotReady;
    // ① 容器：两侧都可解析时以它为准（不一致即硬冲突，不再看更弱信号）
    if (in.eventContainerOk && in.refContainerOk) {
        return (IsEqualGUID(in.eventContainer, in.refContainer) != FALSE)
            ? OemIdentityVerdict::MatchContainer : OemIdentityVerdict::Conflict;
    }
    // ② USB 复合实例：两侧都可解析时以它为准（不一致即硬冲突）
    if (in.eventUsbOk && in.refUsbOk && !in.eventUsb.empty() && !in.refUsb.empty()) {
        return (in.eventUsb == in.refUsb)
            ? OemIdentityVerdict::MatchUsbInstance : OemIdentityVerdict::Conflict;
    }
    // ③ 只剩候选筛选级证据（同 VID/PID）⇒ 仅标注，不构成接纳
    if (!in.eventVidPid.empty() && !in.refVidPid.empty() && in.eventVidPid == in.refVidPid)
        return OemIdentityVerdict::SameModelOnly;
    return OemIdentityVerdict::Reject;
}

static const char* oemIdentityVerdictName(OemIdentityVerdict v) {
    switch (v) {
        case OemIdentityVerdict::MatchContainer: return "match-container";
        case OemIdentityVerdict::MatchUsbInstance: return "match-usb-instance";
        case OemIdentityVerdict::NotReady: return "not-ready";
        case OemIdentityVerdict::SameModelOnly: return "same-model-only";
        case OemIdentityVerdict::Conflict: return "conflict";
        default: return "reject";
    }
}

static OemIdentityInputs oemIdentityInputsFor(const std::wstring& eventPath, const std::wstring& refPath) {
    OemIdentityInputs in;
    if (!eventPath.empty()) {
        in.eventContainerOk = deviceInterfaceContainerId(eventPath.c_str(), &in.eventContainer);
        in.eventUsbOk = deviceInterfaceUsbInstance(eventPath.c_str(), in.eventUsb);
        usbVidPidOf(eventPath, in.eventVidPid);
    }
    if (!refPath.empty()) {
        in.refContainerOk = deviceInterfaceContainerId(refPath.c_str(), &in.refContainer);
        in.refUsbOk = deviceInterfaceUsbInstance(refPath.c_str(), in.refUsb);
        usbVidPidOf(refPath, in.refVidPid);
    }
    return in;
}

// 来源核验（按句柄缓存最后结论；设备增删与 profile 切换时清缓存）。
// 机型未确认 ⇒ 不接纳；身份未就绪 ⇒ 显式未就绪（由 gate 退回既有适配器通路）。
static bool oemRawKbAdmitDevice(HANDLE hDevice) {
    if (hDevice == nullptr) return false;
    if (hDevice == g_oemRawAdmitDev) return g_oemRawAdmitOk;
    std::wstring path;
    std::wstring refPath;
    OemIdentityVerdict verdict = OemIdentityVerdict::Reject;
    OemIdentityInputs in;
    if (ymccIsRogFamily() && g_machineIdentity.resolved) {
        path = rawInputDeviceInterfacePath(hDevice);
        refPath = (g_rog.hasControl && !g_rog.controlPath.empty())
            ? g_rog.controlPath : g_rog.inputPath;
        if (!path.empty() && !refPath.empty()) {
            in = oemIdentityInputsFor(path, refPath);
            verdict = oemIdentityDecide(in);
        }
    }
    // 仅设备树级同源可接纳；同 VID/PID / 冲突 / 未就绪一律不接纳（fail-closed）
    const bool ok = (verdict == OemIdentityVerdict::MatchContainer ||
                     verdict == OemIdentityVerdict::MatchUsbInstance);
    g_oemRawAdmitDev = hDevice;
    g_oemRawAdmitOk = ok;
    // 判据证据随结论一并落盘：任何未接纳情形都带齐成因字段（免于再跑一轮真机）。
    wchar_t evText[64] = L"";
    wchar_t refText[64] = L"";
    if (in.eventContainerOk) StringFromGUID2(in.eventContainer, evText, 64);
    if (in.refContainerOk) StringFromGUID2(in.refContainer, refText, 64);
    appendNativeLifecycleLog("oem-raw-keyboard-admit", {
        {"admitted", ok},
        {"via", oemIdentityVerdictName(verdict)},
        {"family", static_cast<int>(g_machineIdentity.family)},
        {"usbProductId", g_rog.productId},
        {"refKind", (g_rog.hasControl && !g_rog.controlPath.empty()) ? "control" : "input"},
        {"eventPath", W2U(path)},
        {"eventContainer", W2U(evText)},
        {"refContainer", W2U(refText)},
        {"eventUsb", W2U(in.eventUsb)},
        {"refUsb", W2U(in.refUsb)},
        {"eventVidPid", in.eventVidPid},
        {"refVidPid", in.refVidPid}
    });
    return ok;
}

// §21 R1/R3：**生产入口**。协调 = 同线程递归标记（thread_local）+ 跨线程边界锁
// （非终态 try(0)，终态有界等待预算）。所有路径（hid-bound / window-hidden / resume /
// exit / destroy 以及 xbox-face 的收尾同步）都经过这里或下面的同一核心。
static bool rogRemapCoreLocked(bool remap, const char* why, bool terminalPath);

static bool rogEnsureControllerRemap(bool remap, const char* reason) {
    const char* why = reason ? reason : "";
    const bool terminalPath = rogRemapTerminalReason(why);
    RogRemapGuardScope remapGuard;                    // 只挡本线程内 绑定↔重映射 互递归
    if (!remapGuard.acquired) {
        rogRemapLog("rog.controller-remap-skipped", {{"reason", why}, {"skip", "thread-recursion"}});
        return false;
    }
    RogRemapBoundaryScope boundary(terminalPath ? kRogRemapTerminalWaitBudgetMs : 0u);
    if (!boundary.entered) {
        // 并发进入：不读记账、不写记账、不进入设备写入。终态请求在预算内没拿到锁
        // ⇒ 如实登记"退出写回未完成"（R3），不假装已跳过为正常。
        rogRemapLog("rog.controller-remap-busy", {{"reason", why}, {"terminal", terminalPath}});
        if (terminalPath) rogRemapNoteExitUnresolved("wait-budget-exhausted");
        return false;
    }
    return rogRemapCoreLocked(remap, why, terminalPath);
}

// 核心：**调用者必须已持有边界锁**（不重复加锁、不做递归判定）。
// §22（联合裁决 §3）：**恢复 bind 的会话归属收口**。
// 背景：`gamepadRecoverAfterResume` 原先直接调 `rogBindInputHid()`，与在途重映射/会话关闭
// 不在同一边界内 ⇒ 恢复线程可能关闭正在使用的会话（结果文件第 21 批 §十 已自认）。
// 裁决明确**不接受**"try-lock 失败后继续原无锁 bind"——记日志不能代替会话归属。
// 规则（不新增轮询）：
//   ① 线程内重入（已在边界内，如收尾同步路径）⇒ 直接执行，不二次取非递归锁；
//   ② 否则**有界等待**边界（预算与终态同为锁等待预算）；
//   ③ 有界等待失败 ⇒ 把恢复意图**留给下一次生命周期入口消费**（不无锁回退、不无限等待、不丢弃恢复）。
static constexpr unsigned kRogRemapRecoverWaitBudgetMs = 800;      // 与终态同为锁等待预算
static std::atomic<unsigned long long> g_rogRecoverPendingGen{0};  // 0 = 无待办；否则 = 记录时代次
static bool rogRecoverBindSerialized(const char* why) {
    if (g_aiFanMockSession.isolated) return false;
    const char* tag = why ? why : "";
    RogRemapGuardScope guard;                          // 只挡本线程内 绑定↔重映射 互递归
    if (!guard.acquired) {
        // 已在边界内：直接执行（不再取非递归锁）。计数由 rogBindInputHid 自身记录。
        rogBindInputHid();
        return true;
    }
    RogRemapBoundaryScope boundary(kRogRemapRecoverWaitBudgetMs);
    if (!boundary.entered) {
        // 有界等待失败：保留可消费的恢复意图（代次锚定），交给下一次生命周期入口。
        g_rogRecoverPendingGen.store(g_rogRemapDevGen.load(std::memory_order_acquire),
                                     std::memory_order_release);
        g_entryTestRecoverBindDeferred.fetch_add(1, std::memory_order_acq_rel);
        rogRemapLog("rog.recover-bind-deferred", {
            {"reason", tag}, {"devGen", g_rogRemapDevGen.load(std::memory_order_acquire)}});
        return false;
    }
    rogBindInputHid();
    g_rogRecoverPendingGen.store(0, std::memory_order_release);   // 本次已完成 ⇒ 清待办
    rogRemapLog("rog.recover-bind-executed", {{"reason", tag}});
    return true;
}
// 消费延期的恢复意图（**调用者必须已持边界锁**，如 rogRemapCoreLocked 入口）。一次性。
// 代次失效或退出意图 ⇒ 丢弃且不记成功（消费方：下一次持有边界权的生命周期入口）。
static bool rogRemapConsumeDeferredRecover() {
    const unsigned long long pending = g_rogRecoverPendingGen.load(std::memory_order_acquire);
    if (pending == 0) return false;
    g_rogRecoverPendingGen.store(0, std::memory_order_release);   // 一次性消费（含丢弃）
    if (g_exitRequested.load(std::memory_order_acquire)) {
        g_entryTestRecoverBindDropped.fetch_add(1, std::memory_order_acq_rel);
        rogRemapLog("rog.recover-bind-dropped", {{"reason", "exit-intent"}, {"pendingGen", pending}});
        return false;
    }
    const unsigned long long nowGen = g_rogRemapDevGen.load(std::memory_order_acquire);
    if (nowGen != pending) {
        g_entryTestRecoverBindDropped.fetch_add(1, std::memory_order_acq_rel);
        rogRemapLog("rog.recover-bind-dropped", {
            {"reason", "stale-generation"}, {"pendingGen", pending}, {"devGen", nowGen}});
        return false;
    }
    rogBindInputHid();
    rogRemapLog("rog.recover-bind-consumed", {{"devGen", nowGen}});
    return true;
}
static bool rogRemapCoreLocked(bool remap, const char* why, bool terminalPath) {
    // §22：先消费延期的恢复意图（一次性；退出意图或代次过期 ⇒ 丢弃且不记成功）。
    // 消费方 = 下一次持有边界权的生命周期入口；不新增轮询。
    (void)rogRemapConsumeDeferredRecover();
    // §21 R3：退出意图。`g_exitRequested` 由 beginAsyncExit 在退出开始时置位；
    // 之后晚到的 hid-bound / window-hidden / resume 一律不得**重新启用**重映射
    // （remap(false) 的目标态写回仍允许，那是终态该做的事）。
    if (remap && g_exitRequested.load(std::memory_order_acquire)) {
        rogRemapLog("rog.controller-remap-skipped", {{"reason", why}, {"skip", "exit-intent"}});
        return false;
    }
    // §15.1 ③ 设备树脏事件复核：只有"我们绑定签名"确实变了才推进代次
    // （放弃退避）；通用设备树通知（鼠标/虚拟端枚举）不打断刚建立的失败退避。
    switch (rogRemapResolveDirty(g_rogRemapThrottle)) {
        case RogRemapDirty::Relevant:
            rogRemapNoteDeviceGeneration("bound-identity-changed");
            break;
        case RogRemapDirty::Noise:
            if (g_rogRemapThrottle.attemptKnown || g_rogRemapThrottle.appliedKnown) {
                rogRemapLog("rog.controller-remap-noise-ignored", {
                    {"devGen", g_rogRemapDevGen.load(std::memory_order_acquire)}
                });
            }
            break;
        default:
            break;
    }
    const auto phase = g_powerLifecycle.load(std::memory_order_acquire);
    const bool powerQuiet = phase != PowerLifecycle::Ready ||
        !g_inputReady.load(std::memory_order_acquire);
    // 电源期禁写（0915-19：PBT_APMSUSPEND HID 写入阻塞 UI 线程）。
    // hid-bound 补写同样受电源静默期约束：绑定恰好发生在唤醒/休眠过渡时不得写。
    if (std::strcmp(why, "suspend") == 0 ||
        ((std::strcmp(why, "window-hidden") == 0 || std::strcmp(why, "hid-bound") == 0) && powerQuiet)) {
        rogRemapLog("rog.controller-remap-skipped", {
            {"reason", why}, {"remap", remap},
            {"inputReady", g_inputReady.load(std::memory_order_acquire)}
        });
        return false;
    }
    const ULONGLONG now = GetTickCount64();
    // §14.2 节流（尝试记账 × 成功应用 × 代次锚）：5s 内同目标态不重复写 14 条 feature，
    // 失败同样受 5s 退避（旧实现只在成功时记账，失败可绕过节流）。
    const unsigned long long devGen = g_rogRemapDevGen.load(std::memory_order_acquire);
    const unsigned long long powerGen = currentPowerGeneration();
    const RogRemapPlan plan = rogRemapPlan(g_rogRemapThrottle, remap, now, devGen, powerGen);
    if (plan != RogRemapPlan::Write) {
        rogRemapLog(plan == RogRemapPlan::ReuseApplied
                        ? "rog.controller-remap-reuse"
                        : "rog.controller-remap-deferred",
            {
                {"reason", why}, {"remap", remap}, {"plan", rogRemapPlanName(plan)},
                {"ageMs", now - (plan == RogRemapPlan::ReuseApplied
                                     ? g_rogRemapThrottle.appliedTick
                                     : g_rogRemapThrottle.attemptTick)},
                {"devGen", devGen}, {"powerGen", powerGen}
            });
        // 复用＝目标态已应用（true）；退避≠成功（false，不得报伪成功）。
        return plan == RogRemapPlan::ReuseApplied;
    }
    const RogSessionOps& ops = rogSessionOps();       // §21 R2：会话原语（自测可换假设备）
    bool wrote = false;
    int okCount = -1;
    int attempts = 0;   // 实际进入的写入轮数（诊断节流有效性：正常应 ≤5）
    int rebinds = 0;    // 失败路径实际重建会话（⇒ 触发 HID 重新枚举）次数
    // 回读前置态：与写入后回读对比，作为「固件是否接受映射」的证据（P1 未验项闭环）。
    const std::string rbBefore = ops.readBack();
    for (int attempt = 0; attempt < 5; ++attempt) {
        ++attempts;
        if (!g_rog.hasControl) {
            ++rebinds;
            ops.ensureSession();
        }
        if (g_rog.hasControl) okCount = ops.writeRemapSeq(remap);
        wrote = okCount == 14;
        if (wrote) break;
        ops.closeSession(true);
        ops.retryDelay();
        ++rebinds;
        ops.ensureSession();
    }
    const std::string rbAfter = wrote ? ops.readBack() : std::string();
    // 记账：成功/失败都写 attempt（失败退避的键），失败同时作废 applied。
    // 代次用进入本函数时捕获的值：写入期间若发生设备树变化，锚点保持旧值 ⇒
    // 下一次调用判定为「代次不符」而重写（宁可重写，不可错复用）。
    rogRemapRecordResult(g_rogRemapThrottle, remap, wrote, GetTickCount64(), devGen, powerGen);
    rogRemapLog("rog.controller-remap", {
        {"reason", why}, {"remap", remap}, {"wrote", wrote},
        {"okCount", okCount}, {"total", 14},
        {"attempts", attempts}, {"rebinds", rebinds},
        {"terminal", terminalPath},
        {"hasControl", g_rog.hasControl}, {"usbProductId", g_rog.productId},
        {"rbBefore", rbBefore}, {"rbAfter", rbAfter}
    });
    // §21 R3：终态写回没成功 ⇒ 明确登记（M1M2Default 可能未写回）。
    if (terminalPath && !wrote) rogRemapNoteExitUnresolved("write-failed");
    return wrote;
}

// HC's XboxAdaptiveController.Disable() sends 0x02 while it is managing its
// own virtual X360 slot. That action is not a general ROG input-isolation
// primitive: it removes the physical Xbox face from both Steam and YMCC.
// YMCC therefore exposes only HC's lifecycle safety-net direction (0x01).
static bool rogWriteXboxFaceEnabled() {
    if (g_rog.control == INVALID_HANDLE_VALUE || g_rog.featureLen < 5) return false;
    std::vector<BYTE> report(g_rog.featureLen, 0);
    report[0] = 0x5A;
    report[1] = 0xD1;
    report[2] = 0x0B;
    report[3] = 0x01;
    report[4] = 0x01;
    return HidD_SetFeature(g_rog.control, report.data(), static_cast<ULONG>(report.size())) != FALSE;
}

static SHORT rogAxisToXInput(ULONG value, LONG minV, LONG maxV, bool invert) {
    if (maxV <= minV) return 0;
    double n = (static_cast<double>(value) - static_cast<double>(minV)) /
        (static_cast<double>(maxV) - static_cast<double>(minV));
    n = n * 2.0 - 1.0;
    if (invert) n = -n;
    if (n < -1.0) n = -1.0;
    if (n > 1.0) n = 1.0;
    return static_cast<SHORT>(n < 0.0 ? n * 32768.0 : n * 32767.0);
}

static bool rogStartInputRead() {
    if (g_rog.input == INVALID_HANDLE_VALUE || g_rog.inputBuf.empty() || !g_rog.ovEvent) return false;
    if (g_rog.readPending) return true;
    ZeroMemory(&g_rog.ov, sizeof(g_rog.ov));
    g_rog.ov.hEvent = g_rog.ovEvent;
    ResetEvent(g_rog.ovEvent);
    DWORD got = 0;
    if (ReadFile(g_rog.input, g_rog.inputBuf.data(), static_cast<DWORD>(g_rog.inputBuf.size()), &got, &g_rog.ov)) {
        g_rog.readPending = false;
        return true;
    }
    if (GetLastError() == ERROR_IO_PENDING) {
        g_rog.readPending = true;
        return true;
    }
    return false;
}

static bool rogTryReadHidGamepad(XINPUT_GAMEPAD* out) {
    if (!out || !g_rog.hasStableInput || g_rog.input == INVALID_HANDLE_VALUE || !g_rog.preparsed) return false;
    if (!rogStartInputRead()) return false;
    if (g_rog.readPending) {
        if (WaitForSingleObject(g_rog.ovEvent, 0) != WAIT_OBJECT_0) return false;
        DWORD got = 0;
        if (!GetOverlappedResult(g_rog.input, &g_rog.ov, &got, FALSE)) {
            g_rog.readPending = false;
            return false;
        }
        g_rog.readPending = false;
    }
    PCHAR report = reinterpret_cast<PCHAR>(g_rog.inputBuf.data());
    ULONG reportLen = static_cast<ULONG>(g_rog.inputBuf.size());
    XINPUT_GAMEPAD pad{};
    USAGE usages[32]{};
    ULONG usageLen = 32;
    if (HidP_GetUsages(HidP_Input, 0x09, 0, usages, &usageLen, g_rog.preparsed, report, reportLen) == HIDP_STATUS_SUCCESS) {
        for (ULONG i = 0; i < usageLen; ++i) {
            switch (usages[i]) {
            case 1: pad.wButtons |= XINPUT_GAMEPAD_A; break;
            case 2: pad.wButtons |= XINPUT_GAMEPAD_B; break;
            case 3: pad.wButtons |= XINPUT_GAMEPAD_X; break;
            case 4: pad.wButtons |= XINPUT_GAMEPAD_Y; break;
            case 5: pad.wButtons |= XINPUT_GAMEPAD_LEFT_SHOULDER; break;
            case 6: pad.wButtons |= XINPUT_GAMEPAD_RIGHT_SHOULDER; break;
            case 7: pad.wButtons |= XINPUT_GAMEPAD_BACK; break;
            case 8: pad.wButtons |= XINPUT_GAMEPAD_START; break;
            case 9: pad.wButtons |= XINPUT_GAMEPAD_LEFT_THUMB; break;
            case 10: pad.wButtons |= XINPUT_GAMEPAD_RIGHT_THUMB; break;
            default: break;
            }
        }
    }
    if (g_rog.hatPresent) {
        ULONG hat = 0;
        if (HidP_GetUsageValue(HidP_Input, 0x01, 0, 0x39, &hat, g_rog.preparsed, report, reportLen) == HIDP_STATUS_SUCCESS) {
            const ULONG neutral = (g_rog.hatMin == 0) ? 0 : (static_cast<ULONG>(g_rog.hatMax) + 1);
            if (hat != 0 && hat != neutral) {
                const ULONG idx = (g_rog.hatMin == 0) ? hat : (hat - 1);
                switch (idx) {
                case 0: pad.wButtons |= XINPUT_GAMEPAD_DPAD_UP; break;
                case 1: pad.wButtons |= XINPUT_GAMEPAD_DPAD_UP | XINPUT_GAMEPAD_DPAD_RIGHT; break;
                case 2: pad.wButtons |= XINPUT_GAMEPAD_DPAD_RIGHT; break;
                case 3: pad.wButtons |= XINPUT_GAMEPAD_DPAD_DOWN | XINPUT_GAMEPAD_DPAD_RIGHT; break;
                case 4: pad.wButtons |= XINPUT_GAMEPAD_DPAD_DOWN; break;
                case 5: pad.wButtons |= XINPUT_GAMEPAD_DPAD_DOWN | XINPUT_GAMEPAD_DPAD_LEFT; break;
                case 6: pad.wButtons |= XINPUT_GAMEPAD_DPAD_LEFT; break;
                case 7: pad.wButtons |= XINPUT_GAMEPAD_DPAD_UP | XINPUT_GAMEPAD_DPAD_LEFT; break;
                default: break;
                }
            }
        }
    }
    static const USAGE kAxis[4] = { 0x30, 0x31, 0x32, 0x35 };
    ULONG axisVal[4]{};
    for (int i = 0; i < 4; ++i) {
        if (!g_rog.axisPresent[i]) continue;
        if (HidP_GetUsageValue(HidP_Input, 0x01, 0, kAxis[i], &axisVal[i], g_rog.preparsed, report, reportLen) != HIDP_STATUS_SUCCESS)
            continue;
        const SHORT converted = rogAxisToXInput(axisVal[i], g_rog.axisMin[i], g_rog.axisMax[i], i == 1 || i == 3);
        if (i == 0) pad.sThumbLX = converted;
        else if (i == 1) pad.sThumbLY = converted;
        else if (i == 2) pad.sThumbRX = converted;
        else pad.sThumbRY = converted;
    }
    *out = pad;
    rogStartInputRead();
    return true;
}

static WORD rogUsageToXInput(USAGE usage, int map) {
    if (map == 1) {
        switch (usage) {
        case 1: return XINPUT_GAMEPAD_A;
        case 2: return XINPUT_GAMEPAD_B;
        case 3: return XINPUT_GAMEPAD_X;
        case 4: return XINPUT_GAMEPAD_Y;
        case 7: return XINPUT_GAMEPAD_LEFT_SHOULDER;
        case 8: return XINPUT_GAMEPAD_RIGHT_SHOULDER;
        case 9: return XINPUT_GAMEPAD_BACK;
        case 10: return XINPUT_GAMEPAD_START;
        default: break;
        }
    } else if (map == 2) {
        switch (usage) {
        case 1: return XINPUT_GAMEPAD_A;
        case 2: return XINPUT_GAMEPAD_B;
        case 3: return XINPUT_GAMEPAD_X;
        case 4: return XINPUT_GAMEPAD_Y;
        case 9: return XINPUT_GAMEPAD_LEFT_SHOULDER;
        case 10: return XINPUT_GAMEPAD_RIGHT_SHOULDER;
        case 7: return XINPUT_GAMEPAD_BACK;
        case 8: return XINPUT_GAMEPAD_START;
        default: break;
        }
    } else {
        switch (usage) {
        case 1: return XINPUT_GAMEPAD_A;
        case 2: return XINPUT_GAMEPAD_B;
        case 3: return XINPUT_GAMEPAD_X;
        case 4: return XINPUT_GAMEPAD_Y;
        case 5: return XINPUT_GAMEPAD_LEFT_SHOULDER;
        case 6: return XINPUT_GAMEPAD_RIGHT_SHOULDER;
        case 7: return XINPUT_GAMEPAD_BACK;
        case 8: return XINPUT_GAMEPAD_START;
        case 9: return XINPUT_GAMEPAD_LEFT_THUMB;
        case 10: return XINPUT_GAMEPAD_RIGHT_THUMB;
        default: break;
        }
    }
    return 0;
}

// S59.3 (2026-09-11): resolve the physical scope of a Generic-Desktop axis so
// the exempt HID read normalizes against the REAL logical range. The old fixed
// 0..255 mapping assumed 8-bit axes; a 16-bit signed stick (e.g. Flydigi,
// logical -32768..32767) normalized as 0..255 produced full-scale garbage
// (lx=32767 ly=-32768 simultaneously). Reads HIDP_VALUE_CAPS from the report
// descriptor; falls back to the 8-bit convention when the usage is absent.
static bool rogGetAxisRange(PHIDP_PREPARSED_DATA prep, USAGE usage, LONG& minV, LONG& maxV) {
    HIDP_VALUE_CAPS caps[16]{};
    USHORT capLen = 16;
    if (HidP_GetValueCaps(HidP_Input, caps, &capLen, prep) != HIDP_STATUS_SUCCESS || capLen == 0)
        return false;
    for (USHORT i = 0; i < capLen; ++i) {
        if (caps[i].UsagePage != 0x01) continue;
        const USHORT u = caps[i].IsRange ? caps[i].Range.UsageMin : caps[i].NotRange.Usage;
        if (u != usage) continue;
        minV = caps[i].LogicalMin;
        maxV = caps[i].LogicalMax;
        return true;
    }
    return false;
}

static bool rogGetScaledAxis(PHIDP_PREPARSED_DATA prep, PCHAR report, ULONG reportLen,
                             USAGE usage, bool invert, SHORT* out) {
    LONG minV = 0, maxV = 255;
    if (!rogGetAxisRange(prep, usage, minV, maxV) || maxV <= minV) {
        // Fallback: platform convention = unsigned 8-bit (ROG/PadForge style).
        ULONG raw = 0;
        if (HidP_GetUsageValue(HidP_Input, 0x01, 0, usage, &raw, prep, report, reportLen) != HIDP_STATUS_SUCCESS)
            return false;
        *out = rogAxisToXInput(raw, 0, 255, invert);
        return true;
    }
    LONG scaled = 0;
    // HidP_GetScaledUsageValue(ReportType, UsagePage, LinkCollection, Usage,
    // out ScaledUsageValue, PreparsedData, Report, ReportLength) returns the log
    // value sign-corrected against the declared logical range (supports 8-bit
    // and 16-bit signed sticks alike).
    if (HidP_GetScaledUsageValue(HidP_Input, 0x01, 0, usage, &scaled, prep, report, reportLen) != HIDP_STATUS_SUCCESS)
        return false;
    *out = rogAxisToXInput(static_cast<ULONG>(scaled), minV, maxV, invert);
    return true;
}

static bool rogParseReport(PHIDP_PREPARSED_DATA prep, PCHAR report, ULONG reportLen, int map, XINPUT_GAMEPAD* out) {
    if (!prep || !report || !out || reportLen == 0) return false;
    XINPUT_GAMEPAD pad{};
    USAGE usages[32]{};
    ULONG usageLen = 32;
    if (HidP_GetUsages(HidP_Input, 0x09, 0, usages, &usageLen, prep, report, reportLen) == HIDP_STATUS_SUCCESS) {
        for (ULONG i = 0; i < usageLen; ++i) {
            pad.wButtons |= rogUsageToXInput(usages[i], map);
        }
    }
    ULONG hat = 0;
    if (HidP_GetUsageValue(HidP_Input, 0x01, 0, 0x39, &hat, prep, report, reportLen) == HIDP_STATUS_SUCCESS) {
        if (hat != 0 && hat != 8) {
            const ULONG idx = (hat == 0) ? 0 : (hat - 1);
            switch (idx) {
            case 0: pad.wButtons |= XINPUT_GAMEPAD_DPAD_UP; break;
            case 1: pad.wButtons |= XINPUT_GAMEPAD_DPAD_UP | XINPUT_GAMEPAD_DPAD_RIGHT; break;
            case 2: pad.wButtons |= XINPUT_GAMEPAD_DPAD_RIGHT; break;
            case 3: pad.wButtons |= XINPUT_GAMEPAD_DPAD_DOWN | XINPUT_GAMEPAD_DPAD_RIGHT; break;
            case 4: pad.wButtons |= XINPUT_GAMEPAD_DPAD_DOWN; break;
            case 5: pad.wButtons |= XINPUT_GAMEPAD_DPAD_DOWN | XINPUT_GAMEPAD_DPAD_LEFT; break;
            case 6: pad.wButtons |= XINPUT_GAMEPAD_DPAD_LEFT; break;
            case 7: pad.wButtons |= XINPUT_GAMEPAD_DPAD_UP | XINPUT_GAMEPAD_DPAD_LEFT; break;
            default: break;
            }
        }
    }
    SHORT axisVal = 0;
    if (rogGetScaledAxis(prep, report, reportLen, 0x30, false, &axisVal)) pad.sThumbLX = axisVal;
    if (rogGetScaledAxis(prep, report, reportLen, 0x31, true, &axisVal)) pad.sThumbLY = axisVal;
    if (rogGetScaledAxis(prep, report, reportLen, 0x32, false, &axisVal)) pad.sThumbRX = axisVal;
    if (rogGetScaledAxis(prep, report, reportLen, 0x35, true, &axisVal)) pad.sThumbRY = axisVal;
    *out = pad;
    return pad.wButtons != 0 ||
        std::abs(static_cast<int>(pad.sThumbLX)) >= GP_UI_THUMB_THRESHOLD ||
        std::abs(static_cast<int>(pad.sThumbLY)) >= GP_UI_THUMB_THRESHOLD ||
        std::abs(static_cast<int>(pad.sThumbRX)) >= GP_UI_THUMB_THRESHOLD ||
        std::abs(static_cast<int>(pad.sThumbRY)) >= GP_UI_THUMB_THRESHOLD;
}

static void rogAcceptHidPad(const XINPUT_GAMEPAD& pad) {
    g_rog.lastHidPad = pad;
    g_rog.lastHidTick = GetTickCount64();
    if (g_rog.suppressed &&
        (pad.wButtons != 0 ||
         std::abs(static_cast<int>(pad.sThumbLX)) >= GP_UI_THUMB_THRESHOLD ||
         std::abs(static_cast<int>(pad.sThumbLY)) >= GP_UI_THUMB_THRESHOLD)) {
        if (!g_rog.hidSeenAfterSuppress) {
            appendNativeLifecycleLog("rog.hid-frame", {
                {"buttons", pad.wButtons},
                {"buttonMap", g_rog.buttonMap}
            });
        }
        g_rog.hidSeenAfterSuppress = true;
    }
}

// S57 (HC OpenXInput parity): capture the SELECTED physical source's HID report
// via RawInput even while it is cloaked (YMCC is HidHide-exempt via --app-reg).
// HC reads the physical controller through OpenXInput's in-process HID mapping;
// the system XInput sample for a HID->XInput-mapped controller (Flydigi-style
// Xbox 360 spoofers) goes dead/zero once its HID source is hidden. Match the raw
// device identity against the resolved selected physical source so the virtual
// endpoint (HIDMaestro ROOT paths) is never captured as physical input.
static void physicalHidCaptureRawInput(RAWINPUT* raw) {
    if (!raw || raw->header.dwType != RIM_TYPEHID) return;
    // R3b″：身份解析调用方 = capture（caller 1）。
    GpHidResolveCallerScope gpCaller(1);
    HidHidePhysicalIdentity resolved;
    std::uint64_t resolvedGeneration = 0;
    if (!hidHideResolveRawInputIdentity(raw->header.hDevice, resolved, &resolvedGeneration) ||
        !resolved.resolved) {
        // R2（二批需求单）：未通过物理源校验的 WM_INPUT（含 HIDMaestro 虚拟路径）。
        uiCostNoteWmInputFiltered();
        return;
    }
    HidHidePhysicalIdentity selected;
    {
        // 消费侧代际守卫（评审16 R14-2 闭合）：跨代际结果不得参与物理源比较与捕获。
        // 校验代际与读取 selected 在同一临界区内完成（锁序 cacheMx → physicalIdentityMx）。
        std::lock_guard<std::mutex> cacheLock(g_hidResolveCacheMx);
        if (resolvedGeneration == 0 || resolvedGeneration != g_hidResolveCacheGeneration) {
            if (tickCostEnabled())
                g_gpSelectedGenerationRejects[1].fetch_add(1, std::memory_order_relaxed);
            uiCostNoteWmInputFiltered();
            return;
        }
        std::lock_guard<std::mutex> lock(g_hidHidePhysicalIdentityMx);
        selected = g_hidHidePhysicalIdentity;
    }
    if (!selected.resolved) { uiCostNoteWmInputFiltered(); return; }
    const bool exactIdentity = ascii_lower(resolved.physicalIdentity) ==
        ascii_lower(selected.physicalIdentity);
    // S59.1 (2026-09-11): accept reports from ANY HID collection of the SAME
    // physical device (same base container + same VID/PID). A HID->XInput
    // mapped controller (Flydigi) exposes multiple collections (IG_00 gamepad,
    // IG_01 mapping feed); the user's actual input arrives on whichever
    // collection the mapper reads, and the hide transaction may have selected a
    // different one. Requiring an equal usage page/usage rejected those reports
    // and the exempt read produced nothing during the session. The virtual
    // endpoint (HIDMaestro USB root) still has a different base container, so
    // this widened match cannot capture the virtual target.
    const bool sameHardware = resolved.vendorId == selected.vendorId &&
        resolved.productId == selected.productId &&
        resolved.baseContainerDeviceInstanceId == selected.baseContainerDeviceInstanceId;
    if (!exactIdentity && !sameHardware) {
        // R2（二批需求单）：非选中物理源（虚拟目标/其他设备）——计数后丢弃。
        uiCostNoteWmInputFiltered();
        return;
    }
    UINT prepSize = 0;
    GetRawInputDeviceInfoW(raw->header.hDevice, RIDI_PREPARSEDDATA, nullptr, &prepSize);
    if (prepSize == 0) return;
#ifdef YMCC_FAULT_INJECT
    // 评审19 §4 行使：在"已交付 selected + 已取得代际"之后、报告解析/发布之前推进
    // 代际一次（模拟解析耗时窗口内发生失效）⇒ 轻量提交点的二次校验必须拒绝发布。
    if (hidResolveFaultTake(g_fiCommitBump) > 0) {
        Sleep(2);
        hidHideInvalidateRawInputIdentityCache();
    }
#endif
    std::vector<BYTE> prepBuf(prepSize);
    if (GetRawInputDeviceInfoW(raw->header.hDevice, RIDI_PREPARSEDDATA, prepBuf.data(), &prepSize) == static_cast<UINT>(-1)) return;
    auto prep = reinterpret_cast<PHIDP_PREPARSED_DATA>(prepBuf.data());
    PCHAR report = reinterpret_cast<PCHAR>(raw->data.hid.bRawData);
    const ULONG reportLen = raw->data.hid.dwSizeHid * (raw->data.hid.dwCount ? raw->data.hid.dwCount : 1);
    XINPUT_GAMEPAD pad{};
    // map=0 is the standard gamepad usage order (0x90=A, 0x91=B, 0x92=X, 0x93=Y);
    // the ROG-only alternate maps are never applied to a non-ROG physical source.
    // RawInput delivers a report on EVERY state change, INCLUDING the release
    // (all-zero) report, so the full zero sample must be stored too — otherwise
    // the pad sticks at its last non-zero hold and never returns to center.
    // HC OpenXInput semantics: the in-process HID mapping continuously reflects
    // the physical state, zero included.
    if (reportLen > 0 && prep) {
        XINPUT_GAMEPAD pad{};
        rogParseReport(prep, report, reportLen, 0, &pad);
        if (tickCostEnabled()) g_gpCommitPointSamples.fetch_add(1, std::memory_order_relaxed);
        // 评审19 §4：**轻量提交点的二次代际校验**。上方在校验临界区内取到
        // resolvedGeneration（= 当时的代际），此处报告解析已耗时若干微秒；若这期间
        // 发生失效（代际推进），本采样属于旧代际 ⇒ 既不写 g_physicalHidPad 也不置
        // valid（不发布旧代际采样）。按同一代际规则判定（相等即未失效），只读一个
        // 原子、不进缓存锁，避免把 HID 解析塞进锁内。
        if (hidHideResolvedGenerationStillCurrent(resolvedGeneration)) {
            g_physicalHidPad = pad;
            g_physicalHidTick = GetTickCount64();
            g_physicalHidValid = true; // any delivered report is a valid sample
        } else {
            // 评审19 §4 证据计数：**提交点**（解析已耗时、发布前）因代际失效被拒绝的采样。
            if (tickCostEnabled()) {
                g_gpCommitGenerationRejects.fetch_add(1, std::memory_order_relaxed);
                g_gpSelectedGenerationRejects[1].fetch_add(1, std::memory_order_relaxed);
            }
            uiCostNoteWmInputFiltered();
        }
    }
    // 7.47（Controller 族，Legion IMU）：被选物理源为 Legion Go 手柄时，从
    // 同一豁免 HID 报告按 HC 偏移采集 IMU（LegionController.cs:64-79 + 255-295）。
    // HC 报告错位标志：byte1==0 → 整体 -2（LegionController.cs:153 + 195-205）。
    if (g_machineIdentity.family == YmccFamily::LenovoLegionGo &&
        selected.vendorId == 0x17EF && reportLen >= 60) {
        const bool misaligned = report[1] == 0;
        float lgx = 0, lgy = 0, lgz = 0, lax = 0, lay = 0, laz = 0;
        if (legionImuParse(reinterpret_cast<const BYTE*>(report), reportLen, misaligned,
                           lgx, lgy, lgz, lax, lay, laz)) {
            std::lock_guard<std::mutex> lock(g_legionImuMx);
            g_legionImuGx = lgx; g_legionImuGy = lgy; g_legionImuGz = lgz;
            g_legionImuAx = lax; g_legionImuAy = lay; g_legionImuAz = laz;
            g_legionImuTick = GetTickCount64();
            g_legionImuValid = true;
        }
    }
}

static void rogCaptureRawInput(RAWINPUT* raw) {
    if (!raw || raw->header.dwType != RIM_TYPEHID || !g_rog.identityMatched) return;
    RID_DEVICE_INFO info{};
    UINT infoSize = sizeof(info);
    info.cbSize = sizeof(info);
    if (GetRawInputDeviceInfoW(raw->header.hDevice, RIDI_DEVICEINFO, &info, &infoSize) == static_cast<UINT>(-1)) return;
    if (info.dwType != RIM_TYPEHID || info.hid.dwVendorId != 0x0B05 ||
        !rogIsAllyPid(static_cast<USHORT>(info.hid.dwProductId))) return;
    UINT prepSize = 0;
    GetRawInputDeviceInfoW(raw->header.hDevice, RIDI_PREPARSEDDATA, nullptr, &prepSize);
    if (prepSize == 0) return;
    std::vector<BYTE> prepBuf(prepSize);
    if (GetRawInputDeviceInfoW(raw->header.hDevice, RIDI_PREPARSEDDATA, prepBuf.data(), &prepSize) == static_cast<UINT>(-1)) return;
    auto prep = reinterpret_cast<PHIDP_PREPARSED_DATA>(prepBuf.data());
    PCHAR report = reinterpret_cast<PCHAR>(raw->data.hid.bRawData);
    const ULONG reportLen = raw->data.hid.dwSizeHid * (raw->data.hid.dwCount ? raw->data.hid.dwCount : 1);
    XINPUT_GAMEPAD pad{};
    int map = g_rog.buttonMapLocked ? g_rog.buttonMap : 0;
    bool parsed = rogParseReport(prep, report, reportLen, map, &pad);
    if (!g_rog.buttonMapLocked) {
        const WORD summonBits = XINPUT_GAMEPAD_LEFT_SHOULDER | XINPUT_GAMEPAD_RIGHT_SHOULDER;
        for (int candidate = 0; candidate < 3; ++candidate) {
            XINPUT_GAMEPAD trial{};
            if (!rogParseReport(prep, report, reportLen, candidate, &trial)) continue;
            if ((trial.wButtons & summonBits) == summonBits) {
                g_rog.buttonMap = candidate;
                g_rog.buttonMapLocked = true;
                pad = trial;
                parsed = true;
                break;
            }
            if (!parsed) { pad = trial; parsed = true; g_rog.buttonMap = candidate; }
        }
    }
    if (parsed) rogAcceptHidPad(pad);
}

static void rogInspectDevice(HANDLE h, const wchar_t* path, USHORT pid) {
    PHIDP_PREPARSED_DATA prep = nullptr;
    HIDP_CAPS caps{};
    if (!HidD_GetPreparsedData(h, &prep) || HidP_GetCaps(prep, &caps) != HIDP_STATUS_SUCCESS) {
        if (prep) HidD_FreePreparsedData(prep);
        CloseHandle(h);
        return;
    }
    // HC IsReady() (ROGAlly.cs:359-362) classifies each HID interface by its
    // feature-report id: it tries ReadFeatureData(INPUT_HID_ID=0x5A) and falls
    // back to ReadFeatureData(AURA_HID_ID=0x5D) when the first returns false.
    // HidLibrary.ReadFeatureData trusts the HidD_GetFeature *return value*, not
    // an echo of the requested id in buffer[0] (ROG firmware does not guarantee
    // report-id echo), so the probe here follows the same contract.  Both ids
    // are probed unconditionally: a permissive firmware that answers the 0x5A
    // probe on the Aura collection must not starve the 0x5D probe.  Each probe
    // uses a fresh zeroed buffer so no leftover byte leaks between them.
    bool report5A = false;
    bool report5D = false;
    if (caps.FeatureReportByteLength >= 5) {
        std::vector<BYTE> feature(caps.FeatureReportByteLength, 0);
        feature[0] = 0x5A;
        if (HidD_GetFeature(h, feature.data(), caps.FeatureReportByteLength) != FALSE)
            report5A = true;
        std::fill(feature.begin(), feature.end(), 0);
        feature[0] = 0x5D;
        if (HidD_GetFeature(h, feature.data(), caps.FeatureReportByteLength) != FALSE)
            report5D = true;
    }
    const bool gamepadUsage = caps.UsagePage == 0x01 && (caps.Usage == 0x04 || caps.Usage == 0x05);
    USHORT buttonCapsLen = 16;
    std::vector<HIDP_BUTTON_CAPS> buttonCaps(buttonCapsLen);
    const bool haveButtons = HidP_GetButtonCaps(HidP_Input, buttonCaps.data(), &buttonCapsLen, prep) == HIDP_STATUS_SUCCESS && buttonCapsLen > 0;
    USHORT valueCapsLen = 16;
    std::vector<HIDP_VALUE_CAPS> valueCaps(valueCapsLen);
    const bool haveValues = HidP_GetValueCaps(HidP_Input, valueCaps.data(), &valueCapsLen, prep) == HIDP_STATUS_SUCCESS && valueCapsLen > 0;
    (void)haveValues;
    // HC IsReady() picks one role per device with else-if ordering
    // (ROGAlly.cs:359-362): a device answering 0x5A wins the OEM/INPUT slot.
    // The two probes stay independent though: a collection that answers 0x5D
    // (and only then) must still become the Aura slot even when a permissive
    // firmware also returned TRUE for the 0x5A probe at a feature length that
    // does not qualify for OEM control — otherwise Aura is silently lost.
    const bool oemControl = report5A && caps.FeatureReportByteLength >= 64 && !gamepadUsage;
    const bool isAura = report5D && caps.FeatureReportByteLength >= 5 && !gamepadUsage;
    const bool stableInput = gamepadUsage && caps.InputReportByteLength >= 8;
    if (report5A && caps.FeatureReportByteLength >= 64 && g_rog.fallbackControlPath.empty()) {
        g_rog.fallbackControlPath = path;
        g_rog.fallbackFeatureLen = caps.FeatureReportByteLength;
    }
    writeLog("INFO", std::string("rog.hid-discovery vid=0x0B05 pid=0x") +
        (pid == 0x1B4C ? "1B4C" : "1ABE") +
        " report5A=" + (report5A ? "true" : "false") +
        " report5D=" + (report5D ? "true" : "false") +
        " featureLen=" + std::to_string(caps.FeatureReportByteLength) +
        " inputLen=" + std::to_string(caps.InputReportByteLength) +
        " usage=" + std::to_string(caps.Usage) +
        " path=" + W2U(path));
    // Per-collection audit merged into the shared lifecycle stream (same channel
    // as rog.hid-bound), so a lighting regression can be traced to which probe
    // failed without a separate info-log export.
    appendNativeLifecycleLog("rog.hid-discovery", {
        {"usbProductId", pid ? static_cast<int>(pid) : 0},
        {"report5A", report5A},
        {"report5D", report5D},
        {"featureLen", static_cast<int>(caps.FeatureReportByteLength)},
        {"inputLen", static_cast<int>(caps.InputReportByteLength)},
        {"usagePage", static_cast<int>(caps.UsagePage)},
        {"usage", static_cast<int>(caps.Usage)},
        {"oemControl", oemControl},
        {"isAura", isAura},
        {"stableInput", stableInput}
    });
    if (oemControl && !g_rog.hasControl) {
        g_rog.control = h;
        g_rog.controlPath = path;
        g_rog.featureLen = caps.FeatureReportByteLength;
        g_rog.hasControl = true;
        g_rog.identityMatched = true;
        g_rog.productId = pid;
        h = INVALID_HANDLE_VALUE;
    }
    // HC owns the Aura lighting collection as its own HidDevice
    // (hidDevices[AURA_HID_ID]); lighting writes go out this handle only.
    // h was consumed by the OEM branch above; never adopt an invalid handle.
    if (isAura && h != INVALID_HANDLE_VALUE) {
        // §21 R2 扩展：Aura 句柄的**赋值也在 g_rogAuraMx 下**（与关闭/写入同一归属）。
        // 双检避免并发下两个线程都领养；未领养时 h 由函数末尾统一 CloseHandle（不泄漏）。
        std::lock_guard<std::mutex> auraLock(g_rogAuraMx);
        if (g_rog.auraControl == INVALID_HANDLE_VALUE) {
            g_rog.auraControl = h;
            g_rog.auraPath = path;
            g_rog.auraFeatureLen = caps.FeatureReportByteLength;
            g_rog.identityMatched = true;
            g_rog.productId = pid;
            h = INVALID_HANDLE_VALUE;
        }
    }
    if (stableInput && !g_rog.hasStableInput) {
        // Never CreateFile the gamepad HID. Opening it steals the device from
        // XInput/GameInput and leaves YMCC without a working pad.
        g_rog.hasStableInput = true;
        g_rog.inputLen = caps.InputReportByteLength;
        g_rog.inputPath = path;
    }
    if (prep) HidD_FreePreparsedData(prep);
    if (h != INVALID_HANDLE_VALUE) CloseHandle(h);
}

static void rogBindInputHid() {
    g_entryTestBindCalls.fetch_add(1, std::memory_order_acq_rel);   // 自测观察点（生产不读）
    if (g_rog.suppressed) return;
    // B1-ext（2026-09-11）：绑定幂等化——已绑定且设备未断言移除时直返，
    // 对齐 HC AsusACPI 一次性 InitializeAsync 语义（设备绑定后不每次重扫）。
    // g_rog.hasControl 表示 XInput/HID control 句柄已打开；
    // g_rog.identityMatched 表示匹配过 VID_0B05；两者齐备即视为绑定完成，
    // 重复调用（Ensure 重试 / 多个窗口事件源）不再整段重发现，消除
    // rog.hid-discovery/bound 高频刷屏（8 分钟 28 次源）。设备拔出重插时
    // 外部路径先 rogCloseSession 再重绑（resume/boot 路径语义不变）。
    if (g_rog.hasControl && g_rog.identityMatched) return;
    // §14.2：身份丢失（设备断连/解绑）后重新匹配到设备 = 一次真实重连代次
    // （固件映射不保证存活），作废重映射记账 ⇒ 下一次调用重写而非错复用。
    const bool hadIdentity = g_rog.identityMatched;
    rogCloseSession(false);
    // §21 R3：身份已丢 ⇒ 打包签名立即反映"无身份"（脏事件复核按单原子快照判定）。
    g_rogRemapBoundSig.store(rogRemapPackSig(g_rog.epoch, false, 0, 0), std::memory_order_release);
    HDEVINFO set = SetupDiGetClassDevsW(&kYeManGuidDeviceInterfaceHid, nullptr, nullptr,
        DIGCF_PRESENT | DIGCF_DEVICEINTERFACE);
    if (set == INVALID_HANDLE_VALUE) {
        writeLog("INFO", "rog.hid-discovery.matches=0");
        appendNativeLifecycleLog("rog.hid-bound", {{"matched", false}, {"reason", "no-hid-set"}});
        return;
    }
    int matches = 0;
    for (DWORD index = 0;; ++index) {
        SP_DEVICE_INTERFACE_DATA iface{}; iface.cbSize = sizeof(iface);
        if (!SetupDiEnumDeviceInterfaces(set, nullptr, &kYeManGuidDeviceInterfaceHid, index, &iface)) break;
        DWORD bytes = 0;
        SetupDiGetDeviceInterfaceDetailW(set, &iface, nullptr, 0, &bytes, nullptr);
        if (!bytes) continue;
        std::vector<BYTE> detailBuf(bytes);
        auto detail = reinterpret_cast<SP_DEVICE_INTERFACE_DETAIL_DATA_W*>(detailBuf.data());
        detail->cbSize = sizeof(SP_DEVICE_INTERFACE_DETAIL_DATA_W);
        if (!SetupDiGetDeviceInterfaceDetailW(set, &iface, detail, bytes, nullptr, nullptr)) continue;
        HANDLE h = CreateFileW(detail->DevicePath, GENERIC_READ | GENERIC_WRITE,
            FILE_SHARE_READ | FILE_SHARE_WRITE, nullptr, OPEN_EXISTING, 0, nullptr);
        if (h == INVALID_HANDLE_VALUE) continue;
        HIDD_ATTRIBUTES attrs{}; attrs.Size = sizeof(attrs);
        if (HidD_GetAttributes(h, &attrs) && attrs.VendorID == 0x0B05 && rogIsAllyPid(attrs.ProductID)) {
            ++matches;
            g_rog.identityMatched = true;
            g_rog.productId = attrs.ProductID;
            rogInspectDevice(h, detail->DevicePath, attrs.ProductID);
        } else {
            CloseHandle(h);
        }
    }
    SetupDiDestroyDeviceInfoList(set);
    writeLog("INFO", "rog.hid-discovery.matches=" + std::to_string(matches) +
        " control=" + (g_rog.hasControl ? "true" : "false") +
        " stableInput=" + (g_rog.hasStableInput ? "true" : "false"));
    if (!g_rog.hasControl && !g_rog.fallbackControlPath.empty()) {
        HANDLE ch = CreateFileW(g_rog.fallbackControlPath.c_str(), GENERIC_READ | GENERIC_WRITE,
            FILE_SHARE_READ | FILE_SHARE_WRITE, nullptr, OPEN_EXISTING, 0, nullptr);
        if (ch != INVALID_HANDLE_VALUE) {
            g_rog.control = ch;
            g_rog.controlPath = g_rog.fallbackControlPath;
            g_rog.featureLen = g_rog.fallbackFeatureLen;
            g_rog.hasControl = true;
        }
    }
    // §21 R2 扩展：Aura 句柄可见性也在 g_rogAuraMx 下读取（与赋值/关闭/写入同归属）
    bool hasAuraControl = false;
    {
        std::lock_guard<std::mutex> auraLock(g_rogAuraMx);
        hasAuraControl = (g_rog.auraControl != INVALID_HANDLE_VALUE);
    }
    appendNativeLifecycleLog("rog.hid-bound", {
        {"matched", g_rog.identityMatched},
        {"hasControl", g_rog.hasControl},
        {"hasAuraControl", hasAuraControl},
        {"hasStableInput", g_rog.hasStableInput},
        {"usbProductId", g_rog.productId},
        {"featureLen", g_rog.featureLen},
        {"auraFeatureLen", g_rog.auraFeatureLen},
        {"inputLen", g_rog.inputLen},
        {"matches", matches}
    });
    // §15.1 ③ / §21 R3：绑定签名镜像（**单原子打包**）。裁决更正：bool 身份 + 产品 PID 不是
    // 完整设备身份，同 PID 换实例也应付得出"有效换代"。此处用两个可判据：
    //   ① 身份丢失后重获（!hadIdentity && identityMatched）⇒ 会话 epoch +1；
    //   ② 控制接口路径变化（同 PID 换实例/换接口）⇒ 会话 epoch +1。
    // 二者任一发生都让打包签名变化 ⇒ 脏事件复核判 Relevant（放弃退避、重写）。
    const unsigned long long pathHash = rogRemapPathHash15(g_rog.controlPath);
    if (!hadIdentity && g_rog.identityMatched) {
        ++g_rog.epoch;
        g_rogRemapLastPathHash = pathHash;
        rogRemapNoteDeviceGeneration("identity-reacquired");
    } else if (g_rog.identityMatched && pathHash != g_rogRemapLastPathHash) {
        ++g_rog.epoch;
        g_rogRemapLastPathHash = pathHash;
        rogRemapNoteDeviceGeneration("control-instance-changed");
    }
    g_rogRemapBoundSig.store(
        rogRemapPackSig(g_rog.epoch, g_rog.identityMatched, g_rog.productId, pathHash),
        std::memory_order_release);

    // HC 等价点：HC 在 Device_Inserted 里调 ConfigureController(true)
    // （注释原文 "force M1/M2 to send F17 and F18"，ROGAlly.cs:288-290）。
    // YMCC 此前只在 boot/resume/window-hidden/suspend 等生命周期补写；若 ROG 控制
    // 接口是启动后才绑定成功（或首次绑定失败后重试成功），旧写法就不会补写 →
    // 背键永不产生 F17/F18（真机表现为「背键完全没反应」）。
    // 这里在绑定成功后幂等补写：目标态记忆 + 5s 节流 + 防重入守卫都在
    // rogEnsureControllerRemap 内部，重复调用无副作用；g_inputReady 之前不写，
    // 避免早期启动期 HID 写阻塞（0915-19 冻结教训）。
    if (g_rog.hasControl && g_rog.identityMatched &&
        g_inputReady.load(std::memory_order_acquire)) {
        (void)rogEnsureControllerRemap(true, "hid-bound");
    }
    // 独占归属（§4.3）依赖"已绑定接口作容器基准"，而绑定往往发生在启动之后：
    // 绑定结束时重跑一次 gate（入参用上次留存值），把 Raw Input 独占通路接上。
    // 幂等：gate 内部只做判定与开关，且 5s 节流保护 remap 写入。
    oemBackMappingRefreshGate(g_oemGateTargetEnabled, g_oemGatePersona, g_oemGateBackMapping);
}

// §21 R2：真实会话原语 + 接缝取值（定义位置必须在所有真实原语之后）。
// 生产路径恒走 `real`；只有自测进程会把 g_rogSessionOpsFakeActive 置真，
// 从而让**同一个入口/同一个协调函数**驱动假设备（不另抄一套测试算法）。
static void rogOpsRealClose(bool keepIdentity) { rogCloseSession(keepIdentity); }
static bool rogOpsRealEnsure() {
    rogCloseSession(true);
    rogBindInputHid();
    return g_rog.hasControl;
}
static void rogOpsRealDelay() { Sleep(80); }
static int rogOpsRealWriteSeq(bool remap) { return rogWriteControllerRemapSeq(remap); }
static bool rogOpsRealWriteFace() { return rogWriteXboxFaceEnabled(); }
static std::string rogOpsRealReadBack() { return rogReadBackFeatureReport(); }
static const RogSessionOps& rogSessionOps() {
    static const RogSessionOps real{rogOpsRealClose, rogOpsRealEnsure, rogOpsRealDelay,
                                    rogOpsRealWriteSeq, rogOpsRealWriteFace, rogOpsRealReadBack};
    if (g_rogSessionOpsFakeActive.load(std::memory_order_acquire)) return g_rogSessionOpsFake;
    return real;
}

static bool rogEnsureXboxFaceEnabled(const char* reason) {
    if (g_aiFanMockSession.isolated) return false;
    const char* why = reason ? reason : "";
    const auto phase = g_powerLifecycle.load(std::memory_order_acquire);
    const bool powerQuiet = phase != PowerLifecycle::Ready ||
        !g_inputReady.load(std::memory_order_acquire);
    // 0915-19: PBT_APMSUSPEND HID writes blocked the UI thread (first YMCC freeze).
    // window-hidden writes during wake recreate collided with virtual DS4 Dispose.
    if (std::strcmp(why, "suspend") == 0 ||
        (std::strcmp(why, "window-hidden") == 0 &&
         (powerQuiet || g_wakeHoldPhysicalUnhide.load(std::memory_order_acquire)))) {
        appendNativeLifecycleLog("rog.xbox-face-skipped", {
            {"reason", why},
            {"phase", powerLifecycleName(phase)},
            {"inputReady", g_inputReady.load(std::memory_order_acquire)},
            {"wakeHold", g_wakeHoldPhysicalUnhide.load(std::memory_order_acquire)}
        });
        return false;
    }
    // §21 R2：这段控制会话操作（close/bind/0x5A 写入/收尾同步）必须与重映射记账**同一安全边界**——
    // 否则另一线程可以在本线程使用 g_rog.control 期间关闭/重绑同一会话（裁决实读指出的缺口）。
    // 因此：早退判断保持在边界外（便宜），进入边界后才 close/bind/写；收尾的目标态同步
    // 直接调用**核心**（已持边界锁，避免同线程二次取锁，也不再走会触发递归判定的公共入口）。
    const bool terminalPath = rogRemapTerminalReason(why);
    RogRemapGuardScope guard;                          // 只挡本线程内 绑定↔重映射 互递归
    if (!guard.acquired) {
        rogRemapLog("rog.controller-remap-skipped", {{"reason", why}, {"skip", "thread-recursion"}});
        return false;
    }
    RogRemapBoundaryScope boundary(terminalPath ? kRogRemapTerminalWaitBudgetMs : 0u);
    if (!boundary.entered) {
        rogRemapLog("rog.controller-remap-busy", {{"reason", why}, {"terminal", terminalPath}});
        if (terminalPath) rogRemapNoteExitUnresolved("wait-budget-exhausted");
        return false;
    }
    const RogSessionOps& ops = rogSessionOps();
    g_rog.suppressed = false;
    g_rog.restoreRequired = false;
    g_rog.hidSeenAfterSuppress = false;
    g_rog.suppressTick = 0;
    ops.closeSession(true);
    ops.ensureSession();
    bool wrote = false;
    for (int attempt = 0; attempt < 5; ++attempt) {
        if (!g_rog.hasControl) {
            ops.closeSession(true);
            ops.ensureSession();
        }
        if (g_rog.hasControl) wrote = ops.writeFace();
        if (wrote) break;
        ops.closeSession(true);
        ops.retryDelay();
        ops.ensureSession();
    }
    rogRemapLog("rog.xbox-face-enabled", {
        {"reason", why},
        {"wrote", wrote},
        {"terminal", terminalPath},
        {"hasControl", g_rog.hasControl},
        {"usbProductId", g_rog.productId},
        {"matches", 0}
    });
    // 2026-09-23 W3 取证（**gated**：只在 domainLogs.virtual 高频开关打开时写，关闭零成本零写入）：
    // "Xbox 呼出"排查用 —— 记录本次 face 写入的会话状态快照，不学习常驻低频区。
    // 2026-09-23 W3 取证：本行属**事件级**（每次会话个位数），按 operator 裁决进常开/低频区。
    appendNativeLifecycleLog("domain-xbox-face-write", {
        {"reason", why},
        {"wrote", wrote},
        {"terminal", terminalPath},
        {"hasControl", g_rog.hasControl},
        {"usbProductId", g_rog.productId},
        {"suppressed", g_rog.suppressed},
        {"restoreRequired", g_rog.restoreRequired},
        {"hidSeenAfterSuppress", g_rog.hidSeenAfterSuppress},
        {"powerPhase", powerLifecycleName(g_powerLifecycle.load(std::memory_order_acquire))}
    });
    writeLog("INFO", std::string("rog.xbox-face-enabled reason=") + why +
        " wrote=" + (wrote ? "true" : "false"));
    // A 方案（2026-09-16 用户定案）：同步维护 M1/M2 重映射目标态——
    // exit/destroy 写回 M1M2Default（HC Close 同款）；其余保持 M1F18M2F17
    // （背键映射 hook 的物理前置：F18→M1(bit0)→L5、F17→M2(bit1)→R5）。
    (void)rogRemapCoreLocked(!terminalPath, why, terminalPath);
    return wrote;
}

// ── HC ROGAlly AURA lighting port (HandheldCompanion Devices/ASUS/ROGAlly.cs) ──
// The ASUS vendor HID exposes two mutually exclusive interfaces classified by
// feature-report id (HC IsReady(), ROGAlly.cs:359-362): 0x5A => OEM control
// (Xbox face writes) and 0x5D => Aura lighting collection. The lighting path
// opens the 0x5D interface as its own handle (g_rog.auraControl) and writes
// byte-for-byte the same AuraMessage / apply / set frames as HC, padded to the
// 64-byte output-report buffer that HidDeviceExtensions.Write sends.
static constexpr BYTE kRogAuraReportId = 0x5d;

enum class RogAuraMode : BYTE { Solid = 0, Breathing = 1, Wheel = 2, Rainbow = 3, Wave = 4 };
enum class RogAuraSpeed : BYTE { Slow = 0xeb, Medium = 0xf5, Fast = 0xe1 };
enum class RogAuraDirection : BYTE { Forward = 0, Reverse = 1 };
enum class RogAuraZone : BYTE {
    All = 0,
    JoystickLeftSideLeft = 1, JoystickLeftSideRight = 2,
    JoystickRightSideLeft = 3, JoystickRightSideRight = 4,
};

// （g_rogAuraMx 的声明已提前到 RogInputSession 之后，见 §21 R2 扩展注释）

// HC DeviceCapabilities/DynamicLightingCapabilities are static class-level
// bits on IDevice.GetCurrent() (ROGAlly.cs:113-124; DevicePage.xaml.cs gates
// the lighting panel and each effect by those bits). YMCC implements the ROG
// Aura backend only, so the ROG Ally family exposes the same lighting set as
// HC's ROGAlly-derived classes; every other machine has no lighting capability
// and its UI must hide the lighting controls instead of showing a disabled
// panel.
static bool machineIsRogAllyFamily() {
    switch (g_machineIdentity.family) {
        case YmccFamily::AsusRogAllyX:
        case YmccFamily::AsusRogAlly:
        case YmccFamily::AsusRogAllyClassic:
        case YmccFamily::AsusRogAllyXClassic:
            return true;
        default:
            return false;
    }
}

static std::vector<BYTE> rogAuraMessage(RogAuraMode mode, BYTE r1, BYTE g1, BYTE b1,
                                        BYTE r2, BYTE g2, BYTE b2,
                                        RogAuraSpeed speed, RogAuraDirection direction,
                                        RogAuraZone zone) {
    // HC AuraMessage(): 17-byte output report; bytes 0..12 carry zone/mode/colors.
    std::vector<BYTE> msg(17, 0);
    msg[0] = kRogAuraReportId;
    msg[1] = 0xb3;
    msg[2] = static_cast<BYTE>(zone);
    msg[3] = static_cast<BYTE>(mode);
    msg[4] = r1; msg[5] = g1; msg[6] = b1;
    msg[7] = static_cast<BYTE>(speed);
    msg[8] = static_cast<BYTE>(direction);
    msg[9] = (mode == RogAuraMode::Breathing) ? 1 : 0;
    msg[10] = r2; msg[11] = g2; msg[12] = b2;
    return msg;
}

static bool rogAuraWriteLocked(const std::vector<BYTE>& report) {
    if (g_rog.auraControl == INVALID_HANDLE_VALUE || report.empty()) return false;
    // HC parity (HidDeviceExtensions.Write, reportLength=64): the short Aura
    // frame is padded to the device's full output-report buffer before send.
    // A raw 17/2/5-byte WriteFile does not match the ROG Aura collection's
    // output-report length and the frame is ignored by the device.
    std::vector<BYTE> padded(64, 0);
    std::copy(report.begin(),
              report.begin() + std::min(report.size(), padded.size()),
              padded.begin());
    DWORD written = 0;
    if (!WriteFile(g_rog.auraControl, padded.data(), static_cast<DWORD>(padded.size()), &written, nullptr))
        return false;
    return written == padded.size();
}

static RogAuraSpeed rogAuraSpeedFromPercent(int percent) {
    // HC SetLedColor(): speed <= 33 slow, <= 66 medium, else fast.
    if (percent <= 33) return RogAuraSpeed::Slow;
    return percent <= 66 ? RogAuraSpeed::Medium : RogAuraSpeed::Fast;
}

// ── L1 方案 B（2026-09-16）：YeManLightSetter 一次性子进程 ──────────────
// 非 ROG 机型经子进程直驱 HC 程序集执行灯光设置（Legion/MSI/AYANEO/OneX/
// Zotac/AYN/AOKZOE/SuiPlay——各机型 EC/HID/USB 协议由 HC 内部处理；与
// FanLab 同构：SHA-256 锁定的 HandheldCompanion.dll + IsReady/Open 激活）。
// exe 与 fan-host 同目录部署；HC 运行时为锁定候选目录（与 fan-host 同源）。
// setLed 为低频 IPC 调用（非 BUS 线程），同步等待进程完成；成功以退出码
// 判定（子进程 JSON stdout 供诊断）。
static const std::wstring kLightSetterExe =
    POWER_CONTROL_DIR + L"\\light-setter\\YeManLightSetter.exe";
static const std::wstring kLightSetterHcRuntimeRoot =
    POWER_CONTROL_DIR + L"\\handheldcompanion-runtime\\HC-CANDIDATE-0.32.4.0-06c0b954-20260902";
// R1-3：子进程 stdout 读取的独立期限与长度上限（写端被继承时不无界阻塞；超长输出截断）。
static constexpr DWORD kLightSetterReadBudgetMs = 5000;
static constexpr size_t kLightSetterMaxOutputBytes = 64 * 1024;

static json ymccLightSetterApply(bool enabled, const std::string& mode,
                                 BYTE r1, BYTE g1, BYTE b1,
                                 BYTE r2, BYTE g2, BYTE b2,
                                 int speed, int brightness) {
    if (GetFileAttributesW(kLightSetterExe.c_str()) == INVALID_FILE_ATTRIBUTES)
        return json{{"ok", false}, {"reason", "light-setter-missing"}};
    const std::wstring hcDll = kLightSetterHcRuntimeRoot + L"\\HandheldCompanion.dll";
    if (GetFileAttributesW(hcDll.c_str()) == INVALID_FILE_ATTRIBUTES)
        return json{{"ok", false}, {"reason", "hc-runtime-missing"}};

    std::wostringstream cmd;
    cmd << L'"' << kLightSetterExe << L'"'
        << L" --hc-assembly \"" << hcDll << L'"'
        << L" --hc-runtime-root \"" << kLightSetterHcRuntimeRoot << L'"';
    if (!enabled) {
        // HC DynamicLightingManager.UpdateLED() turn-off 分支同构（子进程内
        // 执行 SetLedStatus(false)+SetLedBrightness(0)+Black Solid）。
        cmd << L" --action off";
    } else {
        cmd << L" --action color --level " << U2W(mode)
            << L" --r " << static_cast<int>(r1) << L" --g " << static_cast<int>(g1)
            << L" --b " << static_cast<int>(b1)
            << L" --r2 " << static_cast<int>(r2) << L" --g2 " << static_cast<int>(g2)
            << L" --b2 " << static_cast<int>(b2)
            << L" --speed " << speed
            << L" --brightness " << brightness;
    }

    // 单一实参只取一次 str()：旧代码两次 cmd.str() 产生两个临时对象，且
    // CreateProcessW 会就地写入命令行缓冲——临时对象生命周期/别名风险。
    const std::wstring cmdText = cmd.str();
    std::vector<wchar_t> cmdLine(cmdText.begin(), cmdText.end());
    cmdLine.push_back(L'\0');

    // 捕获子进程 stdout（单行 JSON）。LightSetter 只写 stdout（异常也序列化
    // 到 stdout），故 stderr 合流到同一管道。64KB 远大于单行 JSON，子进程不会
    // 因管道写满而阻塞，父进程可在进程退出后一次性读取（不新增读线程）。
    SECURITY_ATTRIBUTES sa{sizeof(sa), nullptr, TRUE};
    HANDLE hOutR = nullptr, hOutW = nullptr;
    if (!CreatePipe(&hOutR, &hOutW, &sa, 64 * 1024)) {
        return json{{"ok", false}, {"reason", "light-setter-pipe-failed"},
                    {"error", static_cast<unsigned long long>(GetLastError())}};
    }
    SetHandleInformation(hOutR, HANDLE_FLAG_INHERIT, 0);

    STARTUPINFOW si{sizeof(si)};
    si.dwFlags = STARTF_USESTDHANDLES | STARTF_USESHOWWINDOW;
    si.wShowWindow = SW_HIDE;
    si.hStdOutput = hOutW;
    si.hStdError = hOutW;
    si.hStdInput = GetStdHandle(STD_INPUT_HANDLE);
    PROCESS_INFORMATION pi{};
    if (!CreateProcessW(nullptr, cmdLine.data(), nullptr, nullptr, TRUE,
                        CREATE_NO_WINDOW, nullptr, nullptr, &si, &pi)) {
        const DWORD err = GetLastError();
        CloseHandle(hOutR);
        CloseHandle(hOutW);
        return json{{"ok", false}, {"reason", "light-setter-spawn-failed"},
                    {"error", static_cast<unsigned long long>(err)}};
    }
    CloseHandle(hOutW);  // 父进程不持写端：子进程退出后读端立即断管/EOF

    const DWORD wait = WaitForSingleObject(pi.hProcess, 30000);
    DWORD exitCode = 1;
    const bool timedOut = (wait != WAIT_OBJECT_0);
    if (!timedOut) GetExitCodeProcess(pi.hProcess, &exitCode);
    else TerminateProcess(pi.hProcess, 1);

    // R1-3：有界读取。写端被继承（子进程已死但句柄未关）时不无界阻塞；
    //      同时限制累计长度，防止异常子进程刷爆内存。
    // R2-3：读取期限、截断、实际读取错误均记为本次调用的失败标志（进入接受门）。
    // 合计预算：进程等待 30000ms + 读取期限 kLightSetterReadBudgetMs，
    // 内存上限 kLightSetterMaxOutputBytes。
    std::string childOut;
    bool outputTruncated = false, outputReadTimedOut = false, outputReadError = false;
    {
        const ULONGLONG readDeadline = GetTickCount64() + kLightSetterReadBudgetMs;
        char buf[4096];
        for (;;) {
            if (childOut.size() >= kLightSetterMaxOutputBytes) { outputTruncated = true; break; }
            DWORD avail = 0;
            if (!PeekNamedPipe(hOutR, nullptr, 0, nullptr, &avail, nullptr)) {
                // 写端全部关闭属正常 EOF；其它错误记为实际读取错误。
                const DWORD e = GetLastError();
                if (e != ERROR_BROKEN_PIPE && e != ERROR_HANDLE_EOF && e != ERROR_NO_DATA)
                    outputReadError = true;
                break;
            }
            if (avail == 0) {
                if (GetTickCount64() >= readDeadline) { outputReadTimedOut = true; break; }
                Sleep(10);
                continue;
            }
            const DWORD want = static_cast<DWORD>((std::min)(sizeof(buf),
                kLightSetterMaxOutputBytes - childOut.size()));
            DWORD rd = 0;
            if (!ReadFile(hOutR, buf, want, &rd, nullptr)) {
                const DWORD e = GetLastError();
                if (e != ERROR_BROKEN_PIPE && e != ERROR_HANDLE_EOF && e != ERROR_NO_DATA)
                    outputReadError = true;
                break;
            }
            if (rd == 0) break;   // 正常 EOF
            childOut.append(buf, rd);
        }
    }
    CloseHandle(hOutR);
    CloseHandle(pi.hThread);
    CloseHandle(pi.hProcess);

    // 子进程输出契约（LightSetter/Program.cs）：成功
    // {ok:true,result:{deviceClass,hcSha256,ready,opened,action,note}}，失败
    // {ok:false,error}；退出码 0 当且仅当 note=="ok"。note 取值：
    //   color: "ok" | "setLedColor-false" | "setLedBrightness-false"
    //   off:   "ok" | "off-partial"
    // R1-3：严格区分子进程“声明”与本次调用“接受”的结果——子进程 ok:false 时，
    //       即便 result.note 字面量为 "ok"，也绝不再回执 reason=="ok"。
    bool hasJson = false, hasChildOkField = false, childDeclaredOk = false;
    std::string note;
    try {
        const json cj = json::parse(childOut);
        hasJson = true;
        hasChildOkField = cj.contains("ok") && cj["ok"].is_boolean();
        childDeclaredOk = cj.value("ok", false);
        if (cj.contains("result") && cj["result"].is_object())
            note = cj["result"].value("note", std::string());
        if (note.empty() && cj.contains("error"))
            note = cj.value("error", std::string());
    } catch (...) {
        hasJson = false;
    }

    const bool childReportedOk = hasJson && hasChildOkField && childDeclaredOk;
    // R2-3：读取超时/截断/实际读取错误必须进入接受门——已捕获的合法 JSON 不能覆盖它们。
    const bool resultAccepted = !timedOut && !outputReadTimedOut && !outputTruncated &&
                                !outputReadError && exitCode == 0 && childReportedOk;
    // 色彩效果落地与亮度落地的严格推导（仅在本次调用接受结果时成立）：
    //   note=="ok"                    → 色+亮度均落地
    //   note=="setLedBrightness-false"→ 色落地、亮度未落地
    //   note=="setLedColor-false"     → 色未落地
    //   note=="off-partial"           → 关闭仅部分成功
    const bool effectApplied = resultAccepted &&
        (note == "ok" || note == "setLedBrightness-false");
    const bool brightnessApplied = resultAccepted && note == "ok";

    // 硬门：超时 / 读取超时 / 截断 / 读取错误 / 退出码非零 / 子进程未声明 ok / 效果未落地
    // 一律不得报成功。不变量：reason=="ok" ⟺ ok==true；超时、读取失败或结果未被接受时
    // effect/brightness 恒 false。
    const bool ok = resultAccepted && effectApplied;
    std::string reason;
    if (timedOut) reason = "light-setter-timeout";
    else if (outputReadTimedOut) reason = "light-setter-output-read-timeout";
    else if (outputTruncated) reason = "light-setter-output-truncated";
    else if (outputReadError) reason = "light-setter-output-read-error";
    else if (!hasJson) reason = "light-setter-no-json";
    else if (!hasChildOkField) reason = "light-setter-result-unreported";
    else if (!childDeclaredOk) reason = "light-setter-result-not-ok";
    else if (exitCode != 0) reason = "light-setter-exit-" + std::to_string(exitCode);
    else if (note != "ok" && note != "setLedBrightness-false")
        reason = note.empty() ? "light-setter-effect-not-applied" : note;
    else reason = "ok";
    return json{{"ok", ok},
                {"action", enabled ? "color" : "off"},
                {"backend", "hc-direct-light-setter"},
                {"reason", reason},
                {"childDeclaredOk", childDeclaredOk},
                {"resultAccepted", resultAccepted},
                {"effectApplied", effectApplied},
                {"brightnessApplied", brightnessApplied},
                {"note", note},
                {"outputBytes", static_cast<unsigned long long>(childOut.size())},
                {"outputTruncated", outputTruncated},
                {"outputReadTimedOut", outputReadTimedOut},
                {"outputReadError", outputReadError},
                {"exitCode", static_cast<int>(exitCode)},
                {"timedOut", timedOut}};
}

static bool rogAuraApplyColor(RogAuraMode mode, BYTE r1, BYTE g1, BYTE b1,
                               BYTE r2, BYTE g2, BYTE b2, int percent) {
    // HC ApplyColor(): color report, then MESSAGE_APPLY (0x5d b4), MESSAGE_SET (0x5d b5 0 0 0).
    std::lock_guard<std::mutex> lock(g_rogAuraMx);
    const RogAuraSpeed speed = rogAuraSpeedFromPercent(percent);
    bool ok = rogAuraWriteLocked(rogAuraMessage(mode, r1, g1, b1, r2, g2, b2, speed, RogAuraDirection::Forward, RogAuraZone::All));
    ok &= rogAuraWriteLocked({kRogAuraReportId, 0xb4});
    ok &= rogAuraWriteLocked({kRogAuraReportId, 0xb5, 0, 0, 0});
    return ok;
}

static bool rogAuraApplyAmbilight(BYTE r1, BYTE g1, BYTE b1, BYTE r2, BYTE g2, BYTE b2) {
    // HC ApplyColorFast(): per-zone solid writes, main color left / secondary right.
    std::lock_guard<std::mutex> lock(g_rogAuraMx);
    bool ok = true;
    ok &= rogAuraWriteLocked(rogAuraMessage(RogAuraMode::Solid, r1, g1, b1, r1, g1, b1,
        RogAuraSpeed::Slow, RogAuraDirection::Forward, RogAuraZone::JoystickLeftSideLeft));
    ok &= rogAuraWriteLocked(rogAuraMessage(RogAuraMode::Solid, r1, g1, b1, r1, g1, b1,
        RogAuraSpeed::Slow, RogAuraDirection::Forward, RogAuraZone::JoystickLeftSideRight));
    ok &= rogAuraWriteLocked(rogAuraMessage(RogAuraMode::Solid, r2, g2, b2, r2, g2, b2,
        RogAuraSpeed::Slow, RogAuraDirection::Forward, RogAuraZone::JoystickRightSideLeft));
    ok &= rogAuraWriteLocked(rogAuraMessage(RogAuraMode::Solid, r2, g2, b2, r2, g2, b2,
        RogAuraSpeed::Slow, RogAuraDirection::Forward, RogAuraZone::JoystickRightSideRight));
    return ok;
}

static bool rogAuraSetBrightness(int percent) {
    // HC SetLedBrightness(): ROG Ally range is 0..3 with 0 = off.
    std::lock_guard<std::mutex> lock(g_rogAuraMx);
    if (g_rog.auraControl == INVALID_HANDLE_VALUE) return false;
    const BYTE level = static_cast<BYTE>(std::lround(
        static_cast<double>(std::clamp(percent, 0, 100)) / 33.33));
    // HC parity: SetLedBrightness builds { AURA_HID_ID, 0xba, 0xc5, 0xc4, level }
    // and sends via HidDevice.WriteFeatureData, which pads to the collection's
    // FeatureReportByteLength (64 on ROG). HidD_SetFeature requires the full
    // report buffer — a 5-byte frame is rejected by the device, so brightness
    // (including the 0 = off level) never lands. Pad to auraFeatureLen.
    const ULONG len = g_rog.auraFeatureLen > 0 ? g_rog.auraFeatureLen : 64;
    std::vector<BYTE> feature(len, 0);
    feature[0] = kRogAuraReportId;
    if (len >= 5) {
        feature[1] = 0xba; feature[2] = 0xc5; feature[3] = 0xc4; feature[4] = level;
    }
    return HidD_SetFeature(g_rog.auraControl, feature.data(), len) != FALSE;
}

static bool parseRgbHex(const std::string& value, BYTE& r, BYTE& g, BYTE& b) {
    auto hex = value;
    if (!hex.empty() && hex[0] == '#') hex.erase(hex.begin());
    if (hex.size() != 6) return false;
    const auto nibble = [](char c) -> int {
        if (c >= '0' && c <= '9') return c - '0';
        if (c >= 'a' && c <= 'f') return c - 'a' + 10;
        if (c >= 'A' && c <= 'F') return c - 'A' + 10;
        return -1;
    };
    const int a = nibble(hex[0]); const int b0 = nibble(hex[1]);
    const int c = nibble(hex[2]); const int d = nibble(hex[3]);
    const int e = nibble(hex[4]); const int f = nibble(hex[5]);
    if (a < 0 || b0 < 0 || c < 0 || d < 0 || e < 0 || f < 0) return false;
    r = static_cast<BYTE>((a << 4) | b0);
    g = static_cast<BYTE>((c << 4) | d);
    b = static_cast<BYTE>((e << 4) | f);
    return true;
}

// ── MSI Claw 原生灯光后端（2026-09-29，方案 A）──────────────────────────
// 移植 ClawTweaks MsiClawLedController（Isolated\Tasks\Gamepad\_scratch\
// ctw-helper-decomp；与 HC ClawA1M.GetRGB 在 solid 下逐字节一致）：HID Output
// Report 64B，首字节 0x0F（无 report id 前缀）。地址由固件
// （HIDD_ATTRIBUTES.VersionNumber = CTW ReleaseNumberBcd）最近匹配 CTW
// FirmwareTable / HC deviceVersions 取 add1/add2（两表相同）。写序对齐 CT
// TrySetZonesEffect：主块 1 帧 + 3 个 raw 块（num+32 / num+59 / num+86）= 4 帧，
// 单句柄复用、单次尝试无重试（CT LED 路径确无重试；5 次/200ms 仅属模式切换）。
static constexpr int kMsiLedZoneCount = 9;  // GetRGB 27B = 9 区 × RGB
static const int kMsiLedRawOffsets[] = {32, 59, 86};  // CTW num+32/+59/+86

struct MsiLedFwEntry { ULONG firmware; BYTE add1; BYTE add2; };
static constexpr MsiLedFwEntry kMsiLedFwTable[] = {
    {0x163, 0x01, 0xFA}, {0x166, 0x02, 0x4A}, {0x167, 0x02, 0x4A},
    {0x211, 0x01, 0xFA}, {0x217, 0x02, 0x4A}, {0x219, 0x02, 0x4A},
    {0x308, 0x02, 0x4A}, {0x411, 0x02, 0x4A},
};

// 最近匹配（CTW ResolveRgbAddr / HC ClawA1M.cs:149-166）：严格 <，平局取表内先者；
// 缺省 [0x01,0xFA]。真机 258V fw=0x230(560) → 最近 0x219(537) → [0x02,0x4A]。
static void msiLedResolveAddr(ULONG firmware, BYTE& add1, BYTE& add2) {
    add1 = 0x01; add2 = 0xFA;
    long best = -1;
    for (const MsiLedFwEntry& e : kMsiLedFwTable) {
        const long a = static_cast<long>(firmware);
        const long b = static_cast<long>(e.firmware);
        const long dist = a > b ? a - b : b - a;
        if (best < 0 || dist < best) { best = dist; add1 = e.add1; add2 = e.add2; }
    }
}

// 27B 色区（HC GetRGB）：i<4 用副色（secondary），i>=4 用主色（main）。
// solid → 主色==副色（全主色）；ambilight → 主/副分区。
static std::vector<BYTE> msiLedZones(BYTE mr, BYTE mg, BYTE mb,
                                     BYTE sr, BYTE sg, BYTE sb) {
    std::vector<BYTE> z(static_cast<size_t>(kMsiLedZoneCount) * 3, 0);
    for (int i = 0; i < kMsiLedZoneCount; ++i) {
        const bool second = i < 4;
        z[static_cast<size_t>(i) * 3 + 0] = second ? sr : mr;
        z[static_cast<size_t>(i) * 3 + 1] = second ? sg : mg;
        z[static_cast<size_t>(i) * 3 + 2] = second ? sb : mb;
    }
    return z;
}

// CTW BuildBlock：64B，[8]=32、[9]=0、[10]=mode、[11]=9、[12]=speed、
// [13]=brightness，27B 色区 @offset14。
static void msiLedBuildBlock(BYTE* out, BYTE add1, BYTE add2, BYTE mode, BYTE speed,
                             int brightness, const std::vector<BYTE>& zones) {
    std::fill(out, out + 64, 0);
    out[0] = 15; out[3] = 60; out[4] = 33; out[5] = 1; out[6] = add1; out[7] = add2;
    out[8] = 32; out[9] = 0; out[10] = mode; out[11] = 9; out[12] = speed;
    out[13] = static_cast<BYTE>(std::clamp(brightness, 0, 100));
    std::copy(zones.begin(),
              zones.begin() + std::min<size_t>(zones.size(), 27), out + 14);
}

// CTW BuildRawBlock：64B，[8]=payload.size()，payload @offset9。
static void msiLedBuildRawBlock(BYTE* out, BYTE add1, BYTE add2,
                                const std::vector<BYTE>& payload) {
    std::fill(out, out + 64, 0);
    out[0] = 15; out[3] = 60; out[4] = 33; out[5] = 1; out[6] = add1; out[7] = add2;
    out[8] = static_cast<BYTE>(payload.size());
    std::copy(payload.begin(), payload.end(), out + 9);
}

// MSI Claw 灯光应用：仅 solid / ambilight（HC ClawA1M.SetLedColor:801-819 /
// ymccDeviceClassLedEffects）。modeByte=1（LedEffectMode.Static）、speedByte=3
// （SpeedByteFor(Static,*)）。off → 黑色 solid + brightness 0（HC
// DynamicLightingManager turn-off 分支同构）。
static json msiClawApplyLed(bool enabled, const std::string& mode,
                            BYTE r1, BYTE g1, BYTE b1,
                            BYTE r2, BYTE g2, BYTE b2, int brightness) {
    if (enabled && mode != "solid" && mode != "ambilight")
        return json{{"ok", false}, {"reason", "invalid-mode"},
                    {"backend", "msi-claw-native-hid"}};

    MsiClawHidDiag diag;
    const HANDLE handle = msiClawOpenCommandHid(diag);
    if (handle == INVALID_HANDLE_VALUE)
        return json{{"ok", false}, {"reason", "msi-command-hid-unavailable"},
                    {"backend", "msi-claw-native-hid"},
                    {"deviceFound", diag.deviceFound},
                    {"devicesScanned", diag.devicesScanned},
                    {"vendorMatches", diag.vendorMatches},
                    {"openFailures", diag.openFailures},
                    {"openError", static_cast<unsigned long long>(diag.lastError)}};

    BYTE add1 = 0x01, add2 = 0xFA;
    msiLedResolveAddr(diag.firmware, add1, add2);

    // off → 黑色 solid（HC turn-off 亦走 brightness=0）。
    const BYTE mr = enabled ? r1 : 0, mg = enabled ? g1 : 0, mb = enabled ? b1 : 0;
    BYTE sr = enabled ? r2 : 0, sg = enabled ? g2 : 0, sb = enabled ? b2 : 0;
    if (!enabled || mode == "solid") { sr = mr; sg = mg; sb = mb; }
    const std::vector<BYTE> zones = msiLedZones(mr, mg, mb, sr, sg, sb);

    const BYTE modeByte = 1;   // LedEffectMode.Static
    const BYTE speedByte = 3;  // SpeedByteFor(Static, *)
    const int level = enabled ? std::clamp(brightness, 0, 100) : 0;

    const int num = (static_cast<int>(add1) << 8) | static_cast<int>(add2);
    std::vector<BYTE> frames;
    frames.reserve(4 * 64);
    const auto appendFrame = [&frames](const BYTE* f) {
        frames.insert(frames.end(), f, f + 64);
    };
    BYTE block[64];
    msiLedBuildBlock(block, add1, add2, modeByte, speedByte, level, zones);
    appendFrame(block);
    for (int offset : kMsiLedRawOffsets) {
        BYTE raw[64];
        const int addr = num + offset;
        msiLedBuildRawBlock(raw, static_cast<BYTE>((addr >> 8) & 0xFF),
                            static_cast<BYTE>(addr & 0xFF), zones);
        appendFrame(raw);
    }

    bool ok = true;
    DWORD written = 0;
    DWORD lastError = 0;
    int framesWritten = 0;
    for (size_t i = 0; i < frames.size(); i += 64) {
        const MsiClawWriteResult wr = msiClawWriteFrame(handle, frames.data() + i, 64);
        written = wr.written;
        if (!wr.ok) { ok = false; lastError = wr.lastError; break; }
        ++framesWritten;
    }
    CloseHandle(handle);

    appendNativeLifecycleLog("msi-claw-led", {
        {"enabled", enabled}, {"mode", mode}, {"brightness", level},
        {"add1", static_cast<int>(add1)}, {"add2", static_cast<int>(add2)},
        {"firmware", static_cast<unsigned long long>(diag.firmware)},
        {"ok", ok}, {"framesWritten", framesWritten},
        {"written", static_cast<unsigned long long>(written)},
        {"writeError", static_cast<unsigned long long>(lastError)},
        {"policy", "ctw-msiclawledcontroller-trysetzoneseffect"}
    });
    return json{{"ok", ok},
                {"action", enabled ? "color" : "off"},
                {"effectApplied", ok},
                {"brightnessApplied", ok},
                {"mode", mode},
                {"backend", "msi-claw-native-hid"},
                {"framesWritten", framesWritten}};
}

// A test pulse is stopped 125 ms after the newest request (HC Rumble default
// delay). A later request supersedes the earlier one.
static std::atomic<unsigned long long> g_rogVibratePulseGen{0};

static void reg_gamepad_feedback() {
    // HC ControllerPage semantics: Rumble(LargeMotor, SmallMotor) with the
    // VibrationStrength multiplier; lighting follows device DynamicLighting
    // capabilities (ROG Ally: Solid / Breathing / Rainbow / Wheel / Ambilight
    // plus brightness).
    // L2 文件扳机版取代 IPC 版（2026-09-17 用户裁决）：掌机上没有 F12/DevTools
    // Console、前端也没有既有重建入口，原 debug.recreateTargetOnce IPC 已作废
    // ——现由 inputHostConsumeDebugRecreateFlag() 承担（bus tick 1s 节拍 +
    // %LOCALAPPDATA%\YeManCC\debug-recreate-once.flag，pendingDelete）。
    ipc_on("gamepad.feedbackCapabilities", [](const json&) -> json {
        // HC DevicePage gates each lighting control by the device's static
        // capability bits (DynamicLighting / DynamicLightingBrightness plus
        // the DynamicLightingCapabilities LEDLevel set). Two layers are kept
        // apart so the reason stays truthful per machine:
        //   1) familySupportsLighting  — HC 机型库能力位。7.52 P1-T4 起改按
        //      deviceClass 精确判定（ymccDeviceClassSupportsLighting），
        //      family 包装仅兼容 selftest。
        //   2) lightingBackendImplemented — YMCC 实际实现的灯光后端（仅 ROG Aura）
        // The UI grants a panel only when both hold; machines the library says
        // can do lights but whose backend is unimplemented get an explicit
        // backend-not-implemented reason instead of a false "machine-unsupported".
        const std::string& fbDeviceClass = g_machineIdentity.deviceClass;
        const bool familySupportsLighting = ymccDeviceClassSupportsLighting(fbDeviceClass);
        // L1 方案 B（2026-09-16）：后端判定扩展——ROG 走 Aura（内部句柄）；
        // 非 ROG 且能力表命中时经 YeManLightSetter 直驱 HC（子进程在位即
        // 视为后端可用，实际结果由 gamepad.setLed 回执体现）。
        const bool lightSetterPresent =
            GetFileAttributesW(kLightSetterExe.c_str()) != INVALID_FILE_ATTRIBUTES;
        // MSI Claw 原生 HID 后端（方案 A，2026-09-29）：不依赖子进程/exe。
        const bool msiNativeLighting =
            g_machineIdentity.family == YmccFamily::MsiClaw && familySupportsLighting;
        const bool lightingBackendImplemented =
            machineIsRogAllyFamily() || msiNativeLighting || lightSetterPresent;
        const bool rogLightingFamily = familySupportsLighting && lightingBackendImplemented;
        const bool ledAvailable = rogLightingFamily &&
            (machineIsRogAllyFamily() ? g_rog.auraControl != INVALID_HANDLE_VALUE
                                      : (msiNativeLighting || lightSetterPresent));
        const bool brightnessAvailable = rogLightingFamily;
        const char* lightingBackend = machineIsRogAllyFamily() ? "rog-aura"
            : msiNativeLighting ? "msi-claw-native-hid"
            : lightSetterPresent ? "hc-light-setter" : "none";
        // HC DeviceCapabilities.DynamicLightingSecondLEDColor gates the
        // secondary color picker (DevicePage.xaml SecondColorPickerCard); ROG
        // has no such bit, so the UI hides "副颜色" for the ROG backend.
        const bool supportsSecondColor = ymccDeviceClassSupportsSecondColor(fbDeviceClass);
        // HC DynamicLightingCapabilities LEDLevel set per device class (see
        // ymccDeviceClassLedEffects). Only the ROG backend (lighting backend
        // implemented) actually drives the device here; other capable families
        // report their HC mode list so the UI dropdown stays aligned with the
        // machine library even before a backend lands. Uncapable families get
        // an empty list (fail-closed): no dropdown entries, no wrong modes.
        json ledEffects = json::array();
        if (rogLightingFamily) {
            for (const std::string& effect : ymccDeviceClassLedEffects(fbDeviceClass))
                ledEffects.push_back(effect);
        }
        const bool physicalConnected = g_xinputConnectedMask != 0;
        // GP-MSIG3E-3-R2（E4）：震动能力与后端**共用**当前受管主源记录。MSI DInput 主源
        // （1902/MI_00&COL01）已绑定时，主源就是这个实体接口，不应只因没有 XI 槽而报整机
        // 无震动——震动发向 MSI DInput 实体 HID 后端，而非自家虚拟 XInput 槽。
        HidHideMsiMainSourceRecord fbMsiRecord;
        const bool msiDinputFeedbackOwner = msiDinputManagedMainSourceActive(fbMsiRecord);
        const char* vibrationBackend = msiDinputFeedbackOwner ? "msi-dinput-hid"
            : (physicalConnected ? "xinput" : "none");
        const bool vibrationAvailable = msiDinputFeedbackOwner || physicalConnected;
        json result = {
            {"ledAvailable", ledAvailable},
            {"brightnessAvailable", brightnessAvailable},
            {"ledEffects", ledEffects},
            {"supportsSecondColor", supportsSecondColor},
            {"vibrationAvailable", vibrationAvailable},
            {"vibrationBackend", vibrationBackend},
            // S0 第 1 条（write ≠ verified）：MSI DInput 后端本机无回读路径 ⇒ 诚实标注
            // "未现场验证"，不以 UI 假绿替代。
            {"vibrationVerified", msiDinputFeedbackOwner ? false : physicalConnected},
            {"physicalPrimarySlot", physicalConnected ? static_cast<int>(g_xinputPrimarySlot) : -1},
            {"familySupportsLighting", familySupportsLighting},
            {"lightingBackendImplemented", lightingBackendImplemented},
            {"machineFamily", ymccFamilyName(g_machineIdentity.family)},
            // Diagnostics: receipts for the feedback page, never user-visible
            // claims. They let a support run report the exact unavailable cause.
            {"ledDiagnostics", {
                {"controlOpen", g_rog.auraControl != INVALID_HANDLE_VALUE},
                {"auraFeatureLen", static_cast<int>(g_rog.auraFeatureLen)},
                {"familyCapable", rogLightingFamily},
                {"familySupportsLighting", familySupportsLighting},
                {"backendImplemented", lightingBackendImplemented},
                {"lightSetterPresent", lightSetterPresent},
                {"msiNativeLighting", msiNativeLighting},
                {"lightingBackend", lightingBackend},
                {"identityMatched", g_rog.identityMatched},
                {"productId", g_rog.productId ? static_cast<int>(g_rog.productId) : 0},
                {"featureLen", static_cast<int>(g_rog.featureLen)},
                {"suppressed", g_rog.suppressed}
            }},
            {"vibrationDiagnostics", {
                {"connectedMask", static_cast<int>(g_xinputConnectedMask)},
                {"admittedMask", static_cast<int>(g_xinputAdmittedMask)},
                {"sourceLocked", g_xinputPhysicalSourceLocked},
                {"primarySlot", static_cast<int>(g_xinputPrimarySlot)},
                {"backend", vibrationBackend},
                {"msiDinputManaged", msiDinputFeedbackOwner},
                {"msiDinputGeneration", static_cast<unsigned long long>(fbMsiRecord.generation)},
                {"msiDinputInterfacePath", fbMsiRecord.interfacePath}
            }}
        };
        if (!ledAvailable)
            result["ledReason"] = !familySupportsLighting ? "machine-unsupported"
                : !lightingBackendImplemented ? "backend-not-implemented"
                : g_rog.auraControl == INVALID_HANDLE_VALUE ? "rog-hid-control-not-open" : "rog-hid-not-matched";
        else
            result["ledReason"] = "ok";
        if (msiDinputFeedbackOwner)
            result["vibrationReason"] = "ok";
        else if (!physicalConnected)
            result["vibrationReason"] = "no-xinput-slots";
        else
            result["vibrationReason"] = "ok";
        // Diagnostic receipt for the feedback page probe: capture exactly what
        // the renderer receives so a "still-locked" report can be traced to
        // native state or the frontend snapshot without guesswork.
        appendNativeLifecycleLog("gamepad.feedbackCaps", {
            {"ledAvailable", ledAvailable},
            {"vibrationAvailable", vibrationAvailable},
            {"vibrationBackend", vibrationBackend},
            {"vibrationVerified", msiDinputFeedbackOwner ? false : physicalConnected},
            {"msiDinputManaged", msiDinputFeedbackOwner},
            {"physicalPrimarySlot", physicalConnected ? static_cast<int>(g_xinputPrimarySlot) : -1},
            {"xinputConnectedMask", static_cast<int>(g_xinputConnectedMask)},
            {"xinputAdmittedMask", static_cast<int>(g_xinputAdmittedMask)},
            {"xinputSourceLocked", g_xinputPhysicalSourceLocked},
            {"rogControlOpen", g_rog.control != INVALID_HANDLE_VALUE},
            {"rogAuraControlOpen", g_rog.auraControl != INVALID_HANDLE_VALUE},
            {"rogLightingFamily", rogLightingFamily},
            {"lightingBackendImplemented", lightingBackendImplemented},
            {"lightingBackend", lightingBackend},
            {"msiNativeLighting", msiNativeLighting},
            {"lightSetterPresent", lightSetterPresent},
            {"machineFamily", ymccFamilyName(g_machineIdentity.family)},
            {"rogIdentityMatched", g_rog.identityMatched},
        });
        return result;
    });

    ipc_on("gamepad.setLed", [](const json& a) -> json {
        const bool enabled = a.value("enabled", true);
        const std::string mode = a.value("mode", std::string{"solid"});
        const int speed = std::clamp(a.value("speed", 65), 0, 100);
        const int brightness = std::clamp(a.value("brightness", 100), 0, 100);
        // Receipt for every setLed outcome — including early returns such as
        // the power-transition gate — merged into the shared
        // native-lifecycle.log stream (same channel as feedbackCaps/vibrate).
        const auto receipt = [&](const json& body) -> json {
            appendNativeLifecycleLog("gamepad-setLed", {
                {"enabled", enabled}, {"mode", mode}, {"speed", speed},
                {"brightness", brightness},
                {"ok", body.value("ok", false)},
                {"effectApplied", body.value("effectApplied", false)},
                {"brightnessApplied", body.value("brightnessApplied", false)},
                {"reason", body.value("reason", std::string{})},
                {"backend", body.value("backend", std::string{})},
                {"controlOpen", g_rog.auraControl != INVALID_HANDLE_VALUE},
                {"auraFeatureLen", static_cast<int>(g_rog.auraFeatureLen)}
            });
            return body;
        };
        if (!hardwareWriteAllowed())
            return receipt(json{{"ok", false}, {"reason", "power-transition"}});
        BYTE r1 = 0, g1 = 0, b1 = 0, r2 = 0, g2 = 0, b2 = 0;
        if (!parseRgbHex(a.value("color", std::string{"#2ea6ff"}), r1, g1, b1) ||
            !parseRgbHex(a.value("color2", std::string{"#9d7cff"}), r2, g2, b2))
            return receipt(json{{"ok", false}, {"reason", "invalid-color"}});

        // ── 非 ROG 机型灯光分流（无 Aura 句柄 + deviceClass 有灯光能力）──
        // MSI Claw：内置原生 HID 后端（方案 A，移植 CTW MsiClawLedController，
        // 直写 0x0DB0 命令接口，无子进程/HidHide 依赖）。
        // 其余机能族：YeManLightSetter 一次性子进程直驱 HC 程序集（方案 B 兜底；
        // 各机型 EC/HID/USB 协议由 HC 处理）。
        if (g_rog.auraControl == INVALID_HANDLE_VALUE &&
            ymccDeviceClassSupportsLighting(g_machineIdentity.deviceClass) &&
            !machineIsRogAllyFamily()) {
            if (g_machineIdentity.family == YmccFamily::MsiClaw)
                return receipt(msiClawApplyLed(enabled, mode, r1, g1, b1, r2, g2, b2,
                                               brightness));
            return receipt(ymccLightSetterApply(enabled, mode, r1, g1, b1, r2, g2, b2,
                                                speed, brightness));
        }

        if (g_rog.auraControl == INVALID_HANDLE_VALUE)
            return receipt(json{{"ok", false}, {"reason", "aura-device-unavailable"}});

        if (!enabled) {
            // HC DynamicLightingManager.UpdateLED() turn-off branch
            // (Managers/DynamicLightingManager.cs:305-310): only when the
            // LEDSettingsEnabled switch is off — SetLedStatus(false),
            // SetLedBrightness(0) and SetLedColor(Black, Black, SolidColor).
            // 0% brightness is NOT an off switch in HC: with the toggle on,
            // UpdateLED still applies the effect and just writes brightness 0
            // (ROG SetLedBrightness range 0..3, 0 = off). The explicit off path
            // must write the brightness-0 feature AND a black solid frame.
            const bool brightnessOff = rogAuraSetBrightness(0);
            const bool blackApplied = rogAuraApplyColor(RogAuraMode::Solid, 0, 0, 0, 0, 0, 0, 0);
            return receipt(json{{"ok", brightnessOff && blackApplied}, {"applied", "off"},
                {"brightnessApplied", brightnessOff}, {"effectApplied", blackApplied}});
        }

        bool effectApplied = false;
        if (mode == "ambilight") {
            // HC ROGAlly Ambilight = screen-capture driven left/right colors
            // (DynamicLightingManager). YMCC renders a static two-zone split.
            effectApplied = rogAuraApplyAmbilight(r1, g1, b1, r2, g2, b2);
        } else {
            // HC ROGAlly has no DynamicLightingSecondLEDColor capability, so
            // LEDUseSecondColor is hidden/False and SetLedColor receives
            // (Main, Main, ...): the secondary color is the main color. Mirror
            // that for solid/breathing/rainbow/wheel instead of emitting the
            // UI color2 as a distinct second color.
            const BYTE cr = r1, cg = g1, cb = b1;
            if (mode == "solid") {
                effectApplied = rogAuraApplyColor(RogAuraMode::Solid, cr, cg, cb, cr, cg, cb, speed);
            } else if (mode == "breathing") {
                effectApplied = rogAuraApplyColor(RogAuraMode::Breathing, cr, cg, cb, cr, cg, cb, speed);
            } else if (mode == "rainbow") {
                effectApplied = rogAuraApplyColor(RogAuraMode::Rainbow, cr, cg, cb, cr, cg, cb, speed);
            } else if (mode == "wheel") {
                effectApplied = rogAuraApplyColor(RogAuraMode::Wheel, cr, cg, cb, cr, cg, cb, speed);
            } else {
                return receipt(json{{"ok", false}, {"reason", "invalid-mode"}});
            }
        }
        const bool brightnessApplied = rogAuraSetBrightness(brightness);
        return receipt(json{{"ok", effectApplied && brightnessApplied}, {"effectApplied", effectApplied},
                    {"brightnessApplied", brightnessApplied}, {"mode", mode}});
    });

    ipc_on("gamepad.vibrate", [](const json& a) -> json {
        if (!hardwareWriteAllowed())
            return json{{"ok", false}, {"reason", "power-transition"}};
        const int strength = std::clamp(a.value("strength", 70), 0, 100);
        // GP-MSIG3E-3-R2（E4）：MSI DInput 实体后端优先。受管主源有效 ⇒ 主源就是 MSI DInput
        // （1902/MI_00&COL01），震动必须发向该实体接口，**绝不**发向自家虚拟 XInput 槽，
        // 也不因数无 XI 槽而回落 XInput（那会重新把实体 Xbox 泄漏给 Steam）。
        HidHideMsiMainSourceRecord msiVibRecord;
        if (msiDinputManagedMainSourceActive(msiVibRecord)) {
            // 马达字节与倍率（HC 依据）：
            //   A1M（DClawController.cs:84-106）：其 RumbleThreadLoop 只发 0/193 二值化；
            //   其他已登记 Claw 按证据能力授权：线性映射 0..255。
            //   HC 的 VibrationStrength(0..1) 在本机由 strength(0..100) 承载，故不再二次相乘。
            const bool a1m = g_machineIdentity.deviceClass == "HandheldCompanion.Devices.ClawA1M";
            const int motor = a1m ? (strength > 0 ? 193 : 0) : (strength * 255 + 50) / 100;
            const MsiDinputFeedbackResult fb = msiDinputFeedbackWrite(
                static_cast<BYTE>(motor), static_cast<BYTE>(motor), a1m, "vibrate");
            // 停止：复用既有 detached 125ms 线程 + g_rogVibratePulseGen 代际拒绝（陈旧 pulse
            // 不再写停止帧），不新增长期线程。
            const unsigned long long generation = ++g_rogVibratePulseGen;
            std::thread([generation] {
                Sleep(125);
                if (g_rogVibratePulseGen.load(std::memory_order_acquire) != generation) return;
                msiDinputFeedbackStop("pulse-stop");
            }).detach();
            return json{{"ok", fb.ok}, {"backend", "msi-dinput-hid"},
                        {"managed", fb.managed}, {"attempted", fb.attempted},
                        {"motor", motor}, {"strength", strength},
                        {"written", static_cast<unsigned long long>(fb.written)},
                        {"lastError", static_cast<unsigned long long>(fb.lastError)},
                        {"fieldRumbleVerified", false}};
        }
        const DWORD slot = g_xinputPrimarySlot;
        if (slot >= 4 || (g_xinputConnectedMask & (1u << slot)) == 0)
            return json{{"ok", false}, {"reason", "no-xinput-physical-source"}, {"slot", static_cast<int>(slot)}};
        // HC XInputController.SetVibration parity: HC maps the 0..255 motor
        // byte onto the 0..65535 XInput WORD and multiplies by VibrationStrength
        // (double 0..1). 立即震动 is the full-motor HC Rumble() pulse, so the
        // slider strength must land on the full 16-bit motor range, otherwise
        // a 100% pulse reaches only ~178/65535 and is imperceptible.
        const WORD level = static_cast<WORD>((static_cast<DWORD>(strength) * 65535u) / 100u);
        XINPUT_VIBRATION pulse{};
        pulse.wLeftMotorSpeed = level;
        pulse.wRightMotorSpeed = level;
        const DWORD rc = ymccXInputSetState14(slot, &pulse);
        // Diagnostic receipt: captures the exact XInputSetState outcome so a
        // UI-side "震动失败：未知原因" can be traced to slot/mask/rc facts.
        appendNativeLifecycleLog("gamepad-vibrate", {
            {"slot", static_cast<int>(slot)},
            {"connectedMask", static_cast<int>(g_xinputConnectedMask)},
            {"admittedMask", static_cast<int>(g_xinputAdmittedMask)},
            {"primarySlot", static_cast<int>(g_xinputPrimarySlot)},
            {"strength", strength},
            {"level", static_cast<int>(level)},
            {"rc", static_cast<int>(rc)},
            {"ok", rc == ERROR_SUCCESS}
        });
        const unsigned long long generation = ++g_rogVibratePulseGen;
        std::thread([slot, generation] {
            Sleep(125);
            if (g_rogVibratePulseGen.load(std::memory_order_acquire) != generation) return;
            XINPUT_VIBRATION stop{};
            ymccXInputSetState14(slot, &stop);
        }).detach();
        return json{{"ok", rc == ERROR_SUCCESS}, {"slot", static_cast<int>(slot)},
                    {"strength", strength}, {"rc", static_cast<int>(rc)}};
    });
}

/**
 * R2（FAN-926R 唤醒租约与有界等待裁决 §4.4）：**严格白名单**的有限责任事件。
 *
 * 详细日志开关（g_fanLogEnabled）关闭时，唤醒等待这一类"谁在等、等到什么结果"的
 * 责任链不能整段消失。因此这几个事件名**免门**，并复用既有 `appendFanLifecycleLog`
 * 写入已纳入导出的 `fan-lifecycle.log`。白名单刻意极小：每个恢复等待任务只会有
 * started + 唯一终态各一条（低频），且调用方（fanDiagnostics.fanLifecycleEvidence）
 * 只投递非秘密字段。其余事件名一律**不**因本函数放行。
 */
static bool fanLifecycleEvidenceAlwaysLogged(const std::string& event) {
    if (event == "lifecycle.manual-wake-snapshot-adopted" ||
        event == "lifecycle.manual-wake-snapshot-rejected") return true;
#ifdef YMCC_FAN_LOG_TEST
    // E1b 变异反控（仅测试构建；默认 0 = 生产行为）：2 = 放宽白名单（任何事件都免门）。
    if (g_fanLogMutation == 2) return !event.empty();
#endif
    // R12 T-04/T-05：AI fan mock 的有限失败收据同样免门。事件低频（每次启动/请求至多一条），
    // details 仍经 projectFanLifecycleEvidence 有限投影（只带固定错误码 reason），因此详细
    // 日志默认关闭时"下一次失败"依然落盘可判读，而不是整段消失。其余事件名不因此放行。
    if (event == "ai.mock-start-failed" || event == "ai.mock-request-failed") return true;
    return event == "lifecycle.resume-wait-started"
        || event == "lifecycle.resume-wait-completed"
        || event == "lifecycle.resume-wait-cancelled"
        || event == "lifecycle.resume-wait-terminal-failed"
        || event == "lifecycle.resume-admission-accepting"
        || event == "lifecycle.resume-admission-rejected"
        || event == "lifecycle.resume-wait-queue-reentry"
        || event == "lifecycle.power-boundary-supersede"
        || event == "lifecycle.heartbeat-stale-success-ignored"
        || event == "lifecycle.heartbeat-stale-failure-ignored";
}

/**
 * E1b（FAN-926R 执行单 §6.1）：白名单事件的**有限字段投影**。
 *
 * 白名单只放行"事件名"，绝不能让任意 details 对象成为把秘密/超长/嵌套内容带进
 * 免门文件的通道。因此这里按固定字段表投影：只保留非秘密的 action/代际/次数/耗时/
 * 终态与短标签；字符串按上限截断；非标量（对象/数组/浮点）以 `<rejected>` 标记，
 * 其它键一律丢弃（不是"转存"）。未列入字段表的键即使值很小也不保留。
 */
static const char* const kFanLifecycleEvidenceFields[] = {
    "action", "event", "id", "reason", "detail", "state", "caller",
    "generation", "session", "deadlineMs", "probes", "elapsedMs", "intervalMs",
    "intentRevision", "currentGeneration", "currentIntentRevision",
    "ok", "retryable", "wakeContext",
};
static constexpr size_t kFanLifecycleEvidenceMaxString = 48;

static json projectFanLifecycleEvidence(const json& details) {
    json projected = json::object();
    if (!details.is_object()) return projected;
    for (const char* key : kFanLifecycleEvidenceFields) {
        const auto it = details.find(key);
        if (it == details.end()) continue;
        if (it->is_string()) {
            std::string value = it->get<std::string>();
            if (value.size() > kFanLifecycleEvidenceMaxString) value.resize(kFanLifecycleEvidenceMaxString);
            projected[key] = value;
        } else if (it->is_boolean() || it->is_number_integer()) {
            projected[key] = *it;
        } else {
            // 免门事件只携带有限非秘密标量；对象/数组/浮点一律显式拒绝，便于事后核对。
            projected[key] = "<rejected>";
        }
    }
    return projected;
}

static void writeFanDiagnosticLog(const std::string& event, const json& details) {
    if (!g_fanLogEnabled || g_fanLogFile.empty()) return;
    std::lock_guard<std::mutex> lock(g_fanLogMtx);
    auto parent = fspath::path(g_fanLogFile).parent_path();
    fspath::create_directories(parent);
    SYSTEMTIME st; GetLocalTime(&st);
    char ts[32];
    snprintf(ts, sizeof(ts), "%04d-%02d-%02dT%02d:%02d:%02d.%03d",
             st.wYear, st.wMonth, st.wDay, st.wHour, st.wMinute, st.wSecond, st.wMilliseconds);
    json line = {
        {"time", ts},
        {"event", event},
        {"details", details.is_object() ? details : json::object()},
    };
    if (g_fanLogEnabled) rotateOneLogFile(g_fanLogFile);
    std::ofstream f(g_fanLogFile, std::ios::app);
    if (f) f << line.dump() << "\n";
}

// 统一详细门联动（2026-09-17 合并批）：详细开关同时驱动 fan 诊断文件与
// FanHost runtime flag（fan-logging-enabled.flag）。状态未变化时不重复写事件；
// flag 存在性始终与门控对齐（关时清理残留，启动时同样调用）。
static void fanDiagnosticsApplyEnabled(bool enabled) {
    g_fanLogFile = yemancc_data_dir() + L"\\fan-api.log";
    fspath::create_directories(fspath::path(g_fanLogFile).parent_path());
    const std::wstring hostLoggingFlag = fan_host_state_dir() + L"\\fan-logging-enabled.flag";
    if (enabled) {
        const bool was = g_fanLogEnabled.exchange(true, std::memory_order_acq_rel);
        {
            std::ofstream flag(hostLoggingFlag, std::ios::trunc);
            if (flag) flag << "enabled";
        }
        if (!fspath::exists(hostLoggingFlag)) {
            writeFanDiagnosticLog("logging-flag-write-failed", json{{"path", W2U(hostLoggingFlag)}});
        }
        if (!was) writeFanDiagnosticLog("logging-enabled", json::object());
    } else {
        if (g_fanLogEnabled.load(std::memory_order_acquire)) {
            writeFanDiagnosticLog("logging-disabled", json::object());
        }
        g_fanLogEnabled.store(false, std::memory_order_release);
        std::error_code flagEc;
        fspath::remove(hostLoggingFlag, flagEc);
        if (flagEc) {
            writeFanDiagnosticLog("logging-flag-remove-failed", json{
                {"path", W2U(hostLoggingFlag)}, {"error", flagEc.message()}});
        }
    }
}

static bool isCoordinatorDiagnosticEvent(const std::string& event) {
    return event.rfind("coordinator.", 0) == 0
        || event.rfind("lifecycle.", 0) == 0
        || event.rfind("api.", 0) == 0;
}

static void writeCoordinatorDiagnosticLog(const std::string& event, const json& details) {
    if (!g_fanLogEnabled || !isCoordinatorDiagnosticEvent(event)) return;
    const std::wstring path = yemancc_data_dir() + L"\\hardware-coordinator.log";
    std::lock_guard<std::mutex> lock(g_fanLogMtx);
    try {
        fspath::create_directories(fspath::path(path).parent_path());
        SYSTEMTIME st; GetLocalTime(&st);
        char ts[32];
        snprintf(ts, sizeof(ts), "%04d-%02d-%02dT%02d:%02d:%02d.%03d",
                 st.wYear, st.wMonth, st.wDay, st.wHour, st.wMinute, st.wSecond, st.wMilliseconds);
        json line = {
            {"time", ts},
            {"event", event},
            {"details", details.is_object() ? details : json::object()},
            {"pid", GetCurrentProcessId()},
        };
        // 单文件 ≤5MB：旋转切分（保留 .1 旧档），避免重建去重队列覆盖首行时间。
        rotateOneLogFile(path);
        std::ifstream in(path, std::ios::binary);
        std::deque<std::string> lines;
        std::string existing;
        while (std::getline(in, existing)) {
            if (!existing.empty() && existing.back() == '\r') existing.pop_back();
            lines.push_back(std::move(existing));
            while (lines.size() > COORDINATOR_LOG_MAX_LINES - 1) lines.pop_front();
        }
        lines.push_back(line.dump());
        std::string bounded;
        for (auto it = lines.rbegin(); it != lines.rend(); ++it) {
            const size_t extra = it->size() + 1;
            if (bounded.size() + extra > COORDINATOR_LOG_MAX_BYTES) break;
            bounded.insert(0, *it + "\n");
        }
        std::ofstream out(path, std::ios::binary | std::ios::trunc);
        if (out) out.write(bounded.data(), static_cast<std::streamsize>(bounded.size()));
    } catch (...) {
        // Diagnostics must never block or change the hardware lifecycle.
    }
}

static void reg_log() {
    ipc_on("log.setFile", [](const json& a) -> json {
        auto path = a.value("path", std::string{});
        if (path.empty()) {
            // Default to data/app.log
            g_logFile = app_data_dir() + L"\\app.log";
        } else {
            g_logFile = U2W(path);
        }
        // Ensure parent directory exists
        auto parent = fspath::path(g_logFile).parent_path();
        fspath::create_directories(parent);
        return W2U(g_logFile);
    });
    ipc_on("log.write", [](const json& a) -> json {
        auto level = a.value("level", std::string{"info"});
        auto msg   = a.value("message", std::string{});
        writeLog(level, msg);
        return true;
    });
    ipc_on("log.clear", [](const json&) -> json {
        if (g_logFile.empty()) return false;
        std::ofstream f(g_logFile, std::ios::trunc);
        return f.good();
    });
    ipc_on("log.getPath", [](const json&) -> json {
        return g_logFile.empty() ? nullptr : json(W2U(g_logFile));
    });
    // 统一详细门联动（2026-09-17 合并批）：详细开关同时驱动 fan 诊断文件与
    // FanHost runtime flag（fan-logging-enabled.flag）。状态未变化时不重复写
    // 事件；flag 存在性始终与门控对齐（关时清理残留，启动时同样调用）。
    // 裁决 H5（2026-09-19）：
    //   ① **缺少 enabled 键时不得默认覆盖为 false** —— 旧实现用
    //      a.value("enabled", false)，任何不带该键的调用都会把用户刚打开的日志关掉
    //      （双权威互相覆盖的根因之一，真机旁证 logging-enabled→0.45s→logging-disabled）。
    //      缺键 = 无意见 = 纯读回，零副作用。
    //   ② 显式给出布尔时同步**统一门**（g_domainLogEnabled + domainLogsSaveConfig），
    //      使统一详细门成为唯一权威，不再与 fan 设置各写一次互相覆盖。
    ipc_on("fanLog.setEnabled", [](const json& a) -> json {
        if (a.is_object() && a.contains("enabled") && a["enabled"].is_boolean()) {
            const bool enabled = a["enabled"].get<bool>();
            g_domainLogEnabled[0].store(enabled, std::memory_order_release);
            g_domainLogEnabled[1].store(enabled, std::memory_order_release);
            domainLogsSaveConfig();
            domainLogGateRecord("fanLog.setEnabled", enabled);
            // Same authoritative detailed gate as logs.domainSetEnabled. Do not
            // leave the sensor detail mirror or the InputHost cost flag stale.
            g_sensorDetailLogging.store(sensorDetailLoggingGate(), std::memory_order_release);
            fanDiagnosticsApplyEnabled(enabled);
            inputHostCostFlagSync();
        }
        return json{{"enabled", g_fanLogEnabled.load()}, {"path", W2U(g_fanLogFile)}};
    });
    ipc_on("fanLog.write", [](const json& a) -> json {
        const auto event = a.value("event", std::string{});
        if (event.empty()) return false;
        const auto details = a.value("details", json::object());
#ifdef YMCC_FAN_LOG_TEST
        // E1b 变异反控（仅测试构建；默认 0 = 生产行为）：1 = 免门分支被移回详细日志开关之后。
        if (g_fanLogMutation == 1 && !g_fanLogEnabled) {
            if (event.empty()) return false;
            writeFanDiagnosticLog(event, details);
            writeCoordinatorDiagnosticLog(event, details);
            return true;
        }
#endif
        // R2（§4.4）：白名单有限责任证据**免门**（严格按事件名匹配；不进 fan-api.log 的
        // 普通诊断面，也不放开任何其它事件）。投递失败由调用方 fire-and-forget 承担，
        // 绝不影响睡眠/退出路径。
        if (fanLifecycleEvidenceAlwaysLogged(event)) {
            // E1b（§6.1）：白名单只放行事件名；details 必须经**有限字段投影**，不得成为
            // 任意对象/秘密/超长内容的免门通道。
#ifdef YMCC_FAN_LOG_TEST
            // 变异反控（仅测试构建）：3 = 绕过字段投影（details 直传）。
            appendFanLifecycleLog(event.c_str(),
                g_fanLogMutation == 3 ? (details.is_object() ? details : json::object())
                                      : projectFanLifecycleEvidence(details));
#else
            appendFanLifecycleLog(event.c_str(), projectFanLifecycleEvidence(details));
#endif
            return true;
        }
        if (!g_fanLogEnabled) return false;
        writeFanDiagnosticLog(event, details);
        writeCoordinatorDiagnosticLog(event, details);
        return true;
    });
    ipc_on("fanLog.getPath", [](const json&) -> json {
        return json(W2U(g_fanLogFile.empty() ? yemancc_data_dir() + L"\\fan-api.log" : g_fanLogFile));
    });
    ipc_on("fanLog.clear", [](const json&) -> json {
        const std::wstring uiPath = g_fanLogFile.empty() ? yemancc_data_dir() + L"\\fan-api.log" : g_fanLogFile;
        const std::wstring hostPath = fan_host_state_dir() + L"\\logs\\yeman-fan-host-runtime.log";
        // 裁决 H5：免门故障账本同属风扇日志，清理必须一并处理（否则"清空日志"会
        // 留下上一轮卡死态的证据，用户看到的现场与导出内容不一致）。
        const std::wstring hostFaultPath = fan_host_state_dir() + L"\\logs\\fan-host-fault.log";
        const std::wstring coordinatorPath = yemancc_data_dir() + L"\\hardware-coordinator.log";
        bool ok = true;
        {
            std::lock_guard<std::mutex> lock(g_fanLogMtx);
            for (const auto& path : { uiPath, hostPath, hostFaultPath, coordinatorPath }) {
                std::error_code existsEc;
                if (!fspath::exists(path, existsEc)) continue;
                std::ofstream file(path, std::ios::trunc);
                if (!file.good()) ok = false;
            }
        }
        return json{{"ok", ok}, {"uiPath", W2U(uiPath)}, {"hostPath", W2U(hostPath)}};
    });
    ipc_on("fanLog.export", [](const json&) -> json {
        const std::wstring uiPath = g_fanLogFile.empty() ? yemancc_data_dir() + L"\\fan-api.log" : g_fanLogFile;
        const std::wstring hostPath = fan_host_state_dir() + L"\\logs\\yeman-fan-host-runtime.log";
        // 裁决 H5：免门故障账本（fan-host-fault.log）必须在导出清单里，否则"卡死态"
        // 证据无法随导出包送出来（导出器是显式文件清单，不做目录通配）。
        const std::wstring hostFaultPath = fan_host_state_dir() + L"\\logs\\fan-host-fault.log";
        const std::wstring coordinatorPath = yemancc_data_dir() + L"\\hardware-coordinator.log";
        std::vector<std::wstring> files;
        for (const auto& path : { uiPath, hostPath, hostFaultPath, coordinatorPath }) {
            std::error_code fileEc;
            if (fspath::is_regular_file(path, fileEc)) files.push_back(path);
        }
        if (files.empty()) return json{{"ok", false}, {"reason", "暂无风扇日志"}};
        // 日志源文件仍固定保存在 %LOCALAPPDATA%\\YeManCC；压缩包按用户操作
        // 约定导出到桌面，便于直接找到并发送给开发者。
        const std::wstring exportRoot = getKnownFolder(FOLDERID_Desktop);
        if (exportRoot.empty()) throw std::runtime_error("无法定位桌面目录");
        SYSTEMTIME now{};
        GetLocalTime(&now);
        wchar_t stamp[64]{};
        swprintf_s(stamp, L"%04u%02u%02u-%02u%02u%02u-%03u",
                   now.wYear, now.wMonth, now.wDay, now.wHour, now.wMinute,
                   now.wSecond, now.wMilliseconds);
        const std::wstring zipPath = exportRoot + L"\\YeMan-fan-logs-" + stamp + L".zip";
        const TarArchiveRetryResult packed = createTarArchiveWithRetry(zipPath, files);
        if (!packed.ok) {
            return json{{"ok", false},
                        {"reason", "archive-failed-after-2-attempts"},
                        {"attempts", packed.attempts},
                        {"lastError", packed.reason},
                        {"win32Error", packed.win32Error},
                        {"cleanupOk", packed.cleanupOk}};
        }
        json names = json::array();
        for (const auto& path : files) names.push_back(W2U(fspath::path(path).filename().wstring()));
        return json{{"ok", true}, {"path", W2U(zipPath)}, {"files", names},
                    {"attempts", packed.attempts}, {"cleanupOk", packed.cleanupOk}};
    });
}

